window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0032", [{"word":"sufficient","ipa_uk":"/səˈfɪʃənt/","ipa_us":"/səˈfɪʃənt/","definition_zh":"足够的；充分的；刚好够的；（逻）充分的；（古）有能力的","definition_en":"enough for a particular purpose; adequate in quantity, quality, or degree","core_image":"水壶里的水刚好漫过杯口，不多不少，够这一路喝到营地","scene":"徒步到半山腰，背包里还有一壶水。There was sufficient water in the bottle to reach the camp, so they did not need to look for a stream.","sceneCN":"这里 sufficient 是「足够的、够用的」（第 1 个义项：数量上满足需要）；句意：壶里的水足够撑到营地，他们不必再去找溪流。图中可辨识物件：背包、水壶、山径、半山腰的岩石、远处的营地帐篷。","pos":[{"tag":"adj.","zh":"足够的；充分的；刚好够的"}],"collocations":[{"phrase":"sufficient evidence","zh":"充分的证据"},{"phrase":"sufficient funds","zh":"足够的资金"},{"phrase":"sufficient reason","zh":"充分的理由"},{"phrase":"sufficient time","zh":"足够的时间"},{"phrase":"sufficient condition","zh":"充分条件"},{"phrase":"self-sufficient","zh":"自给自足的"}],"forms":[{"label":"比较级（更多用 more 构成）","form":"more sufficient"},{"label":"最高级（更多用 most 构成）","form":"most sufficient"},{"label":"副词","form":"sufficiently"},{"label":"名词","form":"sufficiency"}],"derivatives":[{"word":"sufficiency","pos":"n.","zh":"充足；足够；自足"},{"word":"sufficiently","pos":"adv.","zh":"足够地；充分地"},{"word":"insufficient","pos":"adj.","zh":"不足的；不够的"},{"word":"insufficiency","pos":"n.","zh":"不足；缺陷"}],"senses":[{"no":"01","title":"Enough in quantity","titleCN":"数量上足够的","definition":"present in an amount that meets a need","definitionCN":"数量达到需要","example":"We have sufficient food for three days.","exampleCN":"我们的食物够吃三天。","why":"The Latin verb sufficere means 'to make up to' a mark: sub- 'up to' plus facere 'to make'. Quantity sufficient is quantity that has been made to reach the line.","whyCN":"拉丁动词 sufficere 意为“做到某个标准”：sub-“达到”加 facere“做”。数量 sufficient，就是被做到达标线的数量。"},{"no":"02","title":"Adequate in quality","titleCN":"质量上充分的","definition":"good enough in quality or degree for a purpose","definitionCN":"质量或程度上满足用途","example":"The report gives sufficient detail to reproduce the experiment.","exampleCN":"这份报告给出的细节足以复现该实验。","why":"Quality, not count, is being measured here. A short note can be sufficient if it contains what the reader needs; a long one can fail.","whyCN":"这里衡量的是质量而非数量。一封短笺若含读者所需便 sufficient；长文也可能不合格。"},{"no":"03","title":"Just enough, not ample","titleCN":"刚好够的；不宽裕的","definition":"enough but with little to spare","definitionCN":"够用但几乎没有余量","example":"They lived on a sufficient but modest income.","exampleCN":"他们靠一份刚够用却不宽裕的收入生活。","why":"Sufficient sits below ample. It marks the threshold, not the feast: the glass is full to the brim, not overflowing.","whyCN":"sufficient 位于 ample 之下。它标记的是门槛而非盛宴：杯子满到杯口，却不溢出。"},{"no":"04","title":"Legally adequate","titleCN":"法律上充分的","definition":"meeting the standard required by law or procedure","definitionCN":"达到法律或程序要求的标准","example":"The court found sufficient cause to proceed.","exampleCN":"法院认定有充分理由继续审理。","why":"Law turns 'enough' into a test: a cause, a notice, or a proof is sufficient when it crosses the threshold the statute sets.","whyCN":"法律把“够”变成一道检验：理由、通知或证据越过法条设定的门槛，才算 sufficient。"},{"no":"05","title":"Sufficient condition (logic)","titleCN":"（逻辑）充分条件","definition":"a condition whose presence guarantees the result","definitionCN":"其存在即可保证结果的条件","example":"Being a square is sufficient for being a rectangle.","exampleCN":"是正方形，就是长方形的充分条件。","why":"Logic formalizes the everyday idea: if A is enough to guarantee B, A is a sufficient condition for B. It says nothing about necessity.","whyCN":"逻辑学把日常想法形式化：若 A 足以保证 B，A 就是 B 的充分条件。它并不说明必要性。"},{"no":"06","title":"Self-sufficient","titleCN":"自给自足的","definition":"able to supply one's own needs without outside help","definitionCN":"无需外界帮助即可满足自身需要","example":"The village became self-sufficient in grain.","exampleCN":"这个村子在粮食上实现了自给自足。","why":"The compound turns the word inward: instead of enough for a task, enough for oneself. Sufficiency becomes independence.","whyCN":"复合词把词义转向内部：不再是对某项任务够用，而是对自己够用。充足由此变成独立。"},{"no":"07","title":"Capable, competent (archaic)","titleCN":"有能力的；胜任的（古义）","definition":"in older usage, fit or qualified for a role","definitionCN":"旧用法：适合或胜任某一角色","example":"a person sufficient for the office","exampleCN":"胜任该职位的人","why":"The oldest English sense is personal: a person is sufficient when qualified. Modern English keeps this only in fixed or literary phrases.","whyCN":"英语最早的一层是人：人有资格便是 sufficient。现代英语只在固定或文学短语中保留此义。"},{"no":"08","title":"Sufficient unto itself","titleCN":"自足的；无须外求的（书面）","definition":"complete in itself, needing nothing more","definitionCN":"自身完整，不再需要别的","example":"The argument is sufficient unto itself.","exampleCN":"这个论证自足成立。","why":"This literary phrase pushes sufficiency to self-containment. It is used of arguments, works, and sometimes people who need no outside validation.","whyCN":"这个书面短语把“够”推到“自足”。它用于论证、作品，有时也用于无需外界认可的人。"},{"no":"09","title":"Sufficient statistic (statistics)","titleCN":"（统计）充分统计量","definition":"a summary statistic that retains all information in a sample about a parameter","definitionCN":"保留样本中关于某参数全部信息的统计量","example":"The sample mean is a sufficient statistic for the normal mean.","exampleCN":"样本均值是正态均值的一个充分统计量。","why":"Statistics borrows the logic of 'enough': a summary is sufficient when nothing relevant is lost by discarding the raw data.","whyCN":"统计学借用了“够”的逻辑：一个摘要若丢掉原始数据也不损失相关信息，便是充分的。"}],"etymology":{"intro":{"en":"Sufficient came through Old French from Latin sufficere, literally 'to make up to' a standard. The sub- in the word is not 'below' but 'up to, in support of': what suffices has been made up to the required mark.","cn":"sufficient 经古法语来自拉丁语 sufficere，字面是“做到某个标准”。其中的 sub- 不是“在下”，而是“达到、支撑”：够用之物被做到所需刻度。"},"items":[{"era":"14C","en":"English takes the adjective from Old French sufficient, itself from Latin sufficient-, the stem of sufficiens, present participle of sufficere.","cn":"英语从古法语 sufficient 借入该形容词，后者出自拉丁语 sufficiens（sufficere 的现在分词）词干 sufficient-。"},{"era":"LATIN","en":"sufficere means 'to supply, furnish, be adequate'. It is sub- 'up to' plus facere 'to make, do': to make something up to the needed measure.","cn":"sufficere 意为“供给、提供、够用”。它由 sub-“达到”与 facere“做、造”构成：把某物做到所需分量。"},{"era":"LATIN","en":"Some dictionaries gloss the sub- here as 'under, from below', picturing support placed underneath. The two readings agree in practice: support and adequacy.","cn":"部分词典把这里的 sub- 解作“在下、从下面”，想象在底下垫起支撑。两种读法在实践上相通：支撑即够用。"},{"era":"PIE","en":"facere goes back to PIE *dhe- 'to put, set, do', the same reconstruction behind fact, effect, and defeat.","cn":"facere 可追溯到原始印欧语 *dhe-“放置、设定、做”，同一重构也见于 fact、effect、defeat。"},{"era":"15C","en":"The English sense settles into 'adequate, enough', while the older personal sense 'fit, competent' fades into archaism.","cn":"英语义项稳定为“足够的、充分的”，较早的“适合、胜任”之人义退为古语。"},{"era":"MODERN","en":"Logic and statistics give the word precise technical work: sufficient condition, sufficient statistic, sufficient evidence.","cn":"逻辑学与统计学赋予这个词精确的技术分工：充分条件、充分统计量、充分证据。"}]},"similar":{"note":{"en":"The first group shares the sufficere root and the suf- spelling; the second gathers words that also say 'enough', each with a different limit.","cn":"第一组共享 sufficere 词根与 suf- 拼写；第二组收集同样表示“够”的词，各自的边界不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"suffice","ipa":"/səˈfaɪs/","tag":"same root verb","definition":"to be enough. It is the verb that stands behind sufficient.","definitionCN":"足够；满足需要。它是 sufficient 背后的动词。"},{"word":"sufficiency","ipa":"/səˈfɪʃənsi/","tag":"derived noun","definition":"the state of being enough; also self-sufficiency.","definitionCN":"充足；自足。也指自给自足。"},{"word":"insufficient","ipa":"/ˌɪnsəˈfɪʃənt/","tag":"negated adjective","definition":"not enough for the purpose. The in- reverses sufficiency.","definitionCN":"不足以满足用途。in- 反转了“够”。"}]},{"heading":"NEAR MEANING","entries":[{"word":"adequate","ipa":"/ˈædɪkwət/","tag":"enough for a purpose","definition":"enough in quantity or quality, often just meeting a standard. It is close to sufficient but more formal about fitness.","definitionCN":"数量或质量上够用，常指刚好达标。与 sufficient 接近，但更强调“合用”。"},{"word":"enough","ipa":"/ɪˈnʌf/","tag":"plain 'enough'","definition":"the everyday word for the needed quantity. It is less formal and rarely used before a noun in modern English.","definitionCN":"表示所需数量的日常词。较不正式，现代英语中很少直接置于名词前。"},{"word":"ample","ipa":"/ˈæmpl/","tag":"more than enough","definition":"enough with room to spare. It sits above sufficient on the scale of quantity.","definitionCN":"足够且有余。在数量尺度上高于 sufficient。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: sub- 'up to' plus facere 'to make', the suffice/sufficient pair, the threshold image, and the logic and statistics terms.","cn":"真实联系：sub-“达到”加 facere“做”、suffice 与 sufficient 这对词、门槛意象，以及逻辑与统计术语。"},"normal":[{"en":"Sub- here means 'up to'. To suffice is to be made up to the line, not to overflow it.","cn":"这里的 sub- 意为“达到”。suffice 就是被做到那条线，而不是溢出线外。"},{"en":"Facere means 'make'. The same root hides in fact, effect, and defeat: all are things done.","cn":"facere 意为“做”。同一词根藏在 fact、effect、defeat 里：它们都是被做出来的事。"},{"en":"Sufficient is the threshold word. Ample is the feast; sufficient is the plate that exactly feeds you.","cn":"sufficient 是门槛词。ample 是盛宴；sufficient 是刚好喂饱你的那盘。"},{"en":"In law and logic, sufficient is a test to pass, not a feeling: sufficient cause, sufficient condition.","cn":"在法律与逻辑中，sufficient 是要通过的检验而非感觉：充分理由、充分条件。"},{"en":"Self-sufficient adds 'self' and flips the direction: enough for oneself instead of enough for a task.","cn":"self-sufficient 加上 self 并翻转方向：不是对任务够用，而是对自己够用。"}],"abstract":[{"en":"Enough is a relation to a purpose, not a property of a thing: water is sufficient only relative to a route and a thirst.","cn":"“够”是与用途的关系，不是物的属性：水只有在相对于某段路与某种口渴时才够。"},{"en":"The word hides its own measure: someone must decide what the mark is before anything can be sufficient.","cn":"这个词藏起了自己的量尺：必须先有人定下标准，某物才谈得上够。"},{"en":"Sufficiency is a discipline of limits: to ask what is enough is already to refuse the infinite.","cn":"充足是一门关于限度的修炼：问“多少才够”，本身就已经拒绝无限。"}]},"examples":[{"en":"The evidence was sufficient to convict the defendant.","cn":"证据足以给被告定罪。"},{"en":"A single example is sufficient to show the pattern.","cn":"一个例子就足以说明这个模式。"},{"en":"The farm is now self-sufficient in vegetables.","cn":"这个农场现在蔬菜自给自足。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“舒服神特”——三份饭菜下肚，舒服得神清气爽，因为刚好够吃 → sufficient 足够的","word":"sufficient"},"root":"拉丁语 sufficere“供给、够用”，由 sub-“达到、向上”+ facere“做、造”构成；facere 源于原始印欧语 *dhe-“放置、做”。","sensesIntro":{"en":"Nine senses of sufficient, all measuring a threshold. The threshold can be quantity, quality, law, logic, or the self. The word never means 'plenty'; it means 'made up to the line'.","cn":"sufficient 的九个义项都在量一条门槛。门槛可以是数量、质量、法律、逻辑或自我。这个词从不表示“丰盛”，它表示“被做到那条线”。"},"semanticMap":{"core":{"en":"CORE IMAGE: a measure filled exactly to the mark, no more.","cn":"核心意象：一个量器恰好装满到刻度，不再多。"},"chain":["MAKE UP TO","MEET THE MARK","BE ENOUGH","BE ADEQUATE IN QUALITY","PASS A FORMAL TEST","NEED NOTHING MORE"],"branches":[{"senses":"S1 · S3","en":"QUANTITY: the glass is filled to the brim, with little or nothing to spare.","cn":"数量：杯子满到杯口，几乎没有余量。"},{"senses":"S2","en":"QUALITY: a short text can satisfy a reader if it contains what is needed.","cn":"质量：短文若含所需，便能满足读者。"},{"senses":"S4 · S5 · S9","en":"FORMAL TESTS: law, logic, and statistics each define their own mark to cross.","cn":"形式检验：法律、逻辑与统计各自定义要越过的刻度。"},{"senses":"S6 · S8","en":"THE SELF: sufficiency turns inward and becomes independence or self-containment.","cn":"自我：充足转向内部，成为独立或自足。"},{"senses":"S7","en":"THE PERSON: the archaic sense asks whether a person is fit for a role.","cn":"人：古义问的是一个人是否胜任其职。"}]},"affixes":{"intro":{"en":"Sufficient is a Latin-derived adjective in -ent. English builds -ly, -ency, and the negative in-, while the base facere supplies a large family of 'doing' words.","cn":"sufficient 是带 -ent 的拉丁系形容词。英语派生 -ly、-ency 与否定 in-，词基 facere 则供应一大批“做”的词。"},"latinIntro":{"en":"Latin sufficere 'be adequate' joins sub- 'up to' and facere 'make'. The facere family includes efficient, effect, and defeat; the sufficere branch alone gives suffice, sufficiency, and insufficient.","cn":"拉丁语 sufficere“够用”结合 sub-“达到”与 facere“做”。facere 词族包括 efficient、effect、defeat；仅 sufficere 这一支就生成 suffice、sufficiency、insufficient。"},"items":[{"word":"sufficiently","structure":"sufficient + -ly (adverb)","meaning":"to an adequate degree","meaningCN":"足够地；充分地（-ly 构成副词）","example":"sufficiently clear instructions","exampleCN":"足够清楚的指示"},{"word":"sufficiency","structure":"sufficient + -ency (noun)","meaning":"the state of being enough; self-sufficiency","meaningCN":"充足；自足（-ency 构成名词）","example":"a sufficiency of food","exampleCN":"充足的食物"},{"word":"insufficient","structure":"in- + sufficient (negative)","meaning":"not enough for the purpose","meaningCN":"不足的；不够的（in- 否定）","example":"insufficient evidence","exampleCN":"证据不足"},{"word":"insufficiency","structure":"in- + sufficiency (noun)","meaning":"lack or shortage; medical inadequacy","meaningCN":"不足；机能不全（名词）","example":"renal insufficiency","exampleCN":"肾功能不全"},{"word":"suffice","structure":"from Latin sufficere (verb)","meaning":"to be enough; to satisfy","meaningCN":"足够；满足（动词）","example":"One example will suffice.","exampleCN":"一个例子就够了。"},{"word":"self-sufficient","structure":"self + sufficient (compound adj.)","meaning":"able to meet one's own needs","meaningCN":"自给自足的（复合形容词）","example":"a self-sufficient community","exampleCN":"自给自足的社区"},{"word":"efficient","structure":"ex- + facere (same root)","meaning":"producing results with little waste","meaningCN":"高效的（同根：ex-“出”+ facere“做”）","example":"an efficient engine","exampleCN":"高效的引擎"},{"word":"effect","structure":"ex- + facere (same root)","meaning":"a result produced; to bring about","meaningCN":"效果；实现（同根）","example":"cause and effect","exampleCN":"因果"},{"word":"defeat","structure":"de- + facere (same root)","meaning":"to undo or overcome; a loss","meaningCN":"击败；失败（同根：de-“去掉”+ facere“做”）","example":"defeat an enemy","exampleCN":"击败敌人"}],"latinEntries":[{"word":"sufficere","structure":"sub- 'up to' + facere 'make'","meaning":"to supply, be adequate","meaningCN":"供给；够用"},{"word":"sufficiens","structure":"present participle of sufficere","meaning":"sufficient, adequate","meaningCN":"足够的；充分的"},{"word":"facere","structure":"Latin verb","meaning":"to make, do, produce","meaningCN":"做；造；产生"},{"word":"sub","structure":"Latin preposition","meaning":"under, up to, in support of","meaningCN":"在下；达到；支撑"}]}},{"word":"summarize","ipa_uk":"/ˈsʌməraɪz/","ipa_us":"/ˈsʌməraɪz/","definition_zh":"总结；概括；概述；归纳要点；（罕）求总和","definition_en":"to state the main points of something in a short form","core_image":"把一大摞文件压成一页纸，只留下能撑住结论的几行字","scene":"会议开了两个小时，秘书把讨论写成一页纸。She had to summarize two hours of talk into one page and send it to the people who had not come.","sceneCN":"这里 summarize 是「总结、概括」（第 1 个义项：用简短形式说出要点）；句意：她要把两小时的讨论概括成一页，发给没到场的人。图中可辨识物件：长会议桌、白板、成摞文件、一页要点纸、笔记本电脑。","pos":[{"tag":"v.","zh":"总结；概括；概述"}],"collocations":[{"phrase":"summarize the findings","zh":"总结研究结果"},{"phrase":"summarize the main points","zh":"概括要点"},{"phrase":"summarize the data","zh":"汇总数据"},{"phrase":"summarize a text","zh":"概述文本"},{"phrase":"briefly summarize","zh":"简要概述"},{"phrase":"summarize the plot","zh":"概述情节"}],"forms":[{"label":"第三人称单数","form":"summarizes"},{"label":"现在分词","form":"summarizing"},{"label":"过去式/过去分词","form":"summarized"},{"label":"英式拼写","form":"summarise"}],"derivatives":[{"word":"summary","pos":"n./adj.","zh":"摘要；概要；即决的"},{"word":"summarization","pos":"n.","zh":"概括；摘要编写"},{"word":"summarizer","pos":"n.","zh":"摘要器；做总结的人"},{"word":"summarily","pos":"adv.","zh":"即刻地；草率地（同根不同义）"}],"senses":[{"no":"01","title":"Give a brief account","titleCN":"作简要叙述","definition":"to give a short account of something without every detail","definitionCN":"用简短叙述交代某事而不涉全部细节","example":"She summarized the meeting in five minutes.","exampleCN":"她用五分钟概括了会议。","why":"Summary first means the main points gathered together. The verb turns that noun into an action: to gather the heads of a long thing into a short one.","whyCN":"summary 本义是把要点聚拢。动词化后，动作就是：把长事物的各个“头”收进一个短事物。"},{"no":"02","title":"Extract the main points","titleCN":"提炼要点","definition":"to pick out and state the points that matter most","definitionCN":"挑出并说出最重要的几点","example":"Summarize the article in no more than 100 words.","exampleCN":"用不超过一百词概括这篇文章。","why":"Extraction is selective. To summarize is to decide what can be dropped without breaking the argument, which is an act of judgment, not copying.","whyCN":"提炼是选择性的。概括就是判断哪些内容删掉也不会折断论证，这是判断而非抄写。"},{"no":"03","title":"Reduce to essentials","titleCN":"化繁为简","definition":"to reduce a complex whole to its essential shape","definitionCN":"把复杂整体压缩到基本形状","example":"The model summarizes a decade of change in one graph.","exampleCN":"这个模型把十年的变化浓缩进一张图。","why":"Here the verb is nearly 'compress'. The essentials are not a sample of the details but the structure that explains them.","whyCN":"此处动词近乎“压缩”。要点不是细节的抽样，而是解释细节的结构。"},{"no":"04","title":"Summarize findings","titleCN":"汇总研究结果","definition":"to bring research results together in condensed form","definitionCN":"把研究结果以压缩形式汇合","example":"The review summarizes findings from twenty studies.","exampleCN":"这篇综述汇总了二十项研究的发现。","why":"Academic writing uses the verb for the move from many studies to one statement of what they collectively show.","whyCN":"学术写作中，该动词指从众多研究走向一句“它们 collectively 说明了什么”的动作。"},{"no":"05","title":"Write an abstract","titleCN":"写摘要","definition":"to produce the short version placed before a paper or report","definitionCN":"为论文或报告写置于篇首的短版本","example":"Authors must summarize their paper in 250 words.","exampleCN":"作者须用二百五十词为论文写摘要。","why":"An abstract is a summary with a fixed place and length. The verb names the task of fitting a whole paper into that frame.","whyCN":"abstract 是有固定位置与长度的 summary。动词命名的任务，是把整篇论文塞进那个框。"},{"no":"06","title":"Sum up an argument","titleCN":"归纳论证","definition":"to restate the premises and conclusion in compressed form","definitionCN":"以压缩形式重述前提与结论","example":"To summarize the argument: higher wages raise costs, and higher costs raise prices.","exampleCN":"概括该论证：工资上涨推高成本，成本上升又推高价格。","why":"Logic uses summary as reconstruction: the compressed form should preserve the inferential links, not just the topics.","whyCN":"逻辑学把概括当作重构：压缩后的形式应保留推理链条，而不只是话题。"},{"no":"07","title":"Summarize in a table","titleCN":"以表格汇总","definition":"to present condensed information as a table or chart","definitionCN":"把压缩后的信息以表格或图表呈现","example":"Table 2 summarizes the demographic data.","exampleCN":"表 2 汇总了人口数据。","why":"Visual summary swaps prose for rows and columns. The verb still means 'make short', but the short form is spatial rather than verbal.","whyCN":"视觉化汇总用行列取代散文。动词仍指“变短”，只是短形式是空间的而非文字的。"},{"no":"08","title":"Summarize a plot","titleCN":"概述情节","definition":"to tell the story's main events in order and briefly","definitionCN":"按顺序简要讲述故事的主要事件","example":"The trailer summarizes the plot without spoiling the ending.","exampleCN":"预告片概述了情节，却没剧透结局。","why":"Narrative summary keeps sequence. Unlike a list of themes, it must preserve 'first this, then that', or the story collapses.","whyCN":"叙事概括保留顺序。它不同于主题清单，必须保住“先这样、后那样”，否则故事就塌了。"},{"no":"09","title":"Add up; total (rare)","titleCN":"求总和；合计（罕用）","definition":"in older or technical use, to add numbers into a total","definitionCN":"旧用法或技术用法：把数字加成总数","example":"The clerk summarized the column of figures.","exampleCN":"职员把那一列数字合计起来。","why":"This is the arithmetical seed of the word: summa is the total line under a column. Modern English usually says 'add up' or 'total'.","whyCN":"这是该词的算术种子：summa 是一列数字下方的总计行。现代英语多说 add up 或 total。"}],"etymology":{"intro":{"en":"Summarize is a nineteenth-century verb built on the noun summary, which descends from Latin summarium 'abridgment', from summa 'total, chief point'. The arithmetic image is a column of figures and the line that totals it.","cn":"summarize 是十九世纪在名词 summary 上造出的动词；summary 出自拉丁语 summarium“节本”，再出自 summa“总数、要点”。其算术意象是一列数字与末行的总计。"},"items":[{"era":"1830S","en":"The verb summarize is first recorded in English in the 1830s, formed from summary plus the productive suffix -ize.","cn":"动词 summarize 最早记录于 1830 年代，由 summary 加能产后缀 -ize 构成。"},{"era":"LATIN","en":"summarium means 'abridgment, epitome', a short work containing the summa of a longer one.","cn":"summarium 意为“节本、提要”，即含长篇之 summa 的短作。"},{"era":"LATIN","en":"summa is the noun of summus 'highest'. In accounting it is the top line, the total written above a column of figures.","cn":"summa 是 summus“最高”的名词。在记账中它是顶端一行，即写在一列数字上方的总数。"},{"era":"LATIN","en":"summus is the superlative of super 'above', so the total is literally the 'highest' figure, the one that stands over the rest.","cn":"summus 是 super“在上”的最高级，故总数字面上是“最高”的数字，站在其余之上。"},{"era":"19C","en":"The verb spreads with academic, legal, and business writing, where long material must be reduced to a page.","cn":"该动词随学术、法律与商业写作扩散，这些场景都要求把长材料压成一页。"},{"era":"MODERN","en":"American English prefers -ize; British English accepts both summarise and summarize, with -ise common in general prose.","cn":"美式英语偏好 -ize；英式英语 summarise 与 summarize 并用，一般散文中 -ise 常见。"}]},"similar":{"note":{"en":"The first group is the same summa family seen from noun, process, and adverb; the second is verbs that also shorten content but with different methods.","cn":"第一组是同一 summa 词族的名词、过程与副词三面；第二组是同样压缩内容、但方法不同的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"summary","ipa":"/ˈsʌməri/","tag":"base noun/adjective","definition":"a short statement of main points; also 'immediate' in legal use.","definitionCN":"要点的简短陈述；法律用语中也指“即刻的”。"},{"word":"summarization","ipa":"/ˌsʌməraɪˈzeɪʃn/","tag":"process noun","definition":"the act or result of summarizing. It adds -ization to the verb.","definitionCN":"概括的行为或结果。动词加 -ization。"},{"word":"summarily","ipa":"/səˈmerəli/","tag":"adverb","definition":"immediately and without ceremony, as in summary dismissal. It is not the adverb of 'summary' in the digest sense.","definitionCN":"即刻且不循仪式，如即决解雇。它不是“摘要”义的副词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"condense","ipa":"/kənˈdens/","tag":"compress","definition":"to make shorter by removing what is not needed, often keeping the flow. It stresses compression more than selection.","definitionCN":"删去不需要的部分而变短，常保留行文。它更强调压缩而非挑选。"},{"word":"outline","ipa":"/ˈaʊtlaɪn/","tag":"skeletal account","definition":"to give only the frame or headings of a subject. It is shorter and less connected than a summary.","definitionCN":"只给框架或标题。它比 summary 更短、连接更少。"},{"word":"recap","ipa":"/ˈriːkæp/","tag":"informal review","definition":"to restate the main points of something just finished. It is conversational and backward-looking.","definitionCN":"重述刚结束之事的主要点。口语化，且回望已完成之事。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: summa as the total line, the summary/summarize pair, the -ize suffix, and the difference between selecting and merely shortening.","cn":"真实联系：summa 作总计行、summary 与 summarize 这对词、-ize 后缀，以及“挑选”与“单纯缩短”的区别。"},"normal":[{"en":"Summa is the total line above a column. To summarize is to write that line for a whole page or meeting.","cn":"summa 是一列数字上方的总计行。summarize 就是为一整页或一整场会议写下那一行。"},{"en":"Summary is the noun, summarize the verb, summarization the process. The -ize ending turns the thing into an action.","cn":"summary 是名词，summarize 是动词，summarization 是过程。-ize 把“物”变成“动作”。"},{"en":"Selection comes before shortening: you must know which points carry the argument before you cut.","cn":"挑选先于缩短：先知道哪些点撑住论证，才下刀。"},{"en":"A table can summarize as well as prose. The short form may be spatial, not verbal.","cn":"表格与散文一样能概括。短形式可以是空间的，而非文字的。"},{"en":"Plot summary keeps order; argument summary keeps inference. Each genre has its own skeleton to preserve.","cn":"情节概括保留顺序；论证概括保留推理。每种体裁都有要保住的骨架。"}],"abstract":[{"en":"A summary is a claim about relevance: it says these lines, not those, are what the whole was for.","cn":"摘要是关于相关性的主张：它说这几行、而非那些，才是整体的目的。"},{"en":"Every summary is also a loss, and the honest ones know what they have dropped.","cn":"每次概括都是一次损失，诚实的概括知道自己丢掉了什么。"},{"en":"The shorter the form, the more power it has over memory: the total line outlives the column.","cn":"形式越短，对记忆的权力越大：总计行比整列数字活得更久。"}]},"examples":[{"en":"Please summarize the report in one paragraph.","cn":"请用一段话概括这份报告。"},{"en":"The abstract summarizes the study's aims, methods, and results.","cn":"摘要概括了该研究的目的、方法与结果。"},{"en":"He summarized the argument by restating its two premises.","cn":"他通过重述两个前提来归纳该论证。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“撒么来子”——把撒出去的一大把材料“撒么”一下拢成一小把 → summarize 总结、概括","word":"summarize"},"root":"拉丁语 summa“总数、要点”（summus“最高”的名词）+ 英语动词后缀 -ize；经 summary、summarium“节本”而来。","sensesIntro":{"en":"Nine senses of summarize, all performing one reduction: a long thing becomes a short thing that still carries its weight. The reduction may be verbal, visual, numerical, or narrative.","cn":"summarize 的九个义项都执行同一种压缩：长事物变成仍能承重的短事物。压缩可以是文字的、视觉的、数字的或叙事的。"},"semanticMap":{"core":{"en":"CORE IMAGE: a column of figures reduced to its total line.","cn":"核心意象：一列数字被压缩成末行的总数。"},"chain":["GATHER THE HEADS","SELECT WHAT CARRIES WEIGHT","COMPRESS THE WHOLE","PRODUCE A SHORT FORM","FIT A FRAME (abstract, table)","KEEP THE SKELETON"],"branches":[{"senses":"S1 · S3","en":"REDUCTION: the long account becomes a short one without losing its shape.","cn":"压缩：长叙述变短，而不失其形。"},{"senses":"S2 · S6","en":"SELECTION: points and premises are chosen because they hold the argument up.","cn":"挑选：要点与前提被选中，因为它们撑住论证。"},{"senses":"S4 · S5","en":"ACADEMIC FORM: findings are pooled and a paper is fitted into an abstract.","cn":"学术形式：发现被汇合，论文被装进摘要。"},{"senses":"S7","en":"VISUAL FORM: the short version becomes rows and columns rather than sentences.","cn":"视觉形式：短版本变成行列而非句子。"},{"senses":"S8 · S9","en":"SEQUENCE AND SUM: narrative keeps order; the old arithmetic sense keeps the total.","cn":"顺序与总数：叙事保留次序；古老算术义保留总计。"}]},"affixes":{"intro":{"en":"Summarize is summary plus the verb suffix -ize, from Greek -izein through Latin -izare. The summa family also gives sum, summation, and summit, all built on 'highest'.","cn":"summarize 是 summary 加动词后缀 -ize（经拉丁 -izare 出自希腊 -izein）。summa 词族还给出 sum、summation、summit，皆建于“最高”。"},"latinIntro":{"en":"Latin summa 'total, chief point' is the feminine of summus 'highest', superlative of super 'above'. From it come summary, summarize, sum, and summit; the accounting image of the total line runs through all of them.","cn":"拉丁语 summa“总数、要点”是 summus“最高”的阴性名词，后者为 super“在上”的最高级。由此有 summary、summarize、sum、summit；总计行的记账意象贯穿其中。"},"items":[{"word":"summary","structure":"summa + -arium (noun)","meaning":"a short statement of main points","meaningCN":"摘要；概要（-arium 构成名词）","example":"a summary of the report","exampleCN":"报告摘要"},{"word":"summarization","structure":"summarize + -ation (noun)","meaning":"the act or product of summarizing","meaningCN":"概括；摘要编写（-ation 构成名词）","example":"automatic summarization","exampleCN":"自动摘要"},{"word":"summarizer","structure":"summarize + -er (agent noun)","meaning":"a person or tool that summarizes","meaningCN":"做总结的人或工具（-er 施事）","example":"a text summarizer","exampleCN":"文本摘要器"},{"word":"summarized","structure":"summarize + -ed (past participle)","meaning":"put into short form","meaningCN":"已概括的；已汇总的（过去分词）","example":"the summarized findings","exampleCN":"汇总后的发现"},{"word":"summarily","structure":"summary + -ly (adverb)","meaning":"immediately, without ceremony","meaningCN":"即刻地；草率地（副词，同根不同义）","example":"summarily dismissed","exampleCN":"被即刻解雇"},{"word":"sum","structure":"summa (noun/verb)","meaning":"the total of numbers; to add up","meaningCN":"总数；求和（同根名词/动词）","example":"the sum of the parts","exampleCN":"各部分之和"},{"word":"summation","structure":"summa + -ation (noun)","meaning":"the process of adding up; a concluding summary","meaningCN":"求和；总结（同根名词）","example":"a summation of the evidence","exampleCN":"证据的总结"},{"word":"summative","structure":"summa + -ative (adjective)","meaning":"serving to sum up, especially of assessment","meaningCN":"总结性的（同根形容词）","example":"a summative assessment","exampleCN":"总结性评价"},{"word":"summit","structure":"summus 'highest' (noun)","meaning":"the highest point; a top-level meeting","meaningCN":"顶点；峰会（同根名词）","example":"the summit of the mountain","exampleCN":"山顶"}],"latinEntries":[{"word":"summa","structure":"feminine of summus 'highest'","meaning":"total, sum, chief point","meaningCN":"总数；要点"},{"word":"summarium","structure":"from summa","meaning":"abridgment, epitome","meaningCN":"节本；提要"},{"word":"summus","structure":"superlative of super","meaning":"highest, topmost","meaningCN":"最高的；最上的"},{"word":"super","structure":"Latin preposition","meaning":"above, over","meaningCN":"在上；超过"}]}},{"word":"summary","ipa_uk":"/ˈsʌməri/","ipa_us":"/ˈsʌməri/","definition_zh":"摘要；概要；总结；（律）即决的；立即的；扼要的","definition_en":"a short statement giving the main points; (adj.) done quickly and without full procedure","core_image":"一本厚书的第一页上，用半页字把全书骨架摆出来","scene":"论文开头有一段两百词的文字。The summary set out the question, the method and the conclusion in two hundred words, so a reader could see the whole study at once.","sceneCN":"这里 summary 是「摘要、概要」（第 2 个义项：学术论文篇首的简短陈述）；句意：摘要用两百词摆出研究问题、方法和结论，读者一眼就能看到整项研究。图中可辨识物件：论文首页、摘要栏、加粗标题、参考文献、桌角咖啡杯。","pos":[{"tag":"n.","zh":"摘要；概要；总结；纪要"},{"tag":"adj.","zh":"即决的；立即的；扼要的"}],"collocations":[{"phrase":"a brief summary","zh":"简要概述"},{"phrase":"executive summary","zh":"执行摘要"},{"phrase":"summary judgment","zh":"即决判决"},{"phrase":"summary dismissal","zh":"立即解雇"},{"phrase":"in summary","zh":"总之"},{"phrase":"a summary account","zh":"扼要的叙述"}],"forms":[{"label":"复数","form":"summaries"},{"label":"动词","form":"summarize / summarise"},{"label":"副词（即决义）","form":"summarily"},{"label":"形容词用法","form":"summary report / summary trial"}],"derivatives":[{"word":"summarize","pos":"v.","zh":"总结；概括"},{"word":"summarily","pos":"adv.","zh":"即刻地；不加程序地"},{"word":"summarization","pos":"n.","zh":"概括；摘要"},{"word":"summarist","pos":"n.","zh":"摘编者（罕用）"}],"senses":[{"no":"01","title":"A short statement of main points","titleCN":"要点简述","definition":"a brief statement that gives the main points of something longer","definitionCN":"对较长内容要点的简短陈述","example":"She gave a summary of the discussion.","exampleCN":"她对讨论作了简要总结。","why":"The noun is the total line of a text: the few sentences that stand for the many. It is a thing, not the act of making it.","whyCN":"这个名词是文本的总计行：用几句话代表许多话。它是一件成品，不是制作动作。"},{"no":"02","title":"An academic abstract","titleCN":"论文摘要","definition":"the short text placed at the head of a paper or report","definitionCN":"置于论文或报告篇首的短文","example":"Read the summary before the article itself.","exampleCN":"先读摘要，再读正文。","why":"Academic publishing fixes the summary in place and length. It is a genre with rules: question, method, result, implication.","whyCN":"学术出版把 summary 固定在位置与长度上。它是有规则的文体：问题、方法、结果、意义。"},{"no":"03","title":"Minutes or recap of a meeting","titleCN":"会议纪要；回顾","definition":"a condensed record of what was said or decided","definitionCN":"对发言或决定的压缩记录","example":"The chair circulated a summary of the decisions.","exampleCN":"主席传阅了决定摘要。","why":"A meeting summary is retrospective and selective. It records decisions and owners rather than the noise of discussion.","whyCN":"会议摘要是回溯且选择性的。它记录决定与责任人，而非讨论的噪声。"},{"no":"04","title":"An abridgment (archaic)","titleCN":"节本；缩写本（旧义）","definition":"in older use, a shortened version of a book or document","definitionCN":"旧用法：书或文件的缩略本","example":"He carried a summary of the law in his pocket.","exampleCN":"他口袋里带着一本法律节本。","why":"This is the original bookish sense: a summary is itself a small book made from a large one. Modern usage prefers abridgment or digest.","whyCN":"这是最早的书籍义：summary 本身就是由大书制成的小书。现代多用 abridgment 或 digest。"},{"no":"05","title":"'In summary' as a discourse marker","titleCN":"总之（话语标记）","definition":"a phrase used to introduce a final condensed statement","definitionCN":"用于引出最后概括陈述的短语","example":"In summary, the policy failed on all three counts.","exampleCN":"总之，该政策在三个方面都失败了。","why":"The phrase signals that the speaker is closing the account. It is a doorway into the total line rather than the total line itself.","whyCN":"该短语示意说话人正在收束叙述。它是通往总计行的门，而非总计行本身。"},{"no":"06","title":"Summary judgment (law)","titleCN":"（律）即决判决","definition":"a judgment given without a full trial when facts are not disputed","definitionCN":"事实无争议时不经完整审理而作出的判决","example":"The court granted summary judgment for the plaintiff.","exampleCN":"法院支持原告，作出即决判决。","why":"Here summary is an adjective meaning 'short in procedure'. The court decides on the papers because a trial would add nothing.","whyCN":"此处 summary 是形容词，意为“程序上从简”。法院凭书面材料裁决，因为开庭不会增加什么。"},{"no":"07","title":"Summary dismissal","titleCN":"立即解雇","definition":"dismissal without notice or full process","definitionCN":"不通知或不经完整程序的解雇","example":"He was given summary dismissal for breach of contract.","exampleCN":"他因违约被立即解雇。","why":"The adjective shifts from shortening documents to shortening procedure. What is summary is done at once, without the usual steps.","whyCN":"形容词从“缩短文件”转向“缩短程序”。summary 之事即刻完成，不经通常步骤。"},{"no":"08","title":"Brief, condensed (adj.)","titleCN":"扼要的；概括的","definition":"of an account, giving only the main points","definitionCN":"叙述只给要点的","example":"a summary account of the voyage","exampleCN":"对航程的扼要叙述","why":"The adjective describes the form of an account. It can be neutral ('brief') or faintly negative ('too summary', i.e. too shallow).","whyCN":"该形容词描述叙述的形式。它可中性（“简短”），也可略带贬义（“过于概括”，即太浅）。"},{"no":"09","title":"A collection of digests","titleCN":"汇编；摘要集","definition":"a volume or set of condensed versions of longer works","definitionCN":"长篇作品的缩略本汇集","example":"a summary of cases for students","exampleCN":"供学生用的判例摘要集","why":"In publishing, the plural summaries can name a genre: a shelf of digests. The whole is made of shortened parts.","whyCN":"出版业中，复数 summaries 可指一种体裁：一整架节本。整体由缩短的部分组成。"}],"etymology":{"intro":{"en":"Summary entered English through Anglo-French and Latin summarium, 'abridgment', from summa 'total, chief point'. The image is the total written above a column: the short form that stands for the whole.","cn":"summary 经盎格鲁-法语与拉丁语 summarium“节本”进入英语，再出自 summa“总数、要点”。意象是写在一列数字上方的总数：以短形式代表整体。"},"items":[{"era":"14C","en":"The noun is recorded in Middle English as a digest or abridgment, often of a book of law or theology.","cn":"该名词在中古英语中记录为“节本、提要”，常指法律或神学书籍的缩本。"},{"era":"LATIN","en":"summarium is a noun from summa, meaning an epitome: a small work that contains the main points of a large one.","cn":"summarium 是出自 summa 的名词，意为提要：含长篇要点的短作。"},{"era":"LATIN","en":"summa is the feminine of summus 'highest', used in accounting for the total line above a column of figures.","cn":"summa 是 summus“最高”的阴性形式，记账中用来指一列数字上方的总计行。"},{"era":"LATIN","en":"The adjective came later through legal French: a summary trial or judgment is one shortened in procedure.","cn":"形容词后来经法律法语而来：summary trial 或 judgment 指程序从简的审理或判决。"},{"era":"16C","en":"Legal English fixes summary in phrases such as summary conviction and summary dismissal, where speed replaces fullness.","cn":"法律英语把 summary 固定在 summary conviction、summary dismissal 等短语中，以速度取代完整。"},{"era":"MODERN","en":"Modern usage splits cleanly: the noun is a digest; the adjective means immediate or procedure-light, not 'concise'.","cn":"现代用法清楚分工：名词是摘要；形容词指即刻或程序从简，而非“简洁”。"}]},"similar":{"note":{"en":"The first group is the summa family and its spelling; the second is other names for a short version, each with a different use.","cn":"第一组是 summa 词族及拼写；第二组是短版本的其他名称，用途各异。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"summarize","ipa":"/ˈsʌməraɪz/","tag":"verb","definition":"to make a summary; the action behind the noun.","definitionCN":"作摘要；名词背后的动作。"},{"word":"summarily","ipa":"/səˈmerəli/","tag":"adverb","definition":"immediately, without ceremony, from the legal adjective.","definitionCN":"即刻地、不循仪式地，出自法律形容词。"},{"word":"summation","ipa":"/ˌsʌˈmeɪʃn/","tag":"noun","definition":"the adding up of parts; a concluding summary.","definitionCN":"部分相加；总结性概述。"}]},{"heading":"NEAR MEANING","entries":[{"word":"abstract","ipa":"/ˈæbstrækt/","tag":"academic summary","definition":"the summary at the head of a scholarly paper. It is narrower than summary and tied to publication.","definitionCN":"学术论文篇首的摘要。比 summary 窄，且绑定出版场景。"},{"word":"digest","ipa":"/ˈdaɪdʒest/","tag":"condensed collection","definition":"a compact collection of longer material, often arranged for reading.","definitionCN":"较长材料的紧凑汇集，常编排成读物。"},{"word":"outline","ipa":"/ˈaʊtlaɪn/","tag":"skeleton","definition":"the bare frame of a subject, with headings rather than connected prose.","definitionCN":"主题的裸骨架，用标题而非连贯散文。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: summa as the total line, the noun/adjective split, and the legal phrases that keep the 'immediate' sense alive.","cn":"真实联系：summa 作总计行、名词与形容词的分工，以及让“即刻”义存活的法定短语。"},"normal":[{"en":"The noun summary is the total line; the verb summarize is writing it.","cn":"名词 summary 是总计行；动词 summarize 是写下它。"},{"en":"An abstract is a summary with a fixed slot: same skill, narrower genre.","cn":"abstract 是放进固定格子的 summary：同样的手艺，更窄的体裁。"},{"en":"The adjective does not mean 'short in words'. It means 'short in procedure': summary judgment, summary dismissal.","cn":"形容词不表示“字数少”，而表示“程序短”：即决判决、立即解雇。"},{"en":"'In summary' is a signpost, not a content word. It tells the listener the account is closing.","cn":"in summary 是路标，不是实词。它告诉听者叙述正在收束。"},{"en":"Summaries plural can name a genre: a shelf of digests, each standing for a larger work.","cn":"复数 summaries 可指一种体裁：一整架节本，每一本代表一部更大的作品。"}],"abstract":[{"en":"A summary is a small object with a large claim: it says it can stand in for the whole.","cn":"摘要是一件小物，却有大主张：它说自己能代表整体。"},{"en":"The legal adjective reveals the word's hidden axis: not length of text but length of process.","cn":"法律形容词揭示了这个词的隐藏轴：不是文本的长度，而是过程的长度。"},{"en":"Every age rewrites its summaries; the total line is always someone's judgment of what counted.","cn":"每个时代都重写自己的摘要；总计行永远是某人对“什么算数”的判断。"}]},"examples":[{"en":"The report begins with an executive summary.","cn":"报告以执行摘要开篇。"},{"en":"In summary, the experiment supports the original hypothesis.","cn":"总之，实验支持了最初的假设。"},{"en":"The company sought summary judgment on the contract claim.","cn":"公司就合同主张申请即决判决。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“撒么瑞”——把撒出去的材料“撒么”一拢，端出一份瑞气十足的概要 → summary 摘要","word":"summary"},"root":"拉丁语 summarium“节本、提要”，出自 summa“总数、要点”（summus“最高”的名词）。","sensesIntro":{"en":"Nine senses of summary: five are the noun (digest, abstract, minutes, abridgment, collection) and two are fixed phrases; two are the legal adjective meaning 'short in procedure'. The thread is the total line that stands for the whole.","cn":"summary 的九个义项：五个是名词（概要、摘要、纪要、节本、汇编），两个是固定短语；两个是法律形容词“程序从简”。线索是那条代表整体的总计行。"},"semanticMap":{"core":{"en":"CORE IMAGE: the total line written above a column, standing for everything below it.","cn":"核心意象：写在一列数字上方的总计行，代表其下全部。"},"chain":["TOTAL LINE","SHORT STATEMENT","SELECTED POINTS","FIXED GENRE (abstract, minutes)","PHRASE: IN SUMMARY","SHORTENED PROCEDURE"],"branches":[{"senses":"01 · 08","en":"THE FORM: a short account that carries the main points of a longer one.","cn":"形式：承载长篇要点的短叙述。"},{"senses":"02 · 05","en":"INSTITUTIONS OF SPEECH: an abstract and the closing phrase each place the summary in a ritual.","cn":"言语制度：摘要与收束短语都把 summary 放入某种仪式。"},{"senses":"04 · 09","en":"THE BOOK: the abridgment and the digest collection are summaries you can hold.","cn":"书：节本与摘要集是可以捧在手里的 summary。"},{"senses":"06 · 07","en":"LAW: the adjective shortens procedure, not prose: immediate judgment, immediate dismissal.","cn":"法律：形容词缩短的是程序而非文字：即决判决、立即解雇。"},{"senses":"03","en":"RECORD: the meeting summary keeps decisions rather than discussion.","cn":"记录：会议摘要保留决定而非讨论。"}]},"affixes":{"intro":{"en":"Summary is a Latin noun in -arium attached to the summa stem. Its English family runs through summarize, summarily, and summation, while sum and summit share the 'highest' image.","cn":"summary 是加在 summa 词干上的 -arium 拉丁名词。其英语词族经 summarize、summarily、summation 展开，而 sum 与 summit 共享“最高”意象。"},"latinIntro":{"en":"Latin summa 'total, chief point' gives summarium 'abridgment'. The same root yields sum, summation, and summit; the accounting total line is the ancestor of every later 'short version'.","cn":"拉丁语 summa“总数、要点”生成 summarium“节本”。同根还有 sum、summation、summit；记账的总计行是后世一切“短版本”的祖先。"},"items":[{"word":"summarize","structure":"summary + -ize (verb)","meaning":"to state the main points briefly","meaningCN":"总结；概括（-ize 构成动词）","example":"summarize the report","exampleCN":"概括报告"},{"word":"summarily","structure":"summary + -ly (adverb)","meaning":"immediately, without full process","meaningCN":"即刻地；不循程序地（副词）","example":"summarily rejected","exampleCN":"被即刻驳回"},{"word":"summarization","structure":"summarize + -ation (noun)","meaning":"the act of making a summary","meaningCN":"概括；摘要编写（名词）","example":"text summarization","exampleCN":"文本摘要"},{"word":"summarist","structure":"summary + -ist (rare noun)","meaning":"one who makes summaries","meaningCN":"摘编者（罕用名词）","example":"a summarist of chronicles","exampleCN":"编年史摘编者"},{"word":"sum","structure":"summa (noun)","meaning":"a total; an amount of money","meaningCN":"总数；金额（同根名词）","example":"a large sum","exampleCN":"一大笔钱"},{"word":"summation","structure":"summa + -ation (noun)","meaning":"the adding up; a concluding statement","meaningCN":"求和；总结（同根名词）","example":"a summation of the case","exampleCN":"案件的总结"},{"word":"summative","structure":"summa + -ative (adjective)","meaning":"serving to sum up, especially in assessment","meaningCN":"总结性的（同根形容词）","example":"summative feedback","exampleCN":"总结性反馈"},{"word":"summit","structure":"summus 'highest' (noun)","meaning":"the highest point; a leaders' meeting","meaningCN":"顶点；峰会（同根名词）","example":"reach the summit","exampleCN":"登顶"},{"word":"sumless","structure":"sum + -less (rare adjective)","meaning":"too great to be counted","meaningCN":"不可计数的（罕用）","example":"sumless wealth","exampleCN":"无法计量的财富"}],"latinEntries":[{"word":"summa","structure":"feminine of summus","meaning":"total, chief point","meaningCN":"总数；要点"},{"word":"summarium","structure":"from summa","meaning":"abridgment, epitome","meaningCN":"节本；提要"},{"word":"summus","structure":"superlative of super","meaning":"highest","meaningCN":"最高的"},{"word":"super","structure":"Latin preposition","meaning":"above","meaningCN":"在上"}]}},{"word":"supplement","ipa_uk":"/ˈsʌplɪmənt/","ipa_us":"/ˈsʌplɪmənt/","definition_zh":"补充物；增补；补剂；增刊；附录；（票价的）附加费；补充，增补","definition_en":"something added to complete or improve a thing; to add to something in order to complete it","core_image":"一只快见底的碗，再添一勺汤，刚好把这一餐补齐","scene":"医生建议他在饮食之外再补一种维生素。The doctor told him to supplement his diet with vitamin pills, because the winter sun was too weak.","sceneCN":"这里 supplement 是「补充、增补」（第 6 个义项：在原有之外再加，以补不足）；句意：医生让他在饮食之外补充维生素片，因为冬天的日照太弱。图中可辨识物件：餐盘、药瓶、维生素软胶囊、窗外的冬日阳光、医嘱单。","pos":[{"tag":"n.","zh":"补充物；补剂；增刊；附录；附加费"},{"tag":"v.","zh":"补充；增补；追加"}],"collocations":[{"phrase":"dietary supplement","zh":"膳食补充剂"},{"phrase":"supplement one's income","zh":"增加收入"},{"phrase":"a supplement to the book","zh":"书的附录"},{"phrase":"a newspaper supplement","zh":"报纸增刊"},{"phrase":"supplementary angle","zh":"补角"},{"phrase":"a supplement on the fare","zh":"票价附加费"}],"forms":[{"label":"复数","form":"supplements"},{"label":"第三人称单数","form":"supplements"},{"label":"现在分词","form":"supplementing"},{"label":"过去式/过去分词","form":"supplemented"},{"label":"形容词","form":"supplementary / supplemental"}],"derivatives":[{"word":"supplementary","pos":"adj.","zh":"补充的；附加的；补角的"},{"word":"supplementation","pos":"n.","zh":"补充；增补"},{"word":"supplemental","pos":"adj.","zh":"补充的（多用于美式）"},{"word":"suppletion","pos":"n.","zh":"异干互补（语言学；同根不同义）"}],"senses":[{"no":"01","title":"Something added to complete","titleCN":"补充物；补足物","definition":"a thing added to something else to make it complete","definitionCN":"为使某物完整而添加之物","example":"A supplement to the manual covers the new software.","exampleCN":"手册的补充篇涵盖了新软件。","why":"Supplementum in Latin is 'that which fills up'. The added thing does not replace the whole; it fills the gap the whole left open.","whyCN":"拉丁语 supplementum 是“用来填满之物”。添加物不取代整体，而是填补整体留下的缺口。"},{"no":"02","title":"A dietary supplement","titleCN":"膳食补充剂","definition":"a product taken to add nutrients to the diet","definitionCN":"为膳食增加营养而服用的产品","example":"Vitamin D supplements are common in winter.","exampleCN":"冬季维生素 D 补充剂很常见。","why":"The medical sense narrows the general idea: the diet is the base, and the pill fills a nutritional gap rather than replacing food.","whyCN":"医学义收窄了一般概念：饮食是底，药片填补营养缺口，而非取代食物。"},{"no":"03","title":"A newspaper or magazine supplement","titleCN":"报纸增刊；杂志附册","definition":"a separate section or issue added to a publication","definitionCN":"随出版物附送的独立版面或专刊","example":"The Sunday paper has a travel supplement.","exampleCN":"周日报纸有一份旅游增刊。","why":"Publishing extends 'fill up' to print: the main issue is complete for its purpose, and the supplement adds a specialised area.","whyCN":"出版业把“填满”扩展到印刷品：主刊对其目的已完整，增刊再加一个专门领域。"},{"no":"04","title":"An appendix to a book","titleCN":"书的附录；补编","definition":"a section added at the end of a book for extra material","definitionCN":"书末附加额外材料的章节","example":"The appendix is a supplement to Chapter Three.","exampleCN":"附录是第三章的补充。","why":"The book's body is the whole; the supplement carries what would have broken its flow tables, documents, corrections.","whyCN":"书的正文是整体；补编承载会打断行文的内容——表格、文件、勘误。"},{"no":"05","title":"An extra charge on a fare","titleCN":"（票价的）附加费","definition":"an additional amount paid for a special service or class","definitionCN":"为特殊服务或等级另付的金额","example":"There is a supplement for travel at peak times.","exampleCN":"高峰时段出行需付附加费。","why":"Commerce makes the supplement monetary: the base fare buys the journey, the supplement buys the upgrade. The logic of 'added to complete' becomes 'added for extra'.","whyCN":"商业把补充物变成钱：基础票价买行程，附加费买升级。“为补全而加”的逻辑变成“为额外而加”。"},{"no":"06","title":"To add to something","titleCN":"补充；增补","definition":"to add something in order to improve or complete","definitionCN":"为改善或补全而添加","example":"He supplements his salary with freelance work.","exampleCN":"他用自由职业来补充薪水。","why":"As a verb the word keeps the same geometry: the base stays, and something is laid alongside it. The subject does not replace, it adds.","whyCN":"作动词时几何不变：基底保留，另加一物在旁边。主体不取代，只添加。"},{"no":"07","title":"To supplement income","titleCN":"增加收入","definition":"to earn extra money in addition to a main source","definitionCN":"在主收入之外另赚","example":"Many students supplement their grants with part-time jobs.","exampleCN":"许多学生用兼职补充助学金。","why":"Income is treated as a base that can be filled up. The supplement is not charity but an added stream, often smaller than the main one.","whyCN":"收入被当作可填补的基底。补充不是施舍，而是另加的一条水流，常小于主源。"},{"no":"08","title":"A supplementary angle (geometry)","titleCN":"补角（几何）","definition":"either of two angles whose sum is 180 degrees","definitionCN":"两角之和为 180 度时，其中任一角","example":"The supplement of 60 degrees is 120 degrees.","exampleCN":"60 度的补角是 120 度。","why":"Geometry borrows the word for the exact amount needed to complete a straight line. It is the purest case: the supplement is defined by what it makes whole.","whyCN":"几何学借这个词指补成一条直线所需的精确量。这是最纯粹的情形：补角由它所补全之物定义。"},{"no":"09","title":"A supplemental clause (law)","titleCN":"补充条款","definition":"an added clause that completes or updates an agreement","definitionCN":"补全或更新协议的附加条款","example":"The parties signed a supplement to the contract.","exampleCN":"双方签署了合同的补充协议。","why":"Legal drafting adds supplements rather than rewriting the original, so the base document and its additions must be read together.","whyCN":"法律起草以补充而非重写原文，故基础文件与其附加部分须合读。"}],"etymology":{"intro":{"en":"Supplement comes from Latin supplementum, 'that which fills up', from supplere 'to fill up, complete'. It joins sub- 'from below, up' to plere 'to fill', so the word pictures something poured in from underneath to make a vessel full.","cn":"supplement 出自拉丁语 supplementum“用来填满之物”，源于 supplere“填满、补全”。它把 sub-“从下、向上”与 plere“填”结合，画面是从底下添进去，把容器填满。"},"items":[{"era":"14C","en":"English borrows the noun from Latin supplementum, first in the sense of a thing added to complete something.","cn":"英语从拉丁语 supplementum 借入名词，最早义为“为补全而添加之物”。"},{"era":"LATIN","en":"supplere means 'to fill up, make complete, supply'. It is sub- 'up from below' plus plere 'to fill'.","cn":"supplere 意为“填满、补全、供给”。它由 sub-“自下而上”与 plere“填”构成。"},{"era":"PIE","en":"plere goes back to PIE *pleh₁- 'to fill', the same root behind complete, deplete, plenty, and replenish.","cn":"plere 可追溯到原始印欧语 *pleh₁-“填满”，同一词根见于 complete、deplete、plenty、replenish。"},{"era":"LATIN","en":"supplementum is the noun of instrument or result: the thing with which one fills a gap.","cn":"supplementum 是工具或结果名词：用来填补缺口的东西。"},{"era":"17C","en":"The verb appears in English later, meaning 'to add in order to complete or improve'.","cn":"动词较晚出现于英语，意为“为补全或改善而添加”。"},{"era":"MODERN","en":"Modern use ranges from vitamins and newspapers to fares and contract clauses, all sharing the 'fill the gap' image.","cn":"现代用法从维生素、报纸延伸到票价与合同条款，皆共享“填补缺口”的意象。"}]},"similar":{"note":{"en":"The first group is the supplere family and its -ary/-al adjectives; the second is words for things added, each with a different relation to the whole.","cn":"第一组是 supplere 词族及其 -ary/-al 形容词；第二组是“添加之物”的近义词，与整体的关系各异。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"supplementary","ipa":"/ˌsʌplɪˈmentri/","tag":"adjective","definition":"added to complete or extend something. It is the adjective of supplement.","definitionCN":"为补全或扩展而附加的。是 supplement 的形容词。"},{"word":"supplementation","ipa":"/ˌsʌplɪmenˈteɪʃn/","tag":"process noun","definition":"the act of adding supplements, especially nutrients.","definitionCN":"添加补充物，尤指营养素。"},{"word":"supplemental","ipa":"/ˌsʌplɪˈmentl/","tag":"adjective (US)","definition":"another adjective form, common in American legal and technical writing.","definitionCN":"另一形容词形式，常见于美国法律与技术写作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"complement","ipa":"/ˈkɒmplɪment/","tag":"completing addition","definition":"something that completes by supplying what is missing, often in a way that makes a pair better together.","definitionCN":"通过补上所缺而使完整，常指两者相配更佳。"},{"word":"addition","ipa":"/əˈdɪʃn/","tag":"general add-on","definition":"anything added, without the claim that it fills a gap.","definitionCN":"任何添加之物，不强调填补缺口。"},{"word":"appendix","ipa":"/əˈpendɪks/","tag":"book addition","definition":"a section added at the end of a book for supporting material.","definitionCN":"书末附加的支撑材料章节。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: sub- plus plere, the 'fill up' image, the supplement/supply doublet, and the supplement/complement distinction.","cn":"真实联系：sub- 加 plere、“填满”意象、supplement 与 supply 这对同源词，以及 supplement 与 complement 的区别。"},"normal":[{"en":"Sub- means 'up from below' and plere means 'fill'. A supplement is poured in underneath to make the vessel full.","cn":"sub- 意为“自下而上”，plere 意为“填”。supplement 是从底下添进去，把容器填满。"},{"en":"The base is never replaced: the manual stays, and the supplement fills its gap.","cn":"基底从不被取代：手册仍在，补充篇填其缺口。"},{"en":"A vitamin supplement fills a dietary gap; it does not replace the meal.","cn":"维生素补充剂填补饮食缺口，不取代一餐。"},{"en":"Supplement vs complement: a supplement fills a lack, a complement completes a pair.","cn":"supplement 与 complement：前者填缺，后者成全一对。"},{"en":"Supply and supplement are doublets from supplere: one supplies, one fills the gap.","cn":"supply 与 supplement 是出自 supplere 的同源双词：一个供给，一个补缺。"}],"abstract":[{"en":"A supplement admits that the whole was not quite whole; it is a modest word that names a lack.","cn":"补充物承认整体并不完全完整；它是一个谦逊的词，命名了缺口。"},{"en":"The logic of supplementation can always escalate: every addition creates a new edge that might need another.","cn":"补充的逻辑总会升级：每次添加都造出新的边缘，可能又需要下一次补充。"},{"en":"Whole and part are not fixed: what counts as the base depends on where you draw the line.","cn":"整体与部分并不固定：何谓基底，取决于你把线画在哪里。"}]},"examples":[{"en":"She takes an iron supplement every morning.","cn":"她每天早上服用铁补充剂。"},{"en":"He supplements his income by teaching evening classes.","cn":"他靠晚上教课增加收入。"},{"en":"The magazine published a special supplement on climate.","cn":"杂志出版了一期气候专刊。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“塞普利门特”——往门特（门里）再塞一勺普利，把缺口补满 → supplement 补充物、增补","word":"supplement"},"root":"拉丁语 supplementum“用来填满之物”，出自 supplere“填满、补全”，由 sub-“自下、向上”+ plere“填”构成。","sensesIntro":{"en":"Nine senses of supplement, all built on one geometry: a base stays, and something is added to fill its gap. The gap may be nutritional, editorial, monetary, geometric, or legal.","cn":"supplement 的九个义项都建于同一几何：基底保留，另加一物填其缺口。缺口可以是营养的、编辑的、金钱的、几何的或法律的。"},"semanticMap":{"core":{"en":"CORE IMAGE: a nearly full vessel topped up from below until it is complete.","cn":"核心意象：将满的容器从底下再添，直到补齐。"},"chain":["FILL FROM BELOW","COMPLETE THE GAP","ADD ALONGSIDE","SPECIALISE THE BASE","CHARGE FOR THE EXTRA","READ BASE AND ADDITION TOGETHER"],"branches":[{"senses":"S1 · S6","en":"THE GENERAL ACT: something is added to a base without replacing it.","cn":"一般动作：在基底上添加，而不取代基底。"},{"senses":"S2 · S7","en":"THE BODY AND THE PURSE: nutrients and income are bases that can be topped up.","cn":"身体与钱包：营养与收入都是可被添补的基底。"},{"senses":"S3 · S4","en":"PUBLISHING: the supplement is a separate section or an appendix, marked off from the main text.","cn":"出版：增刊或附录是与正文分开标记的独立部分。"},{"senses":"S5 · S9","en":"MONEY AND LAW: the extra charge and the added clause both extend an original arrangement.","cn":"金钱与法律：附加费与补充条款都扩展了原初安排。"},{"senses":"S8","en":"GEOMETRY: the supplement is defined purely by the whole it completes.","cn":"几何：补角完全由它所补全的整体来定义。"}]},"affixes":{"intro":{"en":"Supplement is a Latin noun in -mentum, the suffix of means and results. English derives -ary and -al adjectives, -ation for the process, and shares the plere root with complete and supply.","cn":"supplement 是带 -mentum（工具与结果后缀）的拉丁名词。英语派生 -ary 与 -al 形容词、表过程的 -ation，并与 complete、supply 共享 plere 词根。"},"latinIntro":{"en":"Latin supplere 'fill up' combines sub- 'from below' and plere 'fill'. Its noun supplementum gives English supplement; the same verb gives supply, and the same root gives complete, deplete, and plenty.","cn":"拉丁语 supplere“填满”由 sub-“从下”与 plere“填”结合。其名词 supplementum 给出英语 supplement；同一动词给出 supply，同一词根给出 complete、deplete、plenty。"},"items":[{"word":"supplementary","structure":"supplement + -ary (adjective)","meaning":"added to complete or extend","meaningCN":"补充的；附加的（-ary 形容词）","example":"supplementary material","exampleCN":"补充材料"},{"word":"supplementation","structure":"supplement + -ation (noun)","meaning":"the act of adding a supplement","meaningCN":"补充；增补（-ation 名词）","example":"iron supplementation","exampleCN":"补铁"},{"word":"supplemental","structure":"supplement + -al (adjective)","meaning":"serving as a supplement","meaningCN":"补充的（-al 形容词）","example":"supplemental evidence","exampleCN":"补充证据"},{"word":"supplemented","structure":"supplement + -ed (participle)","meaning":"having had something added","meaningCN":"已补充的（过去分词）","example":"a supplemented diet","exampleCN":"被补充过的饮食"},{"word":"suppletive","structure":"supplere + -ive (adjective)","meaning":"of a linguistic form supplied from another paradigm","meaningCN":"异干互补的（语言学形容词）","example":"suppletive forms","exampleCN":"异干形式"},{"word":"supply","structure":"from Latin supplere (verb/noun)","meaning":"to provide what is needed; a stock provided","meaningCN":"供给；供应（同源动词/名词）","example":"supply the market","exampleCN":"供应市场"},{"word":"complete","structure":"com- + plere (same root)","meaning":"to fill up entirely; whole","meaningCN":"完成；完整的（同根：com-“完全”+ plere“填”）","example":"complete the form","exampleCN":"填完表格"},{"word":"deplete","structure":"de- + plere (same root)","meaning":"to empty out; to reduce a stock","meaningCN":"耗尽；减少（同根：de-“去掉”+ plere“填”）","example":"deplete resources","exampleCN":"耗尽资源"},{"word":"plenty","structure":"plenus 'full' (same root)","meaning":"a large amount; abundance","meaningCN":"大量；丰富（同根形容词 plenus）","example":"plenty of time","exampleCN":"充足的时间"}],"latinEntries":[{"word":"supplere","structure":"sub- 'from below' + plere 'fill'","meaning":"to fill up, complete, supply","meaningCN":"填满；补全；供给"},{"word":"supplementum","structure":"from supplere","meaning":"that which fills up; a supplement","meaningCN":"补充物；补足物"},{"word":"plere","structure":"Latin verb","meaning":"to fill","meaningCN":"填满"},{"word":"plenus","structure":"Latin adjective","meaning":"full","meaningCN":"满的"}]}},{"word":"survey","ipa_uk":"/ˈsɜːveɪ/ (n.); /səˈveɪ/ (v.)","ipa_us":"/ˈsɜːrveɪ/ (n.); /sərˈveɪ/ (v.)","definition_zh":"调查；概览；测量；房屋检测；（课程）通览；审视；俯瞰；勘测；评述","definition_en":"a detailed study of people's opinions or a subject; the act of measuring land; to look over carefully or question a group","core_image":"站在山顶把整片山谷扫视一遍，再把看到的画成一张图","scene":"研究团队做了一次全国范围的调查。The survey asked two thousand people how long they spent commuting every day.","sceneCN":"这里 survey 是「调查」（第 1 个义项：对一群人进行系统询问以获取数据）；句意：这次调查问了两千人，每天通勤要花多少时间。图中可辨识物件：问卷、手机、通勤地铁、统计图表、研究员的笔记本。","pos":[{"tag":"n.","zh":"调查；概览；测量；房屋检测"},{"tag":"v.","zh":"审视；俯瞰；调查；勘测；评述"}],"collocations":[{"phrase":"conduct a survey","zh":"进行调查"},{"phrase":"a nationwide survey","zh":"全国性调查"},{"phrase":"a survey of the literature","zh":"文献综述"},{"phrase":"survey the landscape","zh":"眺望风景"},{"phrase":"a land survey","zh":"土地测量"},{"phrase":"a building survey","zh":"房屋检测"}],"forms":[{"label":"复数","form":"surveys"},{"label":"第三人称单数","form":"surveys"},{"label":"现在分词","form":"surveying"},{"label":"过去式/过去分词","form":"surveyed"},{"label":"名词施事","form":"surveyor"}],"derivatives":[{"word":"surveyor","pos":"n.","zh":"测量员；房屋检测师"},{"word":"surveying","pos":"n.","zh":"测量；勘测"},{"word":"surveyed","pos":"adj.","zh":"被调查的；被测量的"},{"word":"oversee","pos":"v.","zh":"监督（同源近亲，经不同路径）"}],"senses":[{"no":"01","title":"A questionnaire study","titleCN":"问卷调查","definition":"a structured study that asks people questions and analyses the answers","definitionCN":"向人们提问并分析回答的结构化研究","example":"The survey found that most commuters want later trains.","exampleCN":"调查发现多数通勤者希望班次更晚。","why":"The modern sense is statistical: a sample is questioned so that its answers can stand for a population. The 'looking over' becomes counting.","whyCN":"现代义是统计性的：询问样本，使其回答能代表总体。“俯视”于是变成计数。"},{"no":"02","title":"A general overview","titleCN":"概览；综述","definition":"a broad account of a subject rather than a detailed study","definitionCN":"对某主题的宽泛叙述而非细究","example":"The book offers a survey of European history.","exampleCN":"这本书提供了一部欧洲史概览。","why":"Here survey means seeing the whole field at once. The value is range, not depth: the reader is given the map, not the excavation.","whyCN":"此处 survey 指一次看见整个领域。价值在广度而非深度：读者得到地图，而非发掘现场。"},{"no":"03","title":"Land measurement","titleCN":"土地测量","definition":"the measuring of an area's boundaries, levels, and features","definitionCN":"测量某地块的边界、高程与特征","example":"A survey established the exact boundary of the farm.","exampleCN":"一次测量确定了农场的准确边界。","why":"Land surveying is the oldest technical sense: the eye is replaced by instruments, and 'looking over' becomes measuring so that ownership can be written down.","whyCN":"土地测量是最古老的技术义：眼睛被仪器取代，“俯视”变成测量，以便把所有权写下来。"},{"no":"04","title":"A building inspection","titleCN":"房屋检测","definition":"an examination of a property's condition before purchase or work","definitionCN":"购房或施工前对房产状况的检查","example":"The survey revealed damp in the basement.","exampleCN":"房屋检测发现地下室受潮。","why":"British usage narrows the word to a professional's report on a building. The inspector surveys in the sense of 'looks carefully at every part'.","whyCN":"英式用法把词收窄为专业人士对建筑的报告。检测者 survey，就是“逐部分细看”。"},{"no":"05","title":"To look over from above","titleCN":"俯瞰；扫视","definition":"to look carefully across a whole scene, often from a height","definitionCN":"从高处仔细扫看整个场景","example":"She surveyed the valley from the ridge.","exampleCN":"她从山脊俯瞰山谷。","why":"This is the physical core: the eyes move across a field and take it in as a whole. Everything else is a metaphor built on this sweep.","whyCN":"这是物理核心：目光扫过一片场域，把它作为整体收下。其余义项都是建立在这一扫之上的隐喻。"},{"no":"06","title":"To question a sample","titleCN":"调查询问","definition":"to ask a group of people a set of questions","definitionCN":"向一群人提出一组问题","example":"They surveyed 2,000 readers about their habits.","exampleCN":"他们调查了两千名读者的习惯。","why":"The verb turns the questionnaire into an action. The direction reverses: instead of the scene entering the eye, information is drawn out of people.","whyCN":"动词把问卷变成动作。方向反转：不再是场景进入眼睛，而是从人那里取出信息。"},{"no":"07","title":"To measure land","titleCN":"勘测","definition":"to measure an area with instruments","definitionCN":"用仪器测量一片区域","example":"Engineers surveyed the route before building the bridge.","exampleCN":"工程师在造桥前勘测了路线。","why":"The technical verb keeps the old sense alive. Surveying produces a record numbers, bearings, heights which can be used by others who never saw the site.","whyCN":"技术动词让古老义存活。勘测产出数字、方位、高程的记录，可供从未见过现场的人使用。"},{"no":"08","title":"To review a field","titleCN":"评述；审视","definition":"to examine a subject systematically in writing or speech","definitionCN":"以文字或口头系统考察某主题","example":"The lecture surveys recent work on memory.","exampleCN":"讲座评述了记忆研究的最新成果。","why":"Academic survey is a second-hand looking: the author has read widely and now lets the audience see the field through their sweep.","whyCN":"学术评述是二手的看：作者已广泛阅读，现在让听众透过他的一扫看见该领域。"},{"no":"09","title":"A survey course","titleCN":"通览课程","definition":"a course that introduces a whole field rather than one part","definitionCN":"介绍整个领域而非局部的课程","example":"She took a survey course in art history.","exampleCN":"她上了一门艺术史通览课。","why":"Education borrows the overview sense: the course moves fast across the whole map so that students know where the detailed courses fit.","whyCN":"教育借用了概览义：课程快速走遍整张地图，让学生知道细部课程的位置。"}],"etymology":{"intro":{"en":"Survey comes from Anglo-French surveier, 'to look over', from sur- 'over' (Latin super) plus veoir 'to see' (Latin videre). The medieval Latin verb supervidere 'oversee' is the bridge; the modern statistical sense is a nineteenth-century extension.","cn":"survey 出自盎格鲁-法语 surveier“查看”，由 sur-“在上”（拉丁 super）加 veoir“看”（拉丁 videre）构成。中世纪拉丁语 supervidere“监督”是桥梁；现代统计义是十九世纪的延伸。"},"items":[{"era":"14C","en":"The noun first means 'the act of viewing or inspecting', often of land or property.","cn":"名词最早指“观看或检查的行为”，常指土地或房产。"},{"era":"ANGLO-FRENCH","en":"surveier 'to look over, oversee' comes from sur- 'over' and veoir 'to see'.","cn":"surveier“查看、监督”由 sur-“在上”与 veoir“看”构成。"},{"era":"LATIN","en":"The elements are Latin super 'above' and videre 'to see'. Medieval Latin supervidere 'oversee' is the learned counterpart.","cn":"其成分是拉丁 super“在上”与 videre“看”。中世纪拉丁语 supervidere“监督”是相应的书面形式。"},{"era":"16C","en":"Land surveying becomes a profession, and the word acquires its technical sense of measured boundaries and levels.","cn":"十六世纪土地测量成为职业，该词获得“测量边界与高程”的技术义。"},{"era":"19C","en":"Statistical surveying develops with census and market research: a sample is questioned so that it can represent a whole.","cn":"统计调查随人口普查与市场研究发展：询问样本，使其代表整体。"},{"era":"20C","en":"The questionnaire sense becomes dominant in everyday English, while the 'overview' sense survives in academic titles.","cn":"问卷义在日常英语中占主导，而“概览”义在学术书名中存活。"}]},"similar":{"note":{"en":"The first group shares the survey root and the -or/-ing endings; the second is other ways of finding out what people or a field contain.","cn":"第一组共享 survey 词根与 -or/-ing 结尾；第二组是了解人群或领域内容的其他方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"surveyor","ipa":"/səˈveɪə/","tag":"person noun","definition":"one who measures land or inspects buildings. It adds -or to the verb.","definitionCN":"测量土地或检测建筑的人。动词加 -or。"},{"word":"surveying","ipa":"/səˈveɪɪŋ/","tag":"activity noun","definition":"the profession or act of measuring land.","definitionCN":"测量土地的职业或行为。"},{"word":"surveil","ipa":"/səˈveɪl/","tag":"back-formed verb","definition":"to watch a person or group secretly. It is a modern back-formation from surveillance.","definitionCN":"秘密监视个人或群体。是由 surveillance 逆构的现代动词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"poll","ipa":"/pəʊl/","tag":"opinion count","definition":"a survey of opinions, especially political, by questioning voters. It is narrower and usually electoral.","definitionCN":"对意见的调查，尤指政治民调，询问选民。范围更窄，多涉选举。"},{"word":"study","ipa":"/ˈstʌdi/","tag":"research project","definition":"a careful investigation of a subject, often with a written report. It is broader than a questionnaire survey.","definitionCN":"对主题的仔细探究，常有书面报告。比问卷式调查更广。"},{"word":"overview","ipa":"/ˈəʊvəvjuː/","tag":"broad view","definition":"a general description of a subject from a distance. It matches the 'survey' sense but not the statistical one.","definitionCN":"从远处对主题作总体描述。对应“概览”义，但不含统计义。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: sur- 'over' plus videre 'to see', the sweep of the eyes, and the split between counting people and measuring land.","cn":"真实联系：sur-“在上”加 videre“看”、目光的一扫，以及“数人”与“量地”的分工。"},"normal":[{"en":"Sur- means 'over' and videre means 'see'. To survey is to look over a whole field from above.","cn":"sur- 意为“在上”，videre 意为“看”。survey 就是从上方看遍整片场域。"},{"en":"The same Latin videre gives vision, video, and evident: all are ways of seeing.","cn":"同一拉丁 videre 给出 vision、video、evident：都是“看”的方式。"},{"en":"A questionnaire survey reverses the gaze: instead of the scene entering your eye, you draw answers out of people.","cn":"问卷调查反转了目光：不是场景进入你的眼，而是你从人身上取出回答。"},{"en":"Land survey turns looking into numbers, so that people who never saw the site can build on it.","cn":"土地测量把看变成数字，使从未见过现场的人也能施工。"},{"en":"An academic survey is second-hand seeing: the author sweeps the field and lets you look through their eyes.","cn":"学术综述是二手的看：作者扫过领域，让你透过他的眼睛看。"}],"abstract":[{"en":"Survey is a word about scale: it works only when the whole is too large for a single close look.","cn":"survey 是一个关于尺度的词：只有当整体大到无法一次细看时，它才发挥作用。"},{"en":"Every survey chooses a frame, and the frame decides what can appear as a finding.","cn":"每次调查都选择了一个框架，而框架决定什么能作为“发现”出现。"},{"en":"To survey is to accept the trade of detail for shape, and to be honest about which one you chose.","cn":"survey 就是接受“以细节换形状”的交易，并对你选了哪一边保持诚实。"}]},"examples":[{"en":"The survey asked workers about their commuting habits.","cn":"该调查询问了员工的通勤习惯。"},{"en":"From the tower we surveyed the whole harbor.","cn":"我们从塔上俯瞰整个港口。"},{"en":"The course surveys nineteenth-century literature.","cn":"这门课通览十九世纪文学。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“色威”——站在高处把整片颜色扫一遍，威然在目 → survey 俯瞰、调查","word":"survey"},"root":"盎格鲁-法语 surveier“查看”，由 sur-“在上”（拉丁 super）+ veoir“看”（拉丁 videre）构成；对应中世纪拉丁语 supervidere“监督”。","sensesIntro":{"en":"Nine senses of survey, all one sweep of the eyes. The sweep can be physical (a view from a ridge), statistical (a sample questioned), technical (land measured), or scholarly (a field reviewed).","cn":"survey 的九个义项都是一次目光的扫掠。扫掠可以是物理的（山脊眺望）、统计的（样本询问）、技术的（土地测量）或学术的（领域评述）。"},"semanticMap":{"core":{"en":"CORE IMAGE: the eyes moving across a whole field and taking it in as one picture.","cn":"核心意象：目光扫过整片场域，把它收成一张图。"},"chain":["LOOK OVER","SEE THE WHOLE","TAKE IT IN AS A PICTURE","COUNT AND MEASURE","RECORD THE FINDINGS","REVIEW THE FIELD"],"branches":[{"senses":"S1 · S6","en":"QUESTIONING: the sweep is turned on people, and answers become data.","cn":"询问：扫掠转向人群，回答变成数据。"},{"senses":"S2 · S8 · S9","en":"THE WHOLE FIELD: overview, academic review, and the survey course all value range over depth.","cn":"整片领域：概览、学术评述与通览课程都以广度胜深度。"},{"senses":"S3 · S7","en":"MEASUREMENT: instruments replace the eye, and looking becomes numbers.","cn":"测量：仪器取代眼睛，看变成数字。"},{"senses":"S4","en":"THE BUILDING: a professional looks at every part and writes a condition report.","cn":"建筑：专业人士逐部分细看，写出状况报告。"},{"senses":"S5","en":"THE PHYSICAL CORE: from a height, the eye takes the scene as a single image.","cn":"物理核心：从高处，眼睛把场景收成单一图像。"}]},"affixes":{"intro":{"en":"Survey is an Anglo-French verb built on sur- plus veoir, later reshaped by Latin super and videre. English derives surveyor and surveying, while the same videre family gives vision, video, and supervise.","cn":"survey 是盎格鲁-法语动词，由 sur- 加 veoir 构成，后受拉丁 super 与 videre 重塑。英语派生 surveyor 与 surveying，同一 videre 词族给出 vision、video、supervise。"},"latinIntro":{"en":"Latin super 'above' plus videre 'to see' yields supervidere 'oversee'. French compressed it into surveier, and English took the noun survey. The videre branch also gives vision, evident, and video.","cn":"拉丁 super“在上”加 videre“看”生成 supervidere“监督”。法语压缩为 surveier，英语取名词 survey。videre 一支还给出 vision、evident、video。"},"items":[{"word":"surveyor","structure":"survey + -or (person noun)","meaning":"one who surveys land or buildings","meaningCN":"测量员；检测师（-or 施事）","example":"a chartered surveyor","exampleCN":"特许测量师"},{"word":"surveying","structure":"survey + -ing (activity noun)","meaning":"the profession of measuring land","meaningCN":"测量；勘测（-ing 名词）","example":"land surveying","exampleCN":"土地测量"},{"word":"surveyed","structure":"survey + -ed (participle)","meaning":"examined or measured","meaningCN":"被调查的；被测量的（过去分词）","example":"the surveyed area","exampleCN":"勘测过的区域"},{"word":"supervise","structure":"super- + videre (same root)","meaning":"to watch over and direct work","meaningCN":"监督；管理（同根：super-“在上”+ videre“看”）","example":"supervise a team","exampleCN":"管理团队"},{"word":"supervision","structure":"super- + vision (same root)","meaning":"the act of watching over","meaningCN":"监督；指导（同根名词）","example":"under supervision","exampleCN":"在监督下"},{"word":"supervisor","structure":"supervise + -or (person noun)","meaning":"one who oversees others","meaningCN":"主管；导师（同根施事名词）","example":"a shift supervisor","exampleCN":"值班主管"},{"word":"surveillance","structure":"sur- + veillance 'watching' (noun)","meaning":"close watching of a person or place","meaningCN":"监视；监控（同源名词）","example":"under surveillance","exampleCN":"处于监控之下"},{"word":"vision","structure":"videre + -ion (noun)","meaning":"sight; the ability to see","meaningCN":"视力；远见（同根名词）","example":"night vision","exampleCN":"夜视"},{"word":"video","structure":"Latin videre 'I see' (noun)","meaning":"recorded moving images","meaningCN":"视频（同根，拉丁“我看见”）","example":"watch a video","exampleCN":"看视频"}],"latinEntries":[{"word":"supervidere","structure":"super- 'above' + videre 'see'","meaning":"to oversee, inspect","meaningCN":"监督；查看"},{"word":"videre","structure":"Latin verb","meaning":"to see","meaningCN":"看见"},{"word":"super","structure":"Latin preposition","meaning":"above, over","meaningCN":"在上；超过"},{"word":"surveier","structure":"Anglo-French verb","meaning":"to look over, oversee","meaningCN":"查看；监督"}]}},{"word":"survive","ipa_uk":"/səˈvaɪv/","ipa_us":"/sərˈvaɪv/","definition_zh":"幸存；活下来；继续存在；比…活得长；挺过；维持生存；留存下来；经受住","definition_en":"to continue to live or exist after danger, difficulty, or the end of others","core_image":"风暴过后，沙滩上只剩一棵歪斜的树还立着，根仍抓在土里","scene":"地震之后，这栋老屋居然还在。The walls cracked and the beams tilted, but the old house did survive, and the family moved back in that winter.","sceneCN":"这里 survive 是「幸存、挺过」（第 1 个义项：在危险之后继续存活）；句意：墙裂了、梁斜了，但这栋老屋确实挺了过来，一家人那年冬天又搬了回去。图中可辨识物件：裂缝墙面、倾斜屋梁、瓦砾、救援人员、远处余震扬尘。","pos":[{"tag":"v.","zh":"幸存；活下来；继续存在；比…活得长"}],"collocations":[{"phrase":"survive a crash","zh":"在车祸中幸存"},{"phrase":"survive on benefits","zh":"靠救济金度日"},{"phrase":"survive the winter","zh":"熬过冬天"},{"phrase":"survive as a species","zh":"作为物种存续"},{"phrase":"survive from the Bronze Age","zh":"自青铜时代留存下来"},{"phrase":"survive scrutiny","zh":"经受住审查"}],"forms":[{"label":"第三人称单数","form":"survives"},{"label":"现在分词","form":"surviving"},{"label":"过去式/过去分词","form":"survived"},{"label":"名词","form":"survival / survivor"}],"derivatives":[{"word":"survival","pos":"n.","zh":"生存；幸存；残存物"},{"word":"survivor","pos":"n.","zh":"幸存者；生还者"},{"word":"surviving","pos":"adj.","zh":"仍存活的；残存的"},{"word":"survivable","pos":"adj.","zh":"可幸存的；能挺过去的"}],"senses":[{"no":"01","title":"Continue to live after danger","titleCN":"在危险后活下来","definition":"to remain alive after an accident, war, illness, or disaster","definitionCN":"在事故、战争、疾病或灾难后仍活着","example":"Only two passengers survived the crash.","exampleCN":"只有两名乘客在坠机中幸存。","why":"The Latin verb supervivere means 'to live beyond'. Surviving is living past an event that could have ended you; the preposition is hidden inside the verb.","whyCN":"拉丁动词 supervivere 意为“活过、超出”。幸存就是活过一场本可终结你的事件；介词藏在动词内部。"},{"no":"02","title":"Continue to exist","titleCN":"继续存在","definition":"of a thing, to remain in existence after others have gone","definitionCN":"事物在其余消失后仍然存在","example":"The custom survives in remote villages.","exampleCN":"这一习俗在偏远村庄中留存。","why":"Things as well as people can survive. The word then means persistence, not breath: a practice, a building, or a language outlasts its original conditions.","whyCN":"物与人皆可 survive。此时词义是持续，而非呼吸：一种习俗、一栋建筑或一门语言活得比原初条件更久。"},{"no":"03","title":"Outlive someone","titleCN":"比…活得长","definition":"to live longer than another person","definitionCN":"活得比另一人更久","example":"She survived her husband by ten years.","exampleCN":"她比丈夫多活了十年。","why":"This is the sharply comparative sense: two lives are placed on one timeline, and one crosses the other's end. It can sound cold when used of the dead.","whyCN":"这是明确的比较义：两条生命放在同一时间轴上，一条越过另一条的终点。用于逝者时可能显得冷峻。"},{"no":"04","title":"Endure and get through","titleCN":"挺过；熬过","definition":"to manage to live through a hard period or experience","definitionCN":"设法度过艰难时期或经历","example":"The family survived three years of drought.","exampleCN":"这家人熬过了三年干旱。","why":"Endurance adds time to survival. The danger is not a single event but a duration, and the verb measures how long the living can be sustained.","whyCN":"“熬”在“活”之上加了时间。危险不是单一事件而是持续段，动词衡量生命能被维持多久。"},{"no":"05","title":"Remain viable","titleCN":"存续；活下来（机构/企业）","definition":"of a business or institution, to continue operating","definitionCN":"企业或机构继续运转","example":"Few bookshops survived the rise of online retail.","exampleCN":"很少有书店在网售兴起后存活下来。","why":"Organisations are treated as living things: they have founding, growth, and death. To survive is to keep operating when the conditions that supported them change.","whyCN":"组织被当作生物：有创立、成长与死亡。survive 就是在赖以支撑的条件变化时继续运转。"},{"no":"06","title":"Subsist on","titleCN":"靠…维持生活","definition":"to live with only a particular thing as food or income","definitionCN":"仅以某物为食或为收入来源生活","example":"They survived on bread and tea for weeks.","exampleCN":"他们靠面包和茶撑了几周。","why":"Here the verb specifies the minimum: what is just enough to keep life going. It often carries hardship, because the diet is narrow by necessity.","whyCN":"此处动词指定最低限度：刚好够维持生命之物。它常带艰辛色彩，因为这种食谱是被迫狭窄的。"},{"no":"07","title":"Remain in a form","titleCN":"以…形式留存","definition":"to continue to exist as a particular kind of thing","definitionCN":"以某种形态继续存在","example":"The old dialect survives as a few place names.","exampleCN":"古老方言以几个地名的形式留存。","why":"Survival can be partial. What remains may be a fragment, a trace, or a transformed version, and 'survive as' names that reduced continuance.","whyCN":"留存可以是部分的。所剩可能是碎片、痕迹或变形版本，survive as 命名这种缩减后的延续。"},{"no":"08","title":"Date from an earlier time","titleCN":"自…时期留存","definition":"to have come down from an earlier period","definitionCN":"从更早时期传下来","example":"These coins survive from the third century.","exampleCN":"这些钱币是三世纪留存下来的。","why":"In archaeology and history, the verb marks continuity across a gap. An object survives when it reaches the present without being destroyed, even if its makers are long gone.","whyCN":"在考古与历史中，动词标记跨越断层的连续。器物未毁而抵达现在，即 survive，哪怕制作者早已不在。"},{"no":"09","title":"Withstand a test","titleCN":"经受住（检验）","definition":"to continue to be accepted after close examination or challenge","definitionCN":"经仔细检验或挑战后仍被接受","example":"The theory survived decades of criticism.","exampleCN":"这一理论经受住了数十年的批评。","why":"Abstract survival: an idea or claim must endure attack. The metaphor is still biological, but the 'danger' is now objection rather than death.","whyCN":"抽象的存活：观点或主张必须挺过攻击。隐喻仍是生物的，但“危险”已从死亡变成反驳。"}],"etymology":{"intro":{"en":"Survive comes from Old French survivre, from Latin supervivere, 'to live beyond': super 'over, beyond' plus vivere 'to live'. It is close in form to sustain but not in root: sustain is sub- plus tenere, 'to hold up from below'.","cn":"survive 出自古法语 survivre，源于拉丁语 supervivere“活过、超出”：super“在上、越过”加 vivere“活”。它与 sustain 形近而源不同：sustain 是 sub- 加 tenere“从下面托住”。"},"items":[{"era":"15C","en":"English takes the verb from Old French survivre, meaning 'to outlive, remain alive after'.","cn":"英语自法语 survivre 借入动词，意为“比…活得长、在…之后仍活着”。"},{"era":"LATIN","en":"supervivere is super 'over, beyond' plus vivere 'to live': to live past an event or another person.","cn":"supervivere 是 super“越过、超出”加 vivere“活”：活过某事件或某人。"},{"era":"LATIN","en":"vivere also gives vital, vivid, revive, and vivacity; the noun vita 'life' stands behind vital.","cn":"vivere 还给出 vital、vivid、revive、vivacity；名词 vita“生命”支撑 vital。"},{"era":"PIE","en":"vivere is traced to PIE *gʷeyh₃- 'to live', a reconstruction also proposed for Greek bios 'life'.","cn":"vivere 被追溯到原始印欧语 *gʷeyh₃-“活”，同一重构也被用于希腊语 bios“生命”。"},{"era":"17C","en":"The sense extends from persons to things: customs, buildings, and words can survive their makers.","cn":"十七世纪义项从人扩展到物：习俗、建筑与词语能活得比创造者更久。"},{"era":"MODERN","en":"Modern English adds institutional and abstract uses: firms survive a market, theories survive criticism.","cn":"现代英语增加机构与抽象用法：企业熬过市场，理论挺过批评。"}]},"similar":{"note":{"en":"The first group is the survival family and its endings; the second is verbs of continuing or outlasting, each with a different stress.","cn":"第一组是 survival 词族及词尾；第二组是“持续/活得久”的动词，侧重各异。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"survival","ipa":"/səˈvaɪvl/","tag":"noun","definition":"the state or fact of continuing to live or exist.","definitionCN":"存活；存续的状态或事实。"},{"word":"survivor","ipa":"/səˈvaɪvə/","tag":"person noun","definition":"one who survives a disaster or outlives others.","definitionCN":"灾难生还者；比他人活得久的人。"},{"word":"survivorship","ipa":"/səˈvaɪvəʃɪp/","tag":"legal noun","definition":"the right of a joint owner to take the whole when the other dies.","definitionCN":"共有财产中生存者对全部的权利。"}]},{"heading":"NEAR MEANING","entries":[{"word":"outlast","ipa":"/ˌaʊtˈlɑːst/","tag":"endure longer","definition":"to last longer than something else. It stresses duration rather than danger.","definitionCN":"比另一物持续更久。强调时长而非危险。"},{"word":"endure","ipa":"/ɪnˈdjʊə/","tag":"bear through","definition":"to suffer something painful patiently and continue. It stresses the bearing, not merely the remaining alive.","definitionCN":"耐心承受痛苦并继续。强调承受，而非仅仅活着。"},{"word":"persist","ipa":"/pəˈsɪst/","tag":"keep on","definition":"to continue firmly in an action or state. It often implies stubbornness or repetition.","definitionCN":"坚定持续于某行动或状态。常含固执或重复意味。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: super 'beyond' plus vivere 'live', the surviving/survival family, and the contrast with sustain (sub + tenere).","cn":"真实联系：super“越过”加 vivere“活”、surviving 与 survival 词族，以及同 sustain（sub + tenere）的对照。"},"normal":[{"en":"Super means 'beyond' and vivere means 'live'. To survive is to live beyond the event that could have ended you.","cn":"super 意为“越过”，vivere 意为“活”。survive 就是活过那场本可终结你的事件。"},{"en":"The same vivere gives vital, vivid, and revive: life, liveliness, and life again.","cn":"同一 vivere 给出 vital、vivid、revive：生命、鲜活、复生。"},{"en":"Survive vs sustain: survive is super + vivere (live beyond); sustain is sub + tenere (hold up). Same s-, different bones.","cn":"survive 与 sustain：前者是 super + vivere（活过），后者是 sub + tenere（托住）。同以 s- 开头，骨架不同。"},{"en":"Things survive too: a custom, a coin, a theory. The verb moves easily from breath to persistence.","cn":"物也会 survive：习俗、钱币、理论。动词轻易从呼吸滑向持续。"},{"en":"'Survive on' lowers the bar: bread and tea are enough to keep the living going.","cn":"survive on 把标准压低：面包与茶就够让生命继续。"}],"abstract":[{"en":"Survival is relational: nothing survives alone, only past something that did not.","cn":"存活是关系性的：没有东西独自存活，只是活过了某件没有活下来的事。"},{"en":"What survives is often not the whole but a trace, and the trace rewrites what the whole was.","cn":"存活下来的常不是整体而是痕迹，而痕迹会重写整体曾是什么。"},{"en":"To survive a test is to be changed by it; pure survival without alteration is a fantasy of stones.","cn":"经受住检验就是被检验改变；毫发无损的“纯粹存活”是石头的幻想。"}]},"examples":[{"en":"The pilot survived the crash with minor injuries.","cn":"飞行员在坠机中幸存，仅受轻伤。"},{"en":"Many traditional crafts survive in rural areas.","cn":"许多传统手艺在乡村留存。"},{"en":"The government survived the vote of no confidence.","cn":"政府挺过了不信任投票。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“色外屋”——风暴过后，屋外只剩一抹颜色，屋子居然还在 → survive 幸存","word":"survive"},"root":"拉丁语 supervivere“活过、超出”，由 super“越过、在上”+ vivere“活”构成；vivere 追溯到原始印欧语 *gʷeyh₃-。","sensesIntro":{"en":"Nine senses of survive, all placing a life or a thing on one side of an ending. The ending may be a crash, a drought, a competitor, a century, or an argument.","cn":"survive 的九个义项都把一条生命或一物放在某个“终点”的这一侧。终点可以是坠机、干旱、竞争者、一个世纪或一场论证。"},"semanticMap":{"core":{"en":"CORE IMAGE: one living thing still standing after the storm has passed.","cn":"核心意象：风暴过后，仍有一个活物立着。"},"chain":["LIVE BEYOND","REMAIN ALIVE","OUTLAST OTHERS","ENDURE A DURATION","KEEP OPERATING","LEAVE A TRACE"],"branches":[{"senses":"01 · 03","en":"LIFE AND DEATH: one life crosses an event or another life's end.","cn":"生死：一条生命越过某事件或另一生命的终点。"},{"senses":"02 · 07 · 08","en":"PERSISTENCE: things, forms, and dated traces continue past their makers.","cn":"持续：物、形态与有年代的痕迹越过创造者而延续。"},{"senses":"04 · 06","en":"ENDURANCE: survival is stretched over time and reduced to a minimum diet.","cn":"熬：存活被拉长为时段，并被压到最低食粮。"},{"senses":"05","en":"INSTITUTIONS: a firm must keep going under changed conditions.","cn":"机构：企业须在变化条件下继续运转。"},{"senses":"09","en":"THE TEST: the danger becomes objection, and survival becomes acceptance.","cn":"检验：危险变成反驳，存活变成被接受。"}]},"affixes":{"intro":{"en":"Survive is a Latin-derived verb whose English family is survival, survivor, and survivable. The same vivere root supplies vital, vivid, revive, and vivacity.","cn":"survive 是拉丁系动词，英语词族为 survival、survivor、survivable。同一 vivere 词根供应 vital、vivid、revive、vivacity。"},"latinIntro":{"en":"Latin supervivere 'live beyond' joins super 'over' and vivere 'live'. The vivere branch runs through vital, vivid, and revive; the super- prefix also appears in supervise and superior.","cn":"拉丁语 supervivere“活过”结合 super“越过”与 vivere“活”。vivere 一支贯穿 vital、vivid、revive；super- 前缀也见于 supervise 与 superior。"},"items":[{"word":"survival","structure":"survive + -al (noun)","meaning":"the fact of continuing to live or exist","meaningCN":"存活；存续（-al 名词）","example":"the survival of the fittest","exampleCN":"适者生存"},{"word":"survivor","structure":"survive + -or (person noun)","meaning":"one who survives","meaningCN":"幸存者（-or 施事）","example":"a plane crash survivor","exampleCN":"坠机生还者"},{"word":"survivorship","structure":"survivor + -ship (noun)","meaning":"the state of being a survivor; a legal right","meaningCN":"幸存者身份；生存者权（-ship 名词）","example":"right of survivorship","exampleCN":"生存者取得权"},{"word":"surviving","structure":"survive + -ing (participle/adjective)","meaning":"still alive or remaining","meaningCN":"仍存活的；残存的（现在分词/形容词）","example":"the surviving members","exampleCN":"在世成员"},{"word":"survivable","structure":"survive + -able (adjective)","meaning":"possible to survive","meaningCN":"可幸存的（-able 形容词）","example":"a survivable fall","exampleCN":"可生还的坠落"},{"word":"revive","structure":"re- + vivere (same root)","meaning":"to bring or come back to life","meaningCN":"复苏；复活（同根：re-“再”+ vivere“活”）","example":"revive a tradition","exampleCN":"复兴传统"},{"word":"revival","structure":"revive + -al (noun)","meaning":"a return to life, use, or popularity","meaningCN":"复兴；复苏（名词）","example":"a religious revival","exampleCN":"宗教复兴"},{"word":"vital","structure":"vita 'life' + -al (same root)","meaning":"necessary for life; full of energy","meaningCN":"生命攸关的；有活力的（同根）","example":"vital organs","exampleCN":"重要器官"},{"word":"vivacity","structure":"vivax 'lively' + -ity (same root)","meaning":"liveliness of spirit","meaningCN":"活泼；生气（同根名词）","example":"her usual vivacity","exampleCN":"她一贯的活泼"}],"latinEntries":[{"word":"supervivere","structure":"super- 'beyond' + vivere 'live'","meaning":"to live beyond, outlive","meaningCN":"活过；比…活得长"},{"word":"vivere","structure":"Latin verb","meaning":"to live","meaningCN":"活着"},{"word":"vita","structure":"Latin noun","meaning":"life","meaningCN":"生命"},{"word":"super","structure":"Latin preposition","meaning":"above, beyond","meaningCN":"在上；超过"}]}},{"word":"sustain","ipa_uk":"/səˈsteɪn/","ipa_us":"/səˈsteɪn/","definition_zh":"支撑；维持；使持续；遭受；供养；认可（异议）；证实；承受；延长（音）","definition_en":"to hold up or keep something going over time; to suffer or experience something; to uphold or confirm","core_image":"一根柱子从地面顶住横梁，让整座屋顶多年不塌","scene":"这座小剧院靠本地观众的票款。Ticket sales from local audiences sustain the little theatre, and it has run for thirty years without a single grant.","sceneCN":"这里 sustain 是「维持、使持续」（第 2 个义项：让某事物在时间里持续运转）；句意：本地观众的票款维持着这座小剧院，它开了三十年，没拿过一分政府补贴。图中可辨识物件：老剧院门厅、售票窗口、海报、观众、斑驳的立柱。","pos":[{"tag":"v.","zh":"支撑；维持；遭受；供养；认可；证实；承受"}],"collocations":[{"phrase":"sustain growth","zh":"维持增长"},{"phrase":"sustain an injury","zh":"受伤"},{"phrase":"sustain a family","zh":"养活一家人"},{"phrase":"sustain an objection","zh":"认可异议"},{"phrase":"sustain interest","zh":"保持兴趣"},{"phrase":"sustainable development","zh":"可持续发展"}],"forms":[{"label":"第三人称单数","form":"sustains"},{"label":"现在分词","form":"sustaining"},{"label":"过去式/过去分词","form":"sustained"},{"label":"形容词","form":"sustainable / sustained"}],"derivatives":[{"word":"sustainable","pos":"adj.","zh":"可持续的；可承受的"},{"word":"sustainability","pos":"n.","zh":"可持续性"},{"word":"sustained","pos":"adj.","zh":"持续的；持久的"},{"word":"sustenance","pos":"n.","zh":"食物；营养；生计"}],"senses":[{"no":"01","title":"Hold up physically","titleCN":"支撑；托住","definition":"to bear the weight of something so that it does not fall","definitionCN":"承受重量使某物不塌落","example":"The columns sustain the roof.","exampleCN":"这些柱子支撑着屋顶。","why":"Sustinere in Latin is sub- 'up from below' plus tenere 'to hold'. The image is a hand or pillar placed under a weight; all later senses keep this vertical relation.","whyCN":"拉丁语 sustinere 是 sub-“自下而上”加 tenere“握持”。意象是手或柱子置于重物之下；后世义项都保留这种垂直关系。"},{"no":"02","title":"Keep something going","titleCN":"维持；使持续","definition":"to keep an activity, process, or condition going over time","definitionCN":"使活动、过程或状态在时间中延续","example":"The charity sustains its work through small donations.","exampleCN":"该慈善机构靠小额捐款维持运作。","why":"Maintenance is support extended in time. What began as holding up a roof becomes holding up a practice, day after day, until it becomes a habit or an institution.","whyCN":"维持是拉长到时间里的支撑。最初托住屋顶，后来托住一项实践，日复一日，直到它成为习惯或制度。"},{"no":"03","title":"Suffer an injury or loss","titleCN":"遭受（伤害/损失）","definition":"to experience something harmful, especially an injury","definitionCN":"经历有害之事，尤指受伤","example":"He sustained a knee injury in the match.","exampleCN":"他在比赛中膝部受伤。","why":"The legal and medical sense reverses the direction of support: the body is the thing that must hold up under a blow. What it undergoes, it 'sustains'.","whyCN":"法律与医学义反转了支撑方向：身体成了在打击下必须撑住的东西。它所承受的，就是它 sustain 的。"},{"no":"04","title":"Provide nourishment for","titleCN":"供养；维持生命","definition":"to provide enough food or resources for someone to live","definitionCN":"提供足够食物或资源使人存活","example":"The land sustains a small farming community.","exampleCN":"这片土地养活着一个小农耕社区。","why":"Food is support from below in the most literal way. To sustain a family is to keep it from falling into hunger, month by month.","whyCN":"食物是最字面意义上的“从下面托住”。养活一家人，就是逐月使他们不致落入饥饿。"},{"no":"05","title":"Uphold an objection (law)","titleCN":"认可；支持（异议）","definition":"of a judge, to agree that an objection is valid","definitionCN":"法官同意某项异议有效","example":"The judge sustained the objection.","exampleCN":"法官支持了该异议。","why":"Courtroom English uses sustain for 'let stand': the objection stands, and the question must stop. The judge holds the rule up against the pressure of the trial.","whyCN":"法庭英语用 sustain 表示“使其成立”：异议成立，提问必须停止。法官以规则顶住庭审的推力。"},{"no":"06","title":"Confirm or validate","titleCN":"证实；确认","definition":"to support a claim or conclusion as valid","definitionCN":"支持主张或结论为有效","example":"The data sustain the hypothesis.","exampleCN":"数据支持这一假设。","why":"Evidence holds a claim up. If the claim collapses under scrutiny, it was not sustained; if it stands, the evidence has done the supporting.","whyCN":"证据把主张托住。若主张在审视下崩塌，它便未被 sustain；若仍立着，便是证据完成了支撑。"},{"no":"07","title":"Bear or endure","titleCN":"承受；忍受","definition":"to bear a burden, pain, or difficult condition","definitionCN":"承担负担、痛苦或艰难处境","example":"She sustained the loss with remarkable calm.","exampleCN":"她以非凡的平静承受了这次失去。","why":"Endurance is the emotional twin of physical support. The self becomes the pillar, and the weight is grief, pressure, or waiting.","whyCN":"忍耐是物理支撑的情感孪生。自我成了柱子，重量则是悲伤、压力或等待。"},{"no":"08","title":"Extend a note (music)","titleCN":"延长（音）","definition":"to hold a sound or note at length","definitionCN":"把声音或音符拉长保持","example":"The pedal sustains the chord.","exampleCN":"踏板延长了和弦。","why":"Music borrows the temporal sense: a note is sustained when it is held without decay. The support is now breath or mechanism keeping the sound upright.","whyCN":"音乐借用了时间义：音符不衰减地保持，便是 sustained。支撑物此时是气息或机械，让声音立住。"},{"no":"09","title":"Carry an ecosystem","titleCN":"承载（生态）","definition":"of an environment, to support life or activity without collapse","definitionCN":"环境在不崩溃的前提下支持生命或活动","example":"The river cannot sustain so many farms.","exampleCN":"这条河承载不了这么多农场。","why":"Ecology turns support into a limit: a system can hold only so much weight before it degrades. Sustainable becomes a question of how long the pillar can bear the load.","whyCN":"生态学把支撑变成限度：系统只能承受到某一点，再重就退化。sustainable 于是成为“柱子还能承重多久”的问题。"}],"etymology":{"intro":{"en":"Sustain came through Old French sustenir from Latin sustinere, 'to hold up, endure': sub- 'up from below' plus tenere 'to hold'. It shares the letter s with survive but not the root: survive is super plus vivere, 'to live beyond'.","cn":"sustain 经古法语 sustenir 来自拉丁语 sustinere“托住、忍受”：sub-“自下而上”加 tenere“握持”。它与 survive 同以 s 开头而词根不同：survive 是 super 加 vivere“活过”。"},"items":[{"era":"13C","en":"English borrows the verb from Old French sustenir, 'to hold up, bear, endure'.","cn":"英语自法语 sustenir 借入动词，意为“托住、承担、忍受”。"},{"era":"LATIN","en":"sustinere is sub- 'up from below' plus tenere 'to hold, keep'. It means to hold something up from underneath.","cn":"sustinere 是 sub-“自下而上”加 tenere“握持、保持”。意为从下面把某物托住。"},{"era":"LATIN","en":"tenere also gives contain, maintain, retain, tenant, tenet, and tenure, all built on 'holding'.","cn":"tenere 还给出 contain、maintain、retain、tenant、tenet、tenure，皆建于“握持”。"},{"era":"PIE","en":"tenere is traced to PIE *ten- 'to stretch, hold', the same reconstruction behind tension and tendon.","cn":"tenere 被追溯到原始印欧语 *ten-“伸展、握持”，同一重构见于 tension 与 tendon。"},{"era":"15C","en":"Legal and medical uses appear: a court sustains an objection; a body sustains an injury.","cn":"十五世纪出现法律与医学用法：法庭认可异议；身体遭受伤害。"},{"era":"MODERN","en":"The environmental sense gives sustainable its modern force: support that can be continued without collapse.","cn":"环境义赋予 sustainable 现代力量：不致崩溃、可继续的支撑。"}]},"similar":{"note":{"en":"The first group is the sustain family and its noun forms; the second is verbs of keeping something going, each with a different mechanism.","cn":"第一组是 sustain 词族及其名词形式；第二组是“使某物持续”的动词，机制各异。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"sustainable","ipa":"/səˈsteɪnəbl/","tag":"adjective","definition":"able to be kept going over time without damage or collapse.","definitionCN":"可在不损坏、不崩溃的前提下持续。"},{"word":"sustenance","ipa":"/ˈsʌstənəns/","tag":"noun","definition":"food that keeps a person or thing alive; livelihood.","definitionCN":"维持生命的食物；生计。"},{"word":"sustainment","ipa":"/səˈsteɪnmənt/","tag":"formal noun","definition":"the act of sustaining, especially in military logistics.","definitionCN":"维持的行为，尤指军事后勤。"}]},{"heading":"NEAR MEANING","entries":[{"word":"maintain","ipa":"/meɪnˈteɪn/","tag":"keep in condition","definition":"to keep something at the same level or in good repair. It stresses steady condition rather than bearing weight.","definitionCN":"使某物保持同一水平或良好状态。强调稳定状态而非承重。"},{"word":"support","ipa":"/səˈpɔːt/","tag":"hold up","definition":"to bear weight or give help. It is the plain physical word behind sustain.","definitionCN":"承重或给予帮助。是 sustain 背后的朴素物理词。"},{"word":"endure","ipa":"/ɪnˈdjʊə/","tag":"bear patiently","definition":"to suffer something difficult without giving way. It stresses the suffering subject.","definitionCN":"承受艰难而不垮。强调受苦的主体。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: sub- plus tenere, the pillar image, the tenere family (contain, maintain, tenant), and the contrast with survive.","cn":"真实联系：sub- 加 tenere、柱子意象、tenere 词族（contain、maintain、tenant），以及与 survive 的对照。"},"normal":[{"en":"Sub- means 'up from below' and tenere means 'hold'. A sustain is a hand or pillar placed under a weight.","cn":"sub- 意为“自下而上”，tenere 意为“握持”。sustain 就是置于重物下方的手或柱。"},{"en":"The same tenere gives contain, maintain, retain, and tenant: all are ways of holding.","cn":"同一 tenere 给出 contain、maintain、retain、tenant：都是“握持”的方式。"},{"en":"Sustain vs survive: sustain holds something up (sub + tenere); survive lives past it (super + vivere). Same s-, different bones.","cn":"sustain 与 survive：前者托住（sub + tenere），后者活过（super + vivere）。同以 s- 开头，骨架不同。"},{"en":"A judge who sustains an objection makes the objection stand; the question stops.","cn":"法官 sustain 一项异议，就是让异议立住；提问随即停止。"},{"en":"A pedal sustains a chord by holding the sound up in time, the way a pillar holds a roof up in space.","cn":"踏板 sustain 和弦，是在时间中托住声音，正如柱子在空间中托住屋顶。"}],"abstract":[{"en":"Support and duration are one idea here: to sustain is to keep something from falling, whether through space or through time.","cn":"支撑与持续在此是一个念头：sustain 就是不让某物落下，无论在空间中还是时间中。"},{"en":"Every sustained thing borrows its stability from something else; there is no support without a support.","cn":"每个被维持之物都向别处借来稳定；没有支撑者，就没有支撑。"},{"en":"Sustainability asks how long the pillar can bear the load, and whether the load deserves the pillar.","cn":"可持续性问的是柱子还能承重多久，以及这重量是否配得上这根柱子。"}]},"examples":[{"en":"The soil cannot sustain intensive farming for long.","cn":"这片土壤无法长期承载密集耕作。"},{"en":"She sustained a serious injury in the fall.","cn":"她在坠落中受了重伤。"},{"en":"The judge sustained the defense's objection.","cn":"法官支持了辩护方的异议。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“色斯坦”——颜色稳稳地“斯坦”在梁下，顶住屋顶 → sustain 支撑、维持","word":"sustain"},"root":"拉丁语 sustinere“托住、忍受”，由 sub-“自下而上”+ tenere“握持”构成；tenere 追溯到原始印欧语 *ten-“伸展、握持”。","sensesIntro":{"en":"Nine senses of sustain, all one vertical relation: something holds something else up. The weight may be a roof, a habit, a family, a claim, a note, or an ecosystem.","cn":"sustain 的九个义项都是同一种垂直关系：某物把另一物托住。重量可以是屋顶、习惯、家庭、主张、音符或生态系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pillar standing under a beam, bearing its weight.","cn":"核心意象：一根柱子立在梁下，承其重量。"},"chain":["HOLD FROM BELOW","BEAR THE WEIGHT","KEEP IT STANDING","KEEP IT GOING IN TIME","PROVIDE WHAT IT NEEDS","LET IT CARRY MORE"],"branches":[{"senses":"S1 · S7","en":"PHYSICAL SUPPORT: weight is borne by columns, bodies, and selves.","cn":"物理支撑：重量由柱子、身体与自我承担。"},{"senses":"S2 · S4 · S9","en":"CONTINUANCE: practices, families, and ecosystems are kept going by what feeds them.","cn":"持续：实践、家庭与生态系统靠供给而延续。"},{"senses":"S3 · S6","en":"WHAT ONE UNDERGOES: injuries are sustained, and claims are sustained by evidence.","cn":"所承受者：伤害被遭受，主张被证据支持。"},{"senses":"S5","en":"LAW: the judge lets an objection stand, and the trial stops at that point.","cn":"法律：法官让异议立住，庭审在该点停住。"},{"senses":"S8","en":"MUSIC: the note is held up in time, without decay.","cn":"音乐：音符在时间中被托住，不衰减。"}]},"affixes":{"intro":{"en":"Sustain is a Latin verb whose English family includes sustainable, sustenance, and sustainment. The base tenere also gives contain, maintain, tenant, and tenet.","cn":"sustain 是拉丁系动词，英语词族含 sustainable、sustenance、sustainment。词基 tenere 还给出 contain、maintain、tenant、tenet。"},"latinIntro":{"en":"Latin sustinere 'hold up' joins sub- 'from below' and tenere 'hold'. The tenere branch runs through contain, maintain, retain, and tenant; the sub- prefix also appears in support and suppose.","cn":"拉丁语 sustinere“托住”结合 sub-“自下”与 tenere“握持”。tenere 一支贯穿 contain、maintain、retain、tenant；sub- 前缀也见于 support 与 suppose。"},"items":[{"word":"sustainable","structure":"sustain + -able (adjective)","meaning":"able to be maintained without collapse","meaningCN":"可持续的；可承受的（-able 形容词）","example":"sustainable energy","exampleCN":"可持续能源"},{"word":"sustainability","structure":"sustainable + -ity (noun)","meaning":"the capacity to be maintained over time","meaningCN":"可持续性（-ity 名词）","example":"environmental sustainability","exampleCN":"环境可持续性"},{"word":"sustained","structure":"sustain + -ed (participle/adjective)","meaning":"continued steadily over time","meaningCN":"持续的；持久的（过去分词/形容词）","example":"sustained effort","exampleCN":"持续努力"},{"word":"sustaining","structure":"sustain + -ing (participle)","meaning":"keeping something going","meaningCN":"维持的；支撑的（现在分词）","example":"sustaining food","exampleCN":"维持生命的食物"},{"word":"sustainer","structure":"sustain + -er (agent noun)","meaning":"one who or that which sustains","meaningCN":"维持者；支撑物（-er 施事）","example":"the sustainer of the family","exampleCN":"家庭支柱"},{"word":"sustenance","structure":"sustinere + -ance (noun)","meaning":"food and means of livelihood","meaningCN":"食物；生计（-ance 名词）","example":"spiritual sustenance","exampleCN":"精神食粮"},{"word":"sustainment","structure":"sustain + -ment (formal noun)","meaning":"the act of sustaining, especially logistics","meaningCN":"维持；后勤保障（-ment 名词）","example":"aircraft sustainment","exampleCN":"飞机保障"},{"word":"contain","structure":"con- + tenere (same root)","meaning":"to hold within limits","meaningCN":"容纳；包含（同根：con-“共同”+ tenere“握持”）","example":"contain the spread","exampleCN":"遏制扩散"},{"word":"tenant","structure":"tenere + -ant (person noun)","meaning":"one who holds a lease","meaningCN":"租户（同根：握有租约者）","example":"a tenant farmer","exampleCN":"佃农"}],"latinEntries":[{"word":"sustinere","structure":"sub- 'from below' + tenere 'hold'","meaning":"to hold up, bear, endure","meaningCN":"托住；承担；忍受"},{"word":"tenere","structure":"Latin verb","meaning":"to hold, keep, possess","meaningCN":"握持；保持；拥有"},{"word":"sub","structure":"Latin preposition","meaning":"under, up from below","meaningCN":"在下；自下而上"},{"word":"tenax","structure":"from tenere","meaning":"holding fast, tenacious","meaningCN":"紧握的；顽固的"}]}},{"word":"symbol","ipa_uk":"/ˈsɪmbl/","ipa_us":"/ˈsɪmbl/","definition_zh":"符号；象征；标志；记号；（化/数）符号；信经（古）；象征（罕作动词）","definition_en":"a mark or object that stands for something else, especially an idea or quality","core_image":"两半陶片对在一起，缺口严丝合缝，凭它认出彼此是旧约之人","scene":"广场上放飞了一只白鸽。The white dove is a symbol of peace; it is only a bird, yet people use it to stand for a whole hope.","sceneCN":"这里 symbol 是「象征」（第 2 个义项：用具体物象代表抽象观念）；句意：白鸽是和平的象征；它只是一只鸟，人们却用它代表一整个愿望。图中可辨识物件：白鸽、橄榄枝、广场人群、旗帜、蓝天。","pos":[{"tag":"n.","zh":"符号；象征；标志；记号"},{"tag":"v.","zh":"象征；用符号表示（罕用）"}],"collocations":[{"phrase":"a symbol of peace","zh":"和平的象征"},{"phrase":"chemical symbol","zh":"化学符号"},{"phrase":"status symbol","zh":"身份象征"},{"phrase":"a national symbol","zh":"国家象征"},{"phrase":"symbolic meaning","zh":"象征意义"},{"phrase":"map symbols","zh":"地图符号"}],"forms":[{"label":"复数","form":"symbols"},{"label":"动词","form":"symbolize / symbolise"},{"label":"形容词","form":"symbolic"},{"label":"副词","form":"symbolically"}],"derivatives":[{"word":"symbolic","pos":"adj.","zh":"象征的；符号的"},{"word":"symbolism","pos":"n.","zh":"象征主义；象征体系"},{"word":"symbolize","pos":"v.","zh":"象征；代表"},{"word":"symbology","pos":"n.","zh":"符号学；象征体系"}],"senses":[{"no":"01","title":"A sign standing for something","titleCN":"符号；标记","definition":"a mark, shape, or object used to represent something else","definitionCN":"用来代表他物的记号、形状或物件","example":"In the map, a triangle is the symbol for a campsite.","exampleCN":"在地图上，三角形是营地的符号。","why":"Greek symbolon was a token matched to its other half. A symbol is not the thing but a stand-in that can be recognised and exchanged.","whyCN":"希腊语 symbolon 是与另一半相配的信物。符号不是物本身，而是可被认出、可被交换的替身。"},{"no":"02","title":"An emblem of an idea","titleCN":"象征","definition":"a visible thing used to represent an abstract idea or quality","definitionCN":"用可见之物代表抽象观念或性质","example":"The dove is a symbol of peace.","exampleCN":"鸽子是和平的象征。","why":"The abstract sense grows from the token: a concrete object is trusted to carry an invisible meaning. The dove does not explain peace; it lets people point at it.","whyCN":"抽象义从信物生长：一个具体物被托付承载无形意义。鸽子不解释和平，它让人可以指向和平。"},{"no":"03","title":"A written character","titleCN":"书写符号；字符","definition":"a letter, character, or mark used in writing or notation","definitionCN":"书写或记谱所用的字母、字符或记号","example":"The symbol on the page was a rune.","exampleCN":"纸上的符号是一个如尼字母。","why":"Writing is the most systematic symbol system: marks are arbitrarily tied to sounds or meanings by convention, not by resemblance.","whyCN":"书写是最系统的符号系统：记号与声音或意义按约定相连，而非靠相似。"},{"no":"04","title":"Chemical or mathematical notation","titleCN":"化学/数学符号","definition":"a standard letter or sign for an element, operation, or quantity","definitionCN":"表示元素、运算或量的标准字母或记号","example":"Fe is the chemical symbol for iron.","exampleCN":"Fe 是铁的化学符号。","why":"Science needs symbols that are unambiguous and international. Here the token is exact: one mark, one element, no poetic residue.","whyCN":"科学需要无歧义且国际通用的符号。此处信物是精确的：一个记号对应一种元素，不留诗意残余。"},{"no":"05","title":"A status symbol","titleCN":"身份象征","definition":"an object whose possession signals wealth, taste, or rank","definitionCN":"拥有即显示财富、品味或地位的物件","example":"A luxury watch is a status symbol.","exampleCN":"名表是一种身份象征。","why":"Consumer culture makes objects into tokens of social position. The thing is still a thing, but its meaning is read by others as a claim about the owner.","whyCN":"消费文化把物件变成社会位置的信物。物仍是物，但其意义被他人读作关于拥有者的主张。"},{"no":"06","title":"A psychoanalytic symbol","titleCN":"精神分析象征","definition":"an image whose meaning is unconscious or dream-like","definitionCN":"意义属无意识或梦境层面的意象","example":"In dream analysis, water is often read as a symbol of the unconscious.","exampleCN":"在释梦中，水常被读作无意识的象征。","why":"Depth psychology extends the emblem to the inner life: images carry meanings the dreamer does not consciously intend. The symbol becomes a message from below.","whyCN":"深度心理学把象征扩展到内心生活：意象承载梦者并未有意安排的意义。符号成了来自下方的讯息。"},{"no":"07","title":"The creed (archaic)","titleCN":"信经（古义）","definition":"in early Christian usage, a formal statement of faith, especially the Apostles' Creed","definitionCN":"早期基督教用法：正式信仰陈述，尤指使徒信经","example":"The minister recited the Symbol.","exampleCN":"牧师诵读了信经。","why":"This is the earliest English sense, from Latin symbolum 'creed'. A creed is a token of identity: reciting it shows which community you belong to.","whyCN":"这是最早的英语义，出自拉丁 symbolum“信经”。信经是身份信物：诵读它便显示你属于哪个群体。"},{"no":"08","title":"A mark in notation","titleCN":"记谱记号","definition":"a written sign in music, dance, or a technical system","definitionCN":"音乐、舞蹈或技术体系中的书写记号","example":"The score uses a special symbol for a repeat.","exampleCN":"乐谱用特殊记号表示反复。","why":"Notation systems multiply symbols so that complex actions can be read at a glance. The mark is an instruction as well as a sign.","whyCN":"记谱系统增殖符号，使复杂动作可一眼读出。记号既是符号，也是指令。"},{"no":"09","title":"To symbolize (rare verb)","titleCN":"象征；以符号表示（罕用动词）","definition":"to represent by a symbol; to stand for","definitionCN":"用符号代表；象征","example":"The painting symbols the passage of time.","exampleCN":"这幅画象征时间的流逝。","why":"The verb is rare beside symbolize. It treats the act of representation as a making: the artist puts a mark in place of an idea.","whyCN":"动词远少于 symbolize。它把“代表”的动作视为一种制作：艺术家把记号放在观念的位置上。"}],"etymology":{"intro":{"en":"Symbol came through Latin symbolum from Greek symbolon, 'token, tally, mark'. The Greek verb symballein means 'to throw together': syn- 'together' plus ballein 'to throw'. The original symbol was a broken object whose two halves, thrown together again, proved identity.","cn":"symbol 经拉丁 symbolum 出自希腊语 symbolon“信物、符木、记号”。希腊动词 symballein 意为“扔在一起”：syn-“一起”加 ballein“扔”。最初的 symbol 是一件被掰开的物件，两半再次合拢，便证明身份。"},"items":[{"era":"15C","en":"English takes the word from Latin symbolum, first in the religious sense of a creed or profession of faith.","cn":"英语自拉丁 symbolum 借入，最早为信经或信仰声明的宗教义。"},{"era":"GREEK","en":"symbolon means 'token, tally, contract, sign'. It is a thing thrown together with another to be matched.","cn":"symbolon 意为“信物、符木、契约、记号”。它是与另一物合拢以相配之物。"},{"era":"GREEK","en":"The verb symballein is syn- 'together' plus ballein 'to throw'. Two halves are thrown together and compared.","cn":"动词 symballein 是 syn-“一起”加 ballein“扔”。两半被扔到一起并比对。"},{"era":"PIE","en":"ballein is traced to PIE *gʷel- 'to throw', a reconstruction also behind ballistics and the Greek root of problem.","cn":"ballein 被追溯到原始印欧语 *gʷel-“投掷”，同一重构也见于 ballistics 与 problem 的希腊词根。"},{"era":"16C","en":"The sense widens from creed to any sign or emblem: a mark that stands for something else.","cn":"十六世纪义项从信经扩展到任何记号或标志：代表他物的标记。"},{"era":"MODERN","en":"Modern technical systems add chemical, mathematical, and musical symbols, where the token is exact and convention-bound.","cn":"现代技术体系增加化学、数学与音乐符号，其信物精确且受约定约束。"}]},"similar":{"note":{"en":"The first group is the symbol/symbolic family; the second is other words for a thing that stands for something else.","cn":"第一组是 symbol 与 symbolic 词族；第二组是“代表他物之物”的其他词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"symbolic","ipa":"/sɪmˈbɒlɪk/","tag":"adjective","definition":"serving as a symbol; representing something abstract.","definitionCN":"作为象征的；代表抽象之物的。"},{"word":"symbolize","ipa":"/ˈsɪmbəlaɪz/","tag":"verb","definition":"to be a symbol of; to represent by a symbol.","definitionCN":"是…的象征；用符号表示。"},{"word":"symbolism","ipa":"/ˈsɪmbəlɪzəm/","tag":"noun","definition":"the use of symbols, especially in art and literature.","definitionCN":"象征的使用，尤指艺术与文学。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sign","ipa":"/saɪn/","tag":"general marker","definition":"a mark, gesture, or object that conveys information. It is broader and often more direct than symbol.","definitionCN":"传达信息的记号、手势或物件。比 symbol 更广，常更直接。"},{"word":"emblem","ipa":"/ˈembləm/","tag":"identifying badge","definition":"an object or image that identifies a group or idea, often officially.","definitionCN":"识别群体或观念的物件或图像，常具官方性。"},{"word":"token","ipa":"/ˈtəʊkən/","tag":"concrete stand-in","definition":"a physical object used as a sign, voucher, or proof. It keeps the original 'matched half' flavour.","definitionCN":"用作记号、凭据或证明的实物。保留“相配的一半”的原味。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: syn- plus ballein 'throw together', the two halves of a token, the creed sense, and the exact symbols of science.","cn":"真实联系：syn- 加 ballein“扔在一起”、信物的两半、信经义，以及科学的精确符号。"},"normal":[{"en":"Syn- means 'together' and ballein means 'throw'. A symbolon was two halves thrown together and matched.","cn":"syn- 意为“一起”，ballein 意为“扔”。symbolon 是两半扔在一起并对上。"},{"en":"The word's first English life was religious: the creed is the token by which you show your community.","cn":"这个词在英语中的第一段生命是宗教的：信经是你显示所属群体的信物。"},{"en":"A symbol is a stand-in, not a copy. The dove does not resemble peace; it is trusted to carry it.","cn":"符号是替身，不是复制品。鸽子不像和平；它被托付承载和平。"},{"en":"Science wants exact tokens: Fe means iron and nothing else. Poetry wants loose ones: water can mean many things.","cn":"科学要精确信物：Fe 只指铁。诗要松散信物：水可指许多东西。"},{"en":"Status symbols work because others read the object as a claim about you.","cn":"身份象征之所以有效，是因为他人把该物读作关于你的主张。"}],"abstract":[{"en":"A symbol is a contract: a community agrees that this mark will stand for that meaning.","cn":"符号是一份契约：社群同意此记号代表彼意义。"},{"en":"Every symbol is both a window and a screen; it shows an idea and hides the labour that made the link.","cn":"每个符号既是窗也是屏；它显示观念，也遮住造出这一连接的努力。"},{"en":"The same object can be a tool, a commodity, and a symbol at once; meaning is a layer added to use.","cn":"同一物件可同时是工具、商品与符号；意义是加在用途之上的一层。"}]},"examples":[{"en":"The ring is a symbol of their marriage.","cn":"这枚戒指是他们婚姻的象征。"},{"en":"O is the chemical symbol for oxygen.","cn":"O 是氧的化学符号。"},{"en":"In the painting, the caged bird is a symbol of lost freedom.","cn":"画中笼中鸟是失去自由的象征。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“心不落”——心里放不下的东西，总要找个记号挂住 → symbol 符号、象征","word":"symbol"},"root":"希腊语 symbolon“信物、符木、记号”，出自 symballein“扔在一起”（syn-“一起”+ ballein“扔”）；经拉丁 symbolum 入英语。","sensesIntro":{"en":"Nine senses of symbol: a token that stands in for something else. The something may be an idea, a sound, an element, a social rank, an unconscious image, or a community's faith.","cn":"symbol 的九个义项：一个替另一物站位的信物。那“另一物”可以是观念、声音、元素、社会等级、无意识意象或社群信仰。"},"semanticMap":{"core":{"en":"CORE IMAGE: two halves of a broken token matched to prove identity.","cn":"核心意象：信物被掰成两半，合拢以证身份。"},"chain":["THROW TOGETHER","MATCH THE HALVES","RECOGNISE A STAND-IN","CARRY AN IDEA","FIX A CONVENTION","READ THE DEEPER MEANING"],"branches":[{"senses":"01 · 03 · 08","en":"MARKS: written characters and notation signs are exact, learnable stand-ins.","cn":"记号：书写字符与记谱记号是精确、可学的替身。"},{"senses":"02 · 05 · 09","en":"MEANING IN SOCIETY: doves carry peace, watches carry rank, and the rare verb turns that carrying into an act.","cn":"社会中的意义：鸽子承载和平，名表承载等级，罕用的动词则把这种承载变成动作。"},{"senses":"04","en":"SCIENCE: the token is exact and international, one mark for one element.","cn":"科学：信物精确且国际通用，一记号对一元素。"},{"senses":"06","en":"THE UNCONSCIOUS: an image carries a message the dreamer did not intend.","cn":"无意识：意象承载梦者未曾安排的信息。"},{"senses":"07","en":"CREED: reciting the symbol shows which community you belong to.","cn":"信经：诵读信经显示你属于哪个群体。"}]},"affixes":{"intro":{"en":"Symbol is a Greek-derived noun; English adds -ic, -ize, -ism, and -logy. The Greek root ballein 'throw' also appears in problem and diabolic, which are not about signs but about what is thrown.","cn":"symbol 是希腊系名词；英语加 -ic、-ize、-ism、-logy。希腊词根 ballein“扔”也见于 problem 与 diabolic，它们不关符号，而关“被扔出之物”。"},"latinIntro":{"en":"Greek symbolon 'token' comes from symballein 'throw together'. Latin took it as symbolum, and English took the Latin. The same ballein underlies problem (something thrown forward) and diabolic (something thrown across).","cn":"希腊语 symbolon“信物”出自 symballein“扔在一起”。拉丁取为 symbolum，英语再取拉丁。同一 ballein 也支撑 problem（被扔到前面之物）与 diabolic（被扔到对面之物）。"},"items":[{"word":"symbolic","structure":"symbol + -ic (adjective)","meaning":"of or acting as a symbol","meaningCN":"象征的；符号的（-ic 形容词）","example":"a symbolic gesture","exampleCN":"象征性姿态"},{"word":"symbolically","structure":"symbolic + -ally (adverb)","meaning":"in a symbolic manner","meaningCN":"象征性地（-ally 副词）","example":"symbolically important","exampleCN":"具有象征意义"},{"word":"symbolize","structure":"symbol + -ize (verb)","meaning":"to stand for or represent","meaningCN":"象征；代表（-ize 动词）","example":"a dove symbolizes peace","exampleCN":"鸽子象征和平"},{"word":"symbolism","structure":"symbol + -ism (noun)","meaning":"the use or system of symbols","meaningCN":"象征主义；象征体系（-ism 名词）","example":"religious symbolism","exampleCN":"宗教象征体系"},{"word":"symbolist","structure":"symbol + -ist (noun)","meaning":"an artist or adherent of symbolism","meaningCN":"象征主义者（-ist 名词）","example":"a symbolist poet","exampleCN":"象征派诗人"},{"word":"symbology","structure":"symbol + -logy (noun)","meaning":"the study or system of symbols","meaningCN":"符号学；象征体系（-logy 名词）","example":"ancient symbology","exampleCN":"古代符号体系"},{"word":"symbolization","structure":"symbolize + -ation (noun)","meaning":"the act of representing by symbols","meaningCN":"符号化；象征化（-ation 名词）","example":"dream symbolization","exampleCN":"梦境象征化"},{"word":"problem","structure":"pro- + ballein (same Greek root)","meaning":"a question thrown forward for solution","meaningCN":"问题（同根：pro-“向前”+ ballein“扔”）","example":"solve a problem","exampleCN":"解决问题"},{"word":"diabolic","structure":"dia- + ballein (same Greek root)","meaning":"thrown across; devilish","meaningCN":"恶魔般的（同根：dia-“穿越”+ ballein“扔”）","example":"a diabolic plan","exampleCN":"恶魔般的计划"}],"latinEntries":[{"word":"symbolon","structure":"syn- 'together' + ballein 'throw'","meaning":"token, tally, sign","meaningCN":"信物；符木；记号"},{"word":"symbolum","structure":"Latin from Greek","meaning":"creed, token, mark","meaningCN":"信经；信物；记号"},{"word":"symballein","structure":"Greek verb","meaning":"to throw together, compare","meaningCN":"扔在一起；比对"},{"word":"ballein","structure":"Greek verb","meaning":"to throw","meaningCN":"投掷"}]}},{"word":"target","ipa_uk":"/ˈtɑːɡɪt/","ipa_us":"/ˈtɑːrɡɪt/","definition_zh":"靶子；目标；目标对象；（攻击/批评的）对象；瞄准；把…作为目标；面向（特定群体）；（物理）靶核","definition_en":"an object aimed at or attacked; a goal to be reached; to aim at or direct something toward","core_image":"箭离弦，钉进红白同心圆的正中心","scene":"公司把年轻租房者定为主要目标。The company made young renters its main target and put all its advertising on the apps they use every day.","sceneCN":"这里 target 是「目标对象、目标群体」（第 2 个义项：行动所要达到或影响的对象）；句意：公司把年轻租房者定为主要目标群体，广告全投在他们每天用的应用上。图中可辨识物件：广告看板、手机界面、年轻租客、城市公寓楼、数据图表。","pos":[{"tag":"n.","zh":"靶子；目标；目标对象；靶核"},{"tag":"v.","zh":"瞄准；把…作为目标；面向"},{"tag":"adj.","zh":"目标的；有针对性的"}],"collocations":[{"phrase":"hit the target","zh":"命中目标"},{"phrase":"target audience","zh":"目标受众"},{"phrase":"target market","zh":"目标市场"},{"phrase":"a target of criticism","zh":"批评的对象"},{"phrase":"target practice","zh":"打靶练习"},{"phrase":"set a target","zh":"设定目标"}],"forms":[{"label":"复数","form":"targets"},{"label":"第三人称单数","form":"targets"},{"label":"现在分词","form":"targeting（英式亦作 targetting）"},{"label":"过去式/过去分词","form":"targeted（英式亦作 targetted）"}],"derivatives":[{"word":"targeted","pos":"adj.","zh":"有针对性的；目标明确的"},{"word":"targeting","pos":"n.","zh":"目标定位；瞄准"},{"word":"targetable","pos":"adj.","zh":"可作为目标的"},{"word":"untargeted","pos":"adj.","zh":"无目标的；未定向的"}],"senses":[{"no":"01","title":"An object aimed at","titleCN":"靶子；标的","definition":"a physical object that one aims at in shooting or throwing","definitionCN":"射击或投掷时所瞄的实物","example":"The arrow hit the centre of the target.","exampleCN":"箭射中了靶心。","why":"The word began as a small shield. A shield set up for practice became the thing aimed at, and the name of the shield became the name of the mark.","whyCN":"这个词最初指小盾。练习时立起的盾成了瞄准之物，盾的名称于是变成靶的名称。"},{"no":"02","title":"A goal to be reached","titleCN":"目标；指标","definition":"a result or level that one aims to achieve","definitionCN":"意欲达到的结果或水平","example":"The company set a target of 20% growth.","exampleCN":"公司设定了 20% 增长的目标。","why":"Business and policy turn the physical mark into a number. The target is still something you aim at, but success is now measured rather than seen.","whyCN":"商业与政策把物理靶变成数字。目标仍是所瞄之物，但成败改为可测量，而非可见。"},{"no":"03","title":"An object of attack or criticism","titleCN":"攻击/批评的对象","definition":"a person or thing that others attack, blame, or focus on","definitionCN":"被攻击、指责或聚焦的人或物","example":"The minister became the target of angry questions.","exampleCN":"部长成了愤怒质询的靶子。","why":"Hostility also needs a mark. The metaphor keeps the archery shape: words and blame are loosed at someone who stands in the centre.","whyCN":"敌意也需要一个靶。隐喻保留射箭形状：言语与责难射向站在中心的人。"},{"no":"04","title":"To aim at","titleCN":"瞄准","definition":"to point a weapon or object at a target","definitionCN":"把武器或物件对准目标","example":"The camera targeted the bird and focused.","exampleCN":"相机对准那只鸟并合焦。","why":"The verb restores the original act: selecting one point out of the field and aligning a tool with it.","whyCN":"动词恢复原初动作：从场域中选出一点，并让工具与之对齐。"},{"no":"05","title":"To direct criticism at","titleCN":"把…作为批评对象","definition":"to make someone the object of criticism, blame, or action","definitionCN":"使某人成为批评、责难或行动的对象","example":"The report targets wasteful spending.","exampleCN":"报告把浪费性开支作为批评对象。","why":"Abstract verbs of attack borrow the physical aim. To target a practice is to single it out and fire language at it.","whyCN":"抽象的“攻击”动词借用物理瞄准。target 某项做法，就是把它单独挑出，向它发射语言。"},{"no":"06","title":"To select a group for action","titleCN":"面向；定向","definition":"to choose a group or area as the object of a product, policy, or campaign","definitionCN":"把某群体或区域选为产品、政策或运动的对象","example":"The ad targets first-time buyers.","exampleCN":"这则广告面向首次购房者。","why":"Marketing reverses the arrow: instead of the shooter choosing a mark, the message is fitted to a chosen audience. Selection comes before aiming.","whyCN":"营销反转了箭：不是射手选靶，而是让讯息适配选定受众。挑选先于瞄准。"},{"no":"07","title":"Attributive: intended for a target","titleCN":"目标的；有针对性的（定语）","definition":"used before a noun for the group, level, or result aimed at","definitionCN":"置于名词前，指所对准的群体、水平或结果","example":"target customers, target price","exampleCN":"目标客户、目标价格","why":"The noun becomes an adjective without changing shape. English often does this: a target market is a market that has been targeted.","whyCN":"名词不改变形态即作形容词。英语常见此用法：target market 就是被瞄准的市场。"},{"no":"08","title":"A target nucleus (physics)","titleCN":"（物理）靶核","definition":"the nucleus struck by a projectile in an experiment","definitionCN":"实验中遭射弹轰击的原子核","example":"Neutrons were fired at a uranium target.","exampleCN":"中子被射向一个铀靶。","why":"Physics keeps the oldest sense almost literally: a material is placed in the beam so that particles can hit it. The target is still a thing stood up to be struck.","whyCN":"物理学几乎字面保留最古老义：把材料置于束流中，让粒子撞击。靶仍是立起来受击之物。"},{"no":"09","title":"Hitting the mark","titleCN":"命中；中的","definition":"the successful striking of the target, especially in sport","definitionCN":"成功击中目标，尤指运动","example":"Three shots hit the target in a row.","exampleCN":"三枪连续命中。","why":"This nominal use keeps the result in view. The target is not only the thing aimed at but the event of reaching it, which is why 'on target' can mean both accurate and on schedule.","whyCN":"这一名词用法把结果留在视野里。靶不仅是被瞄之物，也是“到达”的事件，故 on target 既可指准，也可指按期。"}],"etymology":{"intro":{"en":"Target first meant a small shield, from Old French targette, a diminutive of targe 'shield'. The shield's origin is uncertain, often referred to Frankish *targa. In the sixteenth century a shield set up for practice became the mark aimed at, and the word followed the arrow.","cn":"target 最早指小盾，出自古法语 targette（targe“盾”的指小形式）。targe 的来源不确定，常被追溯到法兰克语 *targa。十六世纪，练习时立起的盾成了瞄准的标的，词义便跟着箭走。"},"items":[{"era":"C.1400","en":"The word is recorded in English as 'a small shield', especially a light round one.","cn":"该词在英语中最早记录为“小盾”，尤指轻便的圆盾。"},{"era":"OLD FRENCH","en":"targette is a diminutive of targe 'shield'; the -ette ending makes it small.","cn":"targette 是 targe“盾”的指小形式；-ette 词尾表小。"},{"era":"UNCERTAIN","en":"The deeper origin of targe is uncertain. It is often traced to Frankish *targa 'shield', but the reconstruction is not securely attested.","cn":"targe 的更早来源不确定。常被追溯到法兰克语 *targa“盾”，但这一重构并无确证。"},{"era":"16C","en":"A shield or board set up for archery practice becomes 'the mark aimed at'; the name of the shield transfers to the mark.","cn":"十六世纪，为射箭练习立起的盾或板变成“瞄准的标的”；盾的名称转到标的之上。"},{"era":"19C","en":"Firearms and artillery extend the word to any object fired at, and 'target practice' becomes a fixed phrase.","cn":"十九世纪枪炮把词扩展到任何被射击之物，target practice 成为固定短语。"},{"era":"20C","en":"Business and policy add the abstract senses: target market, target date, performance targets.","cn":"二十世纪商业与政策加入抽象义：目标市场、目标日期、绩效指标。"}]},"similar":{"note":{"en":"The first group is the shield family and its derivatives; the second is words for an aim, each with a different kind of endpoint.","cn":"第一组是“盾”词族及其派生；第二组是表示“目标”的词，各自的终点性质不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"targe","ipa":"/tɑːdʒ/","tag":"archaic noun","definition":"a shield, especially a small round one. It is the base behind target.","definitionCN":"盾，尤指小圆盾。是 target 的词基。"},{"word":"targeteer","ipa":"/ˌtɑːɡɪˈtɪə/","tag":"rare noun","definition":"a soldier armed with a target or shield.","definitionCN":"持盾的士兵（罕用）。"},{"word":"targeted","ipa":"/ˈtɑːɡɪtɪd/","tag":"adjective","definition":"aimed at a particular person or group.","definitionCN":"针对特定人或群体的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"goal","ipa":"/ɡəʊl/","tag":"desired result","definition":"the result one wants to achieve. It stresses intention rather than measurement.","definitionCN":"想要达到的结果。强调意图而非测量。"},{"word":"objective","ipa":"/əbˈdʒektɪv/","tag":"formal aim","definition":"a specific aim set out in planning. It is more formal and often more concrete than goal.","definitionCN":"计划中设定的具体目的。比 goal 更正式、常更具体。"},{"word":"aim","ipa":"/eɪm/","tag":"pointing and purpose","definition":"the act of pointing at something, or the purpose behind it. It keeps both the physical and mental senses.","definitionCN":"瞄准的动作或其背后的目的。兼含物理与心理义。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: targe 'shield', the practice shield that became a mark, the business sense, and the targeted/targeting family.","cn":"真实联系：targe“盾”、由练习盾变成的靶、商业义，以及 targeted 与 targeting 词族。"},"normal":[{"en":"Target began as a small shield. Put a shield up for practice and it becomes the thing you aim at.","cn":"target 最初是小盾。把盾立起来练习，它就变成你瞄准之物。"},{"en":"The arrow sense gives the verb: to target is to pick one point out of the field and align with it.","cn":"箭义给出动词：target 就是从场域中选一点并对准。"},{"en":"A business target is a mark turned into a number: you can miss it without seeing it.","cn":"商业目标是变成数字的靶：你看不见它，却可能打不中。"},{"en":"Targeting an audience reverses the arrow: the message is fitted to the chosen group.","cn":"target 受众反转了箭：讯息被调整以适配选定群体。"},{"en":"In physics the target is almost literal: a material stood in the beam to be struck.","cn":"物理学中的靶几乎是字面义：立在束流中受击的材料。"}],"abstract":[{"en":"A target is a decision about where attention should go; to have one is to accept ignoring everything else.","cn":"靶是关于注意力去向的决定；有靶就意味着接受忽略其余一切。"},{"en":"The word hides a reversal: sometimes we aim at what we want, sometimes what we want is shaped by where we aim.","cn":"这个词藏着反转：有时我们瞄准所欲，有时所欲又被所瞄之处塑形。"},{"en":"Measured targets can replace felt goals, and then the number becomes the thing rather than the sign.","cn":"可测量的指标会取代可感的目标，数字于是从事物之记号变成事物本身。"}]},"examples":[{"en":"The bullet missed the target by a few centimetres.","cn":"子弹偏离靶心几厘米。"},{"en":"The campaign targets young voters in cities.","cn":"这场运动面向城市年轻选民。"},{"en":"The factory missed its production target last quarter.","cn":"工厂上季度未达到生产目标。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“他get”——箭射出去，“他 get 到了”靶心 → target 靶子、目标","word":"target"},"root":"古法语 targette（targe“小盾”的指小形式），targe 来源不确定，常追溯至法兰克语 *targa“盾”；十六世纪由练习用盾转为“靶”。","sensesIntro":{"en":"Nine senses of target, all one geometry: something is singled out and something is directed at it. What is directed may be an arrow, a camera, a criticism, an advertisement, or a beam of particles.","cn":"target 的九个义项都是同一几何：某物被单独选出，另一物朝它而去。朝它而去的可以是箭、相机、批评、广告或粒子束。"},"semanticMap":{"core":{"en":"CORE IMAGE: an arrow finding the centre of a round mark.","cn":"核心意象：箭钉进圆形靶心。"},"chain":["A SHIELD STOOD UP","THE MARK AIMED AT","THE GOAL TO REACH","THE OBJECT OF ATTACK","THE AUDIENCE SELECTED","THE THING STRUCK IN AN EXPERIMENT"],"branches":[{"senses":"S1 · S9","en":"THE PHYSICAL MARK: a thing stood up to be hit, and the event of hitting it.","cn":"物理靶：立起来受击之物，以及击中它的事件。"},{"senses":"S2 · S7","en":"THE GOAL: a desired result, often measured, often used attributively.","cn":"目标：意欲的结果，常被测量，常作定语。"},{"senses":"S3 · S5","en":"THE OBJECT OF ATTACK: blame and criticism are loosed at a chosen person or practice.","cn":"攻击对象：责难与批评射向选定的人或做法。"},{"senses":"S4 · S6","en":"AIMING AND SELECTING: a tool is aligned; an audience is chosen and the message fitted.","cn":"瞄准与挑选：工具被对齐；受众被选定，讯息被适配。"},{"senses":"S8","en":"PHYSICS: material is placed in a beam so that particles can strike it.","cn":"物理：材料置于束流中，供粒子撞击。"}]},"affixes":{"intro":{"en":"Target is a French-derived noun with the diminutive -ette. English adds -ed, -ing, and -able, and keeps the archaic base targe. The suffix -ette is no longer felt as a living diminutive in target.","cn":"target 是带指小后缀 -ette 的法语系名词。英语加 -ed、-ing、-able，并保留古词基 targe。-ette 在 target 中已不再被感知为活的指小后缀。"},"latinIntro":{"en":"There is no Latin source here. Target comes from Old French targe/targette, probably from Frankish *targa 'shield', a Germanic borrowing whose exact form is uncertain.","cn":"此处没有拉丁来源。target 出自古法语 targe/targette，可能来自法兰克语 *targa“盾”，属日耳曼借词，确切形式不确定。"},"items":[{"word":"targets","structure":"target + -s (plural/3sg)","meaning":"more than one target; he/she aims","meaningCN":"靶子（复数）；瞄准（三单）","example":"two targets","exampleCN":"两个靶"},{"word":"targeted","structure":"target + -ed (past participle)","meaning":"aimed at; singled out","meaningCN":"被瞄准的；有针对性的（过去分词）","example":"targeted support","exampleCN":"定向支持"},{"word":"targeting","structure":"target + -ing (gerund)","meaning":"the act of aiming or selecting","meaningCN":"瞄准；定向（动名词）","example":"precision targeting","exampleCN":"精准定向"},{"word":"targetable","structure":"target + -able (adjective)","meaning":"able to be targeted","meaningCN":"可作为目标的（-able 形容词）","example":"a targetable audience","exampleCN":"可定向的受众"},{"word":"untargeted","structure":"un- + targeted (adjective)","meaning":"not aimed at a particular group","meaningCN":"无针对性的（un- 否定）","example":"untargeted advertising","exampleCN":"非定向广告"},{"word":"multitarget","structure":"multi- + target (compound)","meaning":"involving several targets","meaningCN":"多靶点的（复合词）","example":"multitarget drugs","exampleCN":"多靶点药物"},{"word":"targe","structure":"Old French targe (noun)","meaning":"a shield, especially a small round one","meaningCN":"小圆盾（古词基）","example":"a targe and sword","exampleCN":"盾与剑"},{"word":"targeteer","structure":"target + -eer (rare agent noun)","meaning":"a shield-bearing soldier","meaningCN":"持盾士兵（罕用施事名词）","example":"an old targeteer","exampleCN":"一名老持盾兵"},{"word":"targetless","structure":"target + -less (rare adjective)","meaning":"having no target","meaningCN":"无靶的；无目标的（罕用）","example":"targetless practice","exampleCN":"无靶练习"}],"latinEntries":[{"word":"targe","structure":"Old French noun","meaning":"shield","meaningCN":"盾"},{"word":"targette","structure":"diminutive of targe","meaning":"small shield","meaningCN":"小盾"},{"word":"*targa","structure":"Frankish (uncertain)","meaning":"shield","meaningCN":"盾（重构，存疑）"},{"word":"target","structure":"English from Old French","meaning":"mark aimed at","meaningCN":"瞄准的标的"}]}},{"word":"task","ipa_uk":"/tɑːsk/","ipa_us":"/tæsk/","definition_zh":"任务；工作；分派的工作；艰巨的事；（计算机）任务；分派任务；使吃力；责备（习语）","definition_en":"a piece of work to be done, especially one assigned by another; to assign work to someone; to strain","core_image":"桌上压着一张写满待办的纸条，第一行被红笔圈住","scene":"经理把整理客户资料的工作交给了实习生。The task went to the intern, and the deadline was only two days away.","sceneCN":"这里 task 是「任务、分派的工作」（第 2 个义项：由他人指派的工作）；句意：这项任务交给了实习生，期限只有两天。图中可辨识物件：待办清单、文件夹、工位电脑、日历、红笔圈注。","pos":[{"tag":"n.","zh":"任务；工作；分派的工作；艰巨之事"},{"tag":"v.","zh":"分派任务；使吃力；责备（用于 take to task）"}],"collocations":[{"phrase":"complete a task","zh":"完成任务"},{"phrase":"a difficult task","zh":"艰巨的任务"},{"phrase":"task force","zh":"特别工作组"},{"phrase":"take sb to task","zh":"责备某人"},{"phrase":"multitask","zh":"多任务处理"},{"phrase":"a routine task","zh":"例行工作"}],"forms":[{"label":"复数","form":"tasks"},{"label":"第三人称单数","form":"tasks"},{"label":"现在分词","form":"tasking"},{"label":"过去式/过去分词","form":"tasked"},{"label":"复合词","form":"multitask / task force"}],"derivatives":[{"word":"tasking","pos":"n.","zh":"任务分派；任务分配"},{"word":"tasked","pos":"adj.","zh":"被分派任务的"},{"word":"multitask","pos":"v.","zh":"同时处理多项任务"},{"word":"taskmaster","pos":"n.","zh":"监工；严厉的工头"}],"senses":[{"no":"01","title":"A piece of work","titleCN":"任务；工作","definition":"a unit of work that has to be done","definitionCN":"必须完成的一项工作","example":"Cleaning the kitchen is a thankless task.","exampleCN":"打扫厨房是件不讨好的活。","why":"The word names work as a countable unit: not labour in general, but this job, with a beginning and an end.","whyCN":"这个词把工作命名为可数单位：不是泛泛的劳动，而是这一件有始有终的活。"},{"no":"02","title":"An assigned duty","titleCN":"分派的任务","definition":"work given to someone by a superior or by circumstance","definitionCN":"由上级或情势交给某人的工作","example":"The manager gave her the task of training new staff.","exampleCN":"经理把培训新员工的任务交给了她。","why":"Assignment adds a second party. A task is not merely work that exists; it is work laid on someone, carrying obligation and often a deadline.","whyCN":"“分派”引入第二方。任务不只是存在的工作；它是加到某人身上的工作，带义务，常带期限。"},{"no":"03","title":"A difficult undertaking","titleCN":"艰巨的任务","definition":"a job that demands serious effort or endurance","definitionCN":"需要大量努力或耐力的工作","example":"Rebuilding the bridge was a huge task.","exampleCN":"重建这座桥是一项艰巨任务。","why":"English often uses task where the difficulty is the point. The word can carry a sigh: it is work that weighs.","whyCN":"英语常在“难度即重点”时用 task。这个词可带一声叹息：它是压人的活。"},{"no":"04","title":"A computing task","titleCN":"（计算机）任务","definition":"a unit of work run by a computer, often one process among many","definitionCN":"计算机执行的工作单位，常指众多进程之一","example":"The system runs several tasks at once.","exampleCN":"系统同时运行多个任务。","why":"Computing borrows the managerial unit: a job is broken into tasks that the machine schedules. The metaphor is industrial, not mental.","whyCN":"计算借用了管理单位：作业被拆成任务，由机器调度。隐喻是工业的，不是心智的。"},{"no":"05","title":"To assign work","titleCN":"分派任务","definition":"to give someone a particular job to do","definitionCN":"交给某人特定工作","example":"She was tasked with writing the report.","exampleCN":"她被分派撰写报告。","why":"The verb turns the noun into an act of management. It is usually passive or formal, because the assigner is the one with power.","whyCN":"动词把名词变成管理行为。它常用被动或正式语体，因为分派者才是掌权者。"},{"no":"06","title":"To strain or burden","titleCN":"使吃力；使费劲","definition":"to put a heavy demand on someone's patience or resources","definitionCN":"对某人的耐心或资源提出沉重要求","example":"The noise tasked her patience.","exampleCN":"噪声折磨着她的耐心。","why":"This older sense treats a person as a worker pushed to capacity. The task is not given but imposed on a faculty, and the result is strain.","whyCN":"这一较旧义把人当作被推到极限的工人。任务不是被交给某个能力，而是压在其上，结果是紧绷。"},{"no":"07","title":"A school exercise","titleCN":"课业任务；练习","definition":"a piece of work set for students to practise a skill","definitionCN":"为练习技能而布置给学生的作业","example":"The task asks students to compare two sources.","exampleCN":"这项课业任务要求学生比较两份材料。","why":"School turns work into practice: the task is not productive in itself, but it trains the skill that later work will need.","whyCN":"学校把工作变成练习：任务本身不产出什么，却训练日后工作所需的技能。"},{"no":"08","title":"'Take to task'","titleCN":"责备；训斥（习语）","definition":"to criticize or reprimand someone for a fault","definitionCN":"因过错而批评或训斥某人","example":"The coach took the players to task for arriving late.","exampleCN":"教练因迟到训斥了球员。","why":"The idiom pictures a task imposed as correction: the offender is given the work of answering for the fault. It is now fixed and slightly formal.","whyCN":"该习语把“任务”想象为惩罚性加派：犯错者被派去为过错作答。现为固定短语，略正式。"},{"no":"09","title":"A task force","titleCN":"特别工作组；特遣队","definition":"a group formed for a specific operation or problem","definitionCN":"为特定行动或问题而组建的团队","example":"The government set up a task force on housing.","exampleCN":"政府成立了住房问题特别工作组。","why":"Military and administrative language joins task to force: a body of people assembled around one job, then disbanded when it is done.","whyCN":"军事与行政语言把 task 与 force 结合：一群人围绕一项工作集结，事毕即散。"}],"etymology":{"intro":{"en":"Task came from Old North French tasque, 'duty, work', from Vulgar Latin *tasca, a charge or assessment, linked to Latin taxare 'to assess, tax'. The sense moved from a sum imposed to the work imposed, and then to any piece of work.","cn":"task 出自古北法语 tasque“义务、工作”，源于通俗拉丁语 *tasca“课征、摊派”，与拉丁 taxare“评估、征税”相连。义项从“被课的钱”移到“被派的活”，再泛化为任何一件工作。"},"items":[{"era":"C.1300","en":"The noun appears in English as 'labour imposed, duty', often in feudal or servile contexts.","cn":"名词约 1300 年出现于英语，意为“被施加的劳动、义务”，常见于封建或劳役语境。"},{"era":"OLD FRENCH","en":"Old North French tasque means 'duty, task, tax'; the same word family gives English tax.","cn":"古北法语 tasque 意为“义务、任务、税”；同一词族给出英语 tax。"},{"era":"VULGAR LATIN","en":"*tasca is a charge or assessment, reconstructed from Latin taxare 'to assess, value, tax'. The exact relation is debated.","cn":"*tasca 是课征或摊派，由拉丁 taxare“评估、估价、征税”重构；确切关系仍有争议。"},{"era":"LATIN","en":"taxare is a frequentative of tangere 'to touch', hence 'to touch repeatedly, handle, assess'.","cn":"taxare 是 tangere“触摸”的反复动词，故有“反复触碰、处理、评估”之义。"},{"era":"16C","en":"The sense widens from imposed labour to any piece of work, and the verb 'to task' appears.","cn":"十六世纪义项从被施加的劳动扩展到任何一件工作，动词 to task 出现。"},{"era":"19C","en":"'Take to task' fixes the reproach sense, while modern computing adds the scheduled unit of work.","cn":"十九世纪 take to task 固定了责备义；现代计算则加入“被调度的任务单位”。"}]},"similar":{"note":{"en":"The first group is the task family; the second is other names for work, each stressing a different feature.","cn":"第一组是 task 词族；第二组是“工作”的其他名称，各强调不同特征。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tasked","ipa":"/tɑːskt/","tag":"participle","definition":"given a particular job. It is the usual passive form of the verb.","definitionCN":"被分派特定工作的。动词常用被动形式。"},{"word":"tasking","ipa":"/ˈtɑːskɪŋ/","tag":"gerund/noun","definition":"the assigning of tasks, especially in military planning.","definitionCN":"任务分派，尤指军事计划。"},{"word":"multitask","ipa":"/ˌmʌltiˈtɑːsk/","tag":"verb","definition":"to do several tasks at the same time.","definitionCN":"同时做多项任务。"}]},{"heading":"NEAR MEANING","entries":[{"word":"job","ipa":"/dʒɒb/","tag":"work unit or post","definition":"a piece of work, often paid, or a regular position. It is broader and less obligatory than task.","definitionCN":"一件工作，常有报酬，或指固定职位。比 task 更广，义务性更弱。"},{"word":"assignment","ipa":"/əˈsaɪnmənt/","tag":"assigned work","definition":"work given to a person as part of a course or job. It stresses the handing over.","definitionCN":"作为课程或工作的一部分交给某人的任务。强调“交付”。"},{"word":"chore","ipa":"/tʃɔː/","tag":"routine duty","definition":"a small, routine household job. It is everyday and often dull.","definitionCN":"琐碎、例行的家务。日常且常乏味。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: tasque/tax, the unit-of-work image, the assignment sense, and the fixed idiom take to task.","cn":"真实联系：tasque 与 tax、工作单位意象、分派义，以及固定习语 take to task。"},"normal":[{"en":"Task and tax are cousins: both began as something imposed, a charge laid on a person.","cn":"task 与 tax 是表亲：二者最初都指加在人身上的课征。"},{"en":"A task is work as a countable unit: this job, with a start and an end.","cn":"任务是可数的工作单位：这一件活，有始有终。"},{"en":"Assignment adds a second person: the task is laid on you, not merely waiting there.","cn":"分派引入第二个人：任务是被加到你身上的，不只是放在那里。"},{"en":"Computing borrowed the managerial unit: jobs are split into tasks the machine schedules.","cn":"计算借用了管理单位：作业被拆成机器可调度的任务。"},{"en":"Take someone to task is to hand them the work of answering for a fault.","cn":"take someone to task 就是派他去做“为过错作答”这份活。"}],"abstract":[{"en":"A task is a slice of time given a name; naming the slice is already half of managing it.","cn":"任务是被命名的一段时间切片；能命名切片，管理就成了一半。"},{"en":"The word carries obligation silently: whoever assigns the task also defines what counts as done.","cn":"这个词默默携带义务：分派任务的人也定义了什么叫“做完”。"},{"en":"When work becomes a list of tasks, the meaning of the whole can disappear behind the ticked boxes.","cn":"当工作变成任务清单，整体的意义可能消失在打勾的方框后面。"}]},"examples":[{"en":"Her first task was to answer all the emails.","cn":"她的第一项任务是回复所有邮件。"},{"en":"The team was tasked with reducing costs by ten percent.","cn":"团队被分派将成本降低百分之十。"},{"en":"The judge took the lawyer to task for his conduct.","cn":"法官因律师的行为训斥了他。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“他时刻”——他每一时刻都被派了活 → task 任务","word":"task"},"root":"古北法语 tasque“义务、工作”，源于通俗拉丁语 *tasca“课征”，与拉丁 taxare“评估、征税”同族；taxare 出自 tangere“触摸”。","sensesIntro":{"en":"Nine senses of task: a countable unit of work, usually laid on someone. The unit may be a chore, a school exercise, a computer process, a military mission, or a reproach.","cn":"task 的九个义项：可数的工作单位，通常加在某人身上。这个单位可以是家务、课业、计算机进程、军事行动，或一次训斥。"},"semanticMap":{"core":{"en":"CORE IMAGE: a written job laid on a desk, waiting to be done.","cn":"核心意象：一张写好的活放在桌上，等着被做。"},"chain":["A CHARGE IMPOSED","A UNIT OF WORK","WORK LAID ON SOMEONE","WORK THAT WEIGHS","WORK GIVEN TO A MACHINE","WORK GIVEN AS CORRECTION"],"branches":[{"senses":"01 · 07","en":"THE UNIT: work counted as one item, whether chore or school exercise.","cn":"单位：被计为一项的工作，无论是家务还是课业。"},{"senses":"02 · 05 · 09","en":"THE ASSIGNMENT: a person or group is given work and made responsible for it; a task force is the group thus assigned.","cn":"分派：某人或某群体被交给工作并承担责任；特别工作组就是被这样交付任务的一群人。"},{"senses":"03 · 06","en":"THE WEIGHT: task names work that strains patience or capacity.","cn":"重量：task 命名压榨耐心或能力的工作。"},{"senses":"04","en":"THE MACHINE: computing schedules tasks as industrial units.","cn":"机器：计算把任务当作工业单位来调度。"},{"senses":"08","en":"THE REPROACH: the idiom turns a fault into work imposed as correction.","cn":"责备：习语把过错变成惩罚性加派的活。"}]},"affixes":{"intro":{"en":"Task is a French-derived noun. English makes it a verb and compounds it freely: multitask, task force, taskbar. Its older cousin tax keeps the 'assessment' branch.","cn":"task 是法语系名词。英语把它用作动词并自由复合：multitask、task force、taskbar。其较老的亲戚 tax 保留“评估”一支。"},"latinIntro":{"en":"There is no direct classical Latin noun task; it comes from Vulgar Latin *tasca 'charge', from taxare 'assess'. The taxare branch also gives tax, taxation, and taxable.","cn":"古典拉丁语并无直接对应名词；task 出自通俗拉丁语 *tasca“课征”，再出自 taxare“评估”。taxare 一支还给出 tax、taxation、taxable。"},"items":[{"word":"tasks","structure":"task + -s (plural/3sg)","meaning":"more than one task; he/she assigns","meaningCN":"任务（复数）；分派（三单）","example":"daily tasks","exampleCN":"日常任务"},{"word":"tasked","structure":"task + -ed (past participle)","meaning":"given a task","meaningCN":"被分派任务的（过去分词）","example":"tasked with reform","exampleCN":"受命改革"},{"word":"tasking","structure":"task + -ing (gerund/noun)","meaning":"the assigning of tasks","meaningCN":"任务分派（动名词/名词）","example":"mission tasking","exampleCN":"任务指派"},{"word":"multitask","structure":"multi- + task (verb)","meaning":"to do several tasks at once","meaningCN":"同时处理多项任务（复合动词）","example":"multitask on a phone","exampleCN":"在手机上多任务操作"},{"word":"multitasking","structure":"multi- + tasking (noun)","meaning":"the handling of several tasks at once","meaningCN":"多任务处理（名词）","example":"heavy multitasking","exampleCN":"高强度多任务"},{"word":"taskmaster","structure":"task + master (compound noun)","meaning":"one who drives others hard at work","meaningCN":"监工；严厉的工头（复合名词）","example":"a demanding taskmaster","exampleCN":"苛刻的监工"},{"word":"taskbar","structure":"task + bar (computing compound)","meaning":"the bar listing open programs","meaningCN":"任务栏（计算机复合词）","example":"icons on the taskbar","exampleCN":"任务栏图标"},{"word":"task force","structure":"task + force (compound noun)","meaning":"a group formed for one operation","meaningCN":"特别工作组；特遣队（复合名词）","example":"a housing task force","exampleCN":"住房工作组"},{"word":"tax","structure":"from Latin taxare (same family)","meaning":"a charge levied by government; to assess","meaningCN":"税；征税（同族）","example":"income tax","exampleCN":"所得税"}],"latinEntries":[{"word":"taxare","structure":"frequentative of tangere","meaning":"to assess, value, tax","meaningCN":"评估；估价；征税"},{"word":"tangere","structure":"Latin verb","meaning":"to touch","meaningCN":"触摸"},{"word":"*tasca","structure":"Vulgar Latin (reconstructed)","meaning":"a charge, assessment","meaningCN":"课征；摊派"},{"word":"tasque","structure":"Old North French","meaning":"duty, task, tax","meaningCN":"义务；任务；税"}]}},{"word":"technical","ipa_uk":"/ˈteknɪkl/","ipa_us":"/ˈteknɪkl/","definition_zh":"技术的；技术性的；专业的；严格按规则的；细节上的；（金融）技术分析的；（体育）技术犯规的","definition_en":"relating to a particular skill, art, or technology; requiring specialized knowledge; strictly according to rules","core_image":"一张图纸上密布尺寸线与公差标注，外行只看见线，内行看见限度","scene":"说明书里满是公差和扭矩参数。The manual was too technical for ordinary users, who gave up after three lines of numbers.","sceneCN":"这里 technical 是「技术性的、专业术语密集的」（第 2 个义项：需要专门知识才能理解）；句意：这本说明书对普通用户太技术性，读了三个数字就放弃了。图中可辨识物件：说明书、公差标注、扭矩扳手、零件剖面图、皱眉的读者。","pos":[{"tag":"adj.","zh":"技术的；技术性的；专业的；按规则的"},{"tag":"n.","zh":"（复数）技术细节；技术数据"}],"collocations":[{"phrase":"technical support","zh":"技术支持"},{"phrase":"technical terms","zh":"专业术语"},{"phrase":"technical problem","zh":"技术问题"},{"phrase":"technical foul","zh":"技术犯规"},{"phrase":"technical analysis","zh":"技术分析"},{"phrase":"technical school","zh":"技术学校"}],"forms":[{"label":"副词","form":"technically"},{"label":"名词","form":"technicality / technician"},{"label":"比较级（更多用 more 构成）","form":"more technical"},{"label":"最高级（更多用 most 构成）","form":"most technical"}],"derivatives":[{"word":"technically","pos":"adv.","zh":"技术上；严格说来"},{"word":"technicality","pos":"n.","zh":"技术细节；法律细则"},{"word":"technician","pos":"n.","zh":"技术员；技师"},{"word":"technique","pos":"n.","zh":"技巧；方法（同根近亲）"}],"senses":[{"no":"01","title":"Relating to technology","titleCN":"技术的；工业技术的","definition":"of or involving machines, engineering, or applied science","definitionCN":"涉及机器、工程或应用科学的","example":"technical innovation in manufacturing","exampleCN":"制造业的技术创新","why":"The Greek adjective tekhnikos meant 'of an art or craft'. Modern industry narrowed it toward machines, but the old sense of skilled making remains underneath.","whyCN":"希腊形容词 tekhnikos 意为“技艺的”。现代工业把它收窄到机器，但“有技艺的制作”这一旧义仍在底下。"},{"no":"02","title":"Requiring specialized knowledge","titleCN":"专业的；技术性的","definition":"needing expert knowledge to understand or use","definitionCN":"需要专门知识才能理解或使用","example":"The paper is too technical for a general reader.","exampleCN":"这篇论文对普通读者来说太专业了。","why":"This sense is about the audience, not the machine: a text is technical when it assumes a trained reader who shares its terms.","whyCN":"这一义关乎受众而非机器：文本 technical，是指它预设了一个共享术语的训练有素的读者。"},{"no":"03","title":"Of a particular art or skill","titleCN":"某一技艺的","definition":"in the original sense, belonging to a specific craft or discipline","definitionCN":"原义：属于某门具体技艺或学科","example":"the technical vocabulary of music","exampleCN":"音乐的专业词汇","why":"Before technology meant industry, tekhnē meant any craft, from medicine to sculpture. The adjective marked what belonged to a craft as such.","whyCN":"在 technology 指工业之前，tekhnē 指任何技艺，从医学到雕塑。该形容词标记“属于某门技艺本身”之物。"},{"no":"04","title":"Strictly according to rules","titleCN":"严格按规则的","definition":"applying the letter of a rule, often for its own sake","definitionCN":"按规则字面执行，常为规则而规则","example":"a technical violation of the treaty","exampleCN":"对该条约的技术性违反","why":"Sport and law use technical for breaches that are formal rather than substantive: the rule was broken, though the purpose may not have been.","whyCN":"体育与法律用 technical 指形式而非实质的违规：规则被破了，尽管目的未必被违背。"},{"no":"05","title":"A minor detail","titleCN":"细节上的；技术性的（次要）","definition":"concerning a small point of procedure rather than the main issue","definitionCN":"关乎程序小点而非主要问题","example":"We lost on a technical point.","exampleCN":"我们因一个技术性细节输了。","why":"Technical here means 'at the level of detail'. It can be neutral or dismissive, suggesting the point matters to the system more than to the cause.","whyCN":"此处 technical 意为“细节层面的”。它可中性也可轻蔑，暗示该点对制度比对事情本身更重要。"},{"no":"06","title":"Technical language","titleCN":"术语性的；专业用语的","definition":"using the special words of a field","definitionCN":"使用某领域的专门词汇","example":"'Friction' is a technical term in physics.","exampleCN":"friction 是物理学的专业术语。","why":"A technical term has a fixed definition inside a community. The same word may be ordinary outside, which is why technical language can exclude as well as clarify.","whyCN":"专业术语在社群内部有固定定义。同一词在外面可能很普通，故技术语言既能澄清也能排斥。"},{"no":"07","title":"Technical analysis (finance)","titleCN":"（金融）技术分析的","definition":"of price-and-volume analysis rather than company fundamentals","definitionCN":"基于价量而非公司基本面的分析","example":"technical indicators on the chart","exampleCN":"图表上的技术指标","why":"Finance splits analysis into fundamental and technical. The latter reads patterns in prices, treating the market's own record as the evidence.","whyCN":"金融把分析分为基本面与技术面。后者读取价格形态，把市场自身的记录当作证据。"},{"no":"08","title":"Technicals (noun)","titleCN":"技术细节；技术数据","definition":"the technical details or data of a situation, often in plural","definitionCN":"情形中的技术细节或数据，常用复数","example":"The technicals of the deal took weeks.","exampleCN":"交易的细节花了几周。","why":"The plural noun turns the adjective into a collective: all the small technical facts that must be settled before the main thing can proceed.","whyCN":"复数名词把形容词变成集合：在主要事情推进前必须安顿的所有技术性事实。"},{"no":"09","title":"Technical skill in performance","titleCN":"（表演/运动）技术层面的","definition":"of execution in sport, music, or dance rather than artistry","definitionCN":"指运动、音乐或舞蹈的执行层面而非艺术性","example":"Her technical skill is superb, but the performance lacks feeling.","exampleCN":"她的技术极好，但表演缺乏感情。","why":"Performance criticism separates technique from expression. 'Technical' praises the body's control while leaving meaning, taste, and emotion to another scale.","whyCN":"表演评论把技巧与表达分开。technical 赞身体的控制，把意义、品味与情感留给另一把尺。"}],"etymology":{"intro":{"en":"Technical comes from Greek tekhnikos, 'of an art or skill', from tekhnē 'craft, skill, method'. The suffix -ikos means 'pertaining to'. English first used it for the arts and sciences, and only later for industry and machines.","cn":"technical 出自希腊语 tekhnikos“技艺的”，源于 tekhnē“技艺、技能、方法”。后缀 -ikos 意为“属于…的”。英语最初用于文艺与科学，后来才用于工业与机器。"},"items":[{"era":"1610S","en":"The adjective enters English as 'belonging to a particular art or science', in the learned vocabulary of the seventeenth century.","cn":"该形容词在十七世纪进入英语，意为“属于某门技艺或科学的”，属学术词汇。"},{"era":"GREEK","en":"tekhnikos means 'of art, skillful, artificial', from tekhnē 'art, craft, skill, method'.","cn":"tekhnikos 意为“技艺的、熟练的、人造的”，出自 tekhnē“技艺、手艺、技能、方法”。"},{"era":"GREEK","en":"The suffix -ikos forms adjectives of relation: 'pertaining to'. It is not the -logia of technology, which names a discourse or study.","cn":"后缀 -ikos 构成关系形容词：“与…相关”。它不是 technology 的 -logia，后者命名论述或研究。"},{"era":"PIE","en":"tekhnē is traced to PIE *teks- 'to weave, fabricate', also behind tectonic and textile.","cn":"tekhnē 被追溯到原始印欧语 *teks-“编织、制作”，同一词根也见于 tectonic 与 textile。"},{"era":"19C","en":"Industrialisation shifts the centre of gravity: technical now suggests machinery, engineering, and applied science.","cn":"工业化转移重心：technical 现在多暗示机械、工程与应用科学。"},{"era":"MODERN","en":"Modern usage keeps both poles: technical can mean 'of machines' or 'of expert detail', and the context decides.","cn":"现代用法保留两极：technical 可指“机器的”或“专家细节的”，由语境决定。"}]},"similar":{"note":{"en":"The first group is the technē family, which looks alike but splits into skill, person, and detail; the second is related adjectives with different objects.","cn":"第一组是 technē 词族，形近而分为技艺、人物与细节；第二组是对象不同的相关形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"technique","ipa":"/tekˈniːk/","tag":"noun","definition":"a way of doing something requiring skill; the skill itself.","definitionCN":"需要技巧的做法；技巧本身。"},{"word":"technician","ipa":"/tekˈnɪʃn/","tag":"person noun","definition":"one trained in the practical details of a technical field.","definitionCN":"受过某技术领域实操训练的人。"},{"word":"technicality","ipa":"/ˌteknɪˈkæləti/","tag":"noun","definition":"a small point of technical detail or legal procedure.","definitionCN":"技术细节；法律程序细则。"}]},{"heading":"NEAR MEANING","entries":[{"word":"technological","ipa":"/ˌteknəˈlɒdʒɪkl/","tag":"of technology","definition":"relating to technology as a body of knowledge and its applications. It is wider and more systemic than technical.","definitionCN":"关乎技术知识体系及其应用。比 technical 更广、更系统。"},{"word":"specialized","ipa":"/ˈspiːʃəlaɪzd/","tag":"expert","definition":"designed for or requiring expert knowledge. It stresses the narrowness of the field.","definitionCN":"为专家知识设计或需要专家知识。强调领域之窄。"},{"word":"mechanical","ipa":"/məˈkænɪkl/","tag":"machine-related","definition":"relating to machines or to routine physical action. It is narrower and often suggests lack of thought.","definitionCN":"关乎机器或例行物理动作。更窄，常暗示缺乏思考。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: tekhnē 'craft', the -ikos suffix, the technical/technological split, and the 'detail' sense in law and sport.","cn":"真实联系：tekhnē“技艺”、-ikos 后缀、technical 与 technological 的分工，以及法律与体育中的“细节”义。"},"normal":[{"en":"Tekhnē means craft. Technical first meant 'of a craft', and only later 'of machines'.","cn":"tekhnē 意为技艺。technical 最早指“技艺的”，后来才指“机器的”。"},{"en":"The -ikos ending means 'pertaining to'. It makes an adjective of relation, not a science.","cn":"-ikos 词尾意为“与…相关”。它造关系形容词，而非一门学科。"},{"en":"Technical vs technological: technical is the detail or the skill; technological is the whole system of technology.","cn":"technical 与 technological：前者是细节或技艺，后者是技术这一整体体系。"},{"en":"A technical foul is formal: the rule broke, whether or not the purpose did.","cn":"技术犯规是形式性的：规则被破了，不论目的有没有被违背。"},{"en":"A technical point is a small joint in the machinery of procedure.","cn":"技术性细节是程序机器上的一个小接点。"}],"abstract":[{"en":"Technical knowledge is power only for those inside the vocabulary; outside it, the same words look like a wall.","cn":"技术知识只对词汇内部的人是权力；在外部，同样的话看起来像一堵墙。"},{"en":"The word keeps two loyalties: to the craft that makes things, and to the rule that judges them.","cn":"这个词保持两种忠诚：对制作之技艺，以及对评判之规则。"},{"en":"Calling a problem 'technical' can be an honest description or a way of moving it beyond public argument.","cn":"把问题称为“技术性的”，可以是诚实描述，也可以是把问题移出公共辩论的手法。"}]},"examples":[{"en":"The flight was delayed by a technical problem.","cn":"航班因技术问题延误。"},{"en":"The manual is too technical for most users.","cn":"这本手册对多数用户来说太专业了。"},{"en":"He received a technical foul for arguing with the referee.","cn":"他因与裁判争论被判技术犯规。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“特克尼扣”——特别克制、特别讲究地抠每一个技术细节 → technical 技术的","word":"technical"},"root":"希腊语 tekhnikos“技艺的”，出自 tekhnē“技艺、技能、方法”，后缀 -ikos“与…相关”；tekhnē 追溯到原始印欧语 *teks-“编织、制作”。","sensesIntro":{"en":"Nine senses of technical, built on two axes: craft (what is made with skill) and detail (what is known only to insiders). Law, sport, finance, and performance each tilt the word toward one axis.","cn":"technical 的九个义项建于两条轴：技艺（以技能制作之物）与细节（只有内行知道之物）。法律、体育、金融与表演各把词倾向一轴。"},"semanticMap":{"core":{"en":"CORE IMAGE: a drawing full of tolerances that only a trained eye can read.","cn":"核心意象：一张满是公差标注的图纸，只有受过训练的眼睛能读。"},"chain":["OF A CRAFT","OF A SPECIALIZED FIELD","OF MACHINES AND INDUSTRY","OF FORMAL RULES","OF SMALL DETAILS","OF TECHNICAL EXECUTION"],"branches":[{"senses":"S1 · S3","en":"CRAFT AND MACHINE: the old sense of skill and the modern sense of industry share one stem.","cn":"技艺与机器：古老的技能义与现代的工业义共享一词干。"},{"senses":"S2 · S6","en":"THE INSIDER'S LANGUAGE: terms and texts assume a trained reader.","cn":"内行语言：术语与文本预设训练有素的读者。"},{"senses":"S4 · S5","en":"RULES AND DETAILS: formal breaches and minor procedural points.","cn":"规则与细节：形式违规与程序小点。"},{"senses":"S7 · S8","en":"FINANCE: price patterns and the plural 'technicals' of a deal.","cn":"金融：价格形态与交易中的“技术细节”。"},{"senses":"S9","en":"PERFORMANCE: the body's control measured apart from expression.","cn":"表演：身体的控制，与表达分开衡量。"}]},"affixes":{"intro":{"en":"Technical is a Greek-derived adjective in -ikos (English -ical/-ic). Its family splits into technique (the skill), technician (the person), and technicality (the detail).","cn":"technical 是带希腊 -ikos（英语 -ical/-ic）的形容词。其词族分为 technique（技艺）、technician（人）、technicality（细节）。"},"latinIntro":{"en":"Greek tekhnē 'craft' plus -ikos gives tekhnikos, Latinised as technicus. English technical follows the -ical branch, while technology follows the -logia branch: skill studied versus skill described.","cn":"希腊 tekhnē“技艺”加 -ikos 成 tekhnikos，拉丁化为 technicus。英语 technical 走 -ical 一支，technology 走 -logia 一支：前者是被研究的技艺，后者是关于技艺的论述。"},"items":[{"word":"technically","structure":"technical + -ly (adverb)","meaning":"in technical terms; strictly speaking","meaningCN":"技术上；严格说来（-ly 副词）","example":"technically feasible","exampleCN":"技术上可行"},{"word":"technicality","structure":"technical + -ity (noun)","meaning":"a small technical or legal detail","meaningCN":"技术细节；法律细则（-ity 名词）","example":"acquitted on a technicality","exampleCN":"因程序细节获释"},{"word":"technician","structure":"tekhnē + -ician (person noun)","meaning":"one skilled in the practical side of a field","meaningCN":"技术员；技师（-ician 施事）","example":"a lab technician","exampleCN":"实验室技术员"},{"word":"technique","structure":"tekhnē + -ique (noun)","meaning":"a skilled way of doing something","meaningCN":"技巧；方法（-ique 名词）","example":"a new technique","exampleCN":"新方法"},{"word":"technology","structure":"tekhnē + -logia (noun)","meaning":"the systematic study or application of arts","meaningCN":"技术；工艺学（-logia 名词）","example":"information technology","exampleCN":"信息技术"},{"word":"technological","structure":"technology + -ical (adjective)","meaning":"relating to technology as a system","meaningCN":"技术体系的（-ical 形容词）","example":"technological change","exampleCN":"技术变革"},{"word":"technocracy","structure":"tekhnē + -cracy (noun)","meaning":"rule by technical experts","meaningCN":"技术官僚统治（-cracy 名词）","example":"a technocracy in practice","exampleCN":"实践中的技术官僚制"},{"word":"tectonic","structure":"PIE *teks- (same root)","meaning":"relating to building or earth structure","meaningCN":"构造的；建筑的（同根）","example":"tectonic plates","exampleCN":"构造板块"},{"word":"textile","structure":"PIE *teks- (same root)","meaning":"woven cloth","meaningCN":"纺织品（同根：编织）","example":"the textile industry","exampleCN":"纺织业"}],"latinEntries":[{"word":"tekhnē","structure":"Greek noun","meaning":"art, craft, skill, method","meaningCN":"技艺；手艺；技能；方法"},{"word":"tekhnikos","structure":"tekhnē + -ikos","meaning":"of art, skillful","meaningCN":"技艺的；熟练的"},{"word":"technicus","structure":"Latin from Greek","meaning":"technical, of an art","meaningCN":"技术的；技艺的"},{"word":"*-ikos","structure":"Greek adjectival suffix","meaning":"pertaining to","meaningCN":"与…相关的"}]}},{"word":"technique","ipa_uk":"/tekˈniːk/","ipa_us":"/tekˈniːk/","definition_zh":"技巧；技术；方法；手法；（艺术/音乐/体育的）技法；操作程序","definition_en":"a particular way of doing something that requires skill, especially in art, science, sport, or medicine","core_image":"画师手腕一转，笔尖在纸上拖出一道又薄又长的飞白","scene":"这位陶艺家不用拉坯机。Her technique is unusual: she builds the pot by coiling ropes of clay, one circle on top of another, with no wheel at all.","sceneCN":"这里 technique 是「技法、做法」（第 1 个义项：完成某事所需的特定方法）；句意：她的技法很特别：不用拉坯机，全靠把泥条一圈圈盘上去。图中可辨识物件：陶泥、手、盘筑的陶罐、转盘、工作室的木架。","pos":[{"tag":"n.","zh":"技巧；技术；方法；手法；操作程序"}],"collocations":[{"phrase":"a new technique","zh":"新方法"},{"phrase":"surgical technique","zh":"手术技巧"},{"phrase":"playing technique","zh":"演奏技法"},{"phrase":"teaching technique","zh":"教学法"},{"phrase":"master a technique","zh":"掌握技巧"},{"phrase":"a technique for doing sth","zh":"做某事的技巧"}],"forms":[{"label":"复数","form":"techniques"},{"label":"形容词","form":"technical"},{"label":"副词","form":"technically"},{"label":"施事名词","form":"technician"}],"derivatives":[{"word":"technical","pos":"adj.","zh":"技术的；专业性的"},{"word":"technician","pos":"n.","zh":"技术员；技师"},{"word":"technically","pos":"adv.","zh":"技术上；严格说来"},{"word":"technics","pos":"n.","zh":"技术学；工艺（罕用复数）"}],"senses":[{"no":"01","title":"A skilled way of doing something","titleCN":"技巧；做法","definition":"a particular method of doing something, especially one requiring practice","definitionCN":"完成某事的特定方法，尤需练习","example":"The potter's technique involves coiling, not throwing.","exampleCN":"这位陶艺家的技法是盘筑，而非拉坯。","why":"Technique is method plus skill. It names not the goal but the route, and implies that the route has been learned by the body as well as the mind.","whyCN":"technique 是方法加技能。它命名的不是目标而是路径，并暗示这条路径已被身体与心智共同学会。"},{"no":"02","title":"Skill in execution","titleCN":"技艺；手上功夫","definition":"the level of skill with which something is performed","definitionCN":"执行时所达到的技能水平","example":"Her piano technique is flawless.","exampleCN":"她的钢琴技巧无懈可击。","why":"Here the word means the quality of the doing rather than the recipe. A performer 'has technique' when the body can carry out what the mind intends.","whyCN":"此处词义是“做的质量”而非配方。表演者“有 technique”，就是身体能执行心智所意图的动作。"},{"no":"03","title":"An artistic method","titleCN":"艺术手法","definition":"a characteristic way of handling materials in art","definitionCN":"艺术中处理材料的独特方式","example":"The painter's brush technique gives the leaves a blurred edge.","exampleCN":"画家的笔法让叶子边缘带上模糊。","why":"Art criticism uses technique for the visible trace of a method: how paint is laid, how stone is cut, how a phrase is shaped.","whyCN":"艺术评论用 technique 指方法留下的可见痕迹：颜料如何铺、石如何刻、乐句如何塑形。"},{"no":"04","title":"A musical technique","titleCN":"演奏技法","definition":"a specific way of producing sound or handling an instrument","definitionCN":"发声或操作乐器的特定方式","example":"The piece requires a difficult bowing technique.","exampleCN":"这首曲子需要困难的运弓技法。","why":"Music turns technique into a repertoire of physical actions: bowing, fingering, breathing. Each has a name and a history of teaching.","whyCN":"音乐把 technique 变成一套身体动作曲目：运弓、指法、呼吸。每一项都有名称与教学史。"},{"no":"05","title":"A sports technique","titleCN":"运动技术","definition":"a standard or learned way of executing a movement","definitionCN":"执行动作的标准或习得方式","example":"His throwing technique improved after coaching.","exampleCN":"经教练指导后，他的投掷技术提高了。","why":"Sport measures technique against an efficient ideal: the same movement, done with less wasted force. Coaching is largely the transmission of technique.","whyCN":"体育以效率理想衡量技术：同一动作，少浪费力。教练工作很大部分就是技术的传递。"},{"no":"06","title":"A surgical technique","titleCN":"手术方式","definition":"a specific procedure used in an operation","definitionCN":"手术中使用的特定操作程序","example":"The surgeon used a minimally invasive technique.","exampleCN":"外科医生采用了微创技术。","why":"Medicine names techniques after their route and instruments. Here method becomes protocol, because variation can mean risk.","whyCN":"医学以路径与器械命名技术。此处方法变成规程，因为变化可能意味着风险。"},{"no":"07","title":"A scientific procedure","titleCN":"实验方法；工艺","definition":"a standardised procedure for producing or measuring something","definitionCN":"用于制作或测量的标准化程序","example":"The lab adopted a new staining technique.","exampleCN":"实验室采用了新的染色方法。","why":"Science converts technique into reproducibility: a method is written down so that others can repeat it and get the same result.","whyCN":"科学把技术转化为可复现性：方法被写下，使他人能重复并得到同样结果。"},{"no":"08","title":"A teaching technique","titleCN":"教学法","definition":"a method used to help students learn","definitionCN":"帮助学生学习的某种方法","example":"Group work is an effective teaching technique.","exampleCN":"小组活动是有效的教学法。","why":"Education borrows the word for classroom methods. Technique is judged by learning outcomes, not by elegance.","whyCN":"教育借这个词指课堂方法。技术以学习结果评判，而非优雅程度。"},{"no":"09","title":"A therapeutic technique","titleCN":"治疗技术","definition":"a procedure used in therapy or counselling","definitionCN":"治疗或咨询中使用的程序","example":"Cognitive restructuring is a common therapeutic technique.","exampleCN":"认知重构是常见的治疗技术。","why":"Therapy combines technique with relationship: the method is deliberate, but its effect depends on trust. The word keeps the clinical side visible.","whyCN":"治疗把技术与关系结合：方法是刻意的，效果却依赖信任。这个词让临床的一面保持可见。"}],"etymology":{"intro":{"en":"Technique entered English from French in the early nineteenth century. French technique is a noun use of the adjective technique 'technical', from Greek tekhnikos, from tekhnē 'art, craft'. The French ending -ique marks it as a learned borrowing, not a native Germanic word.","cn":"technique 于十九世纪初自法语进入英语。法语 technique 是形容词 technique“技术的”的名词化，源于希腊 tekhnikos，再出自 tekhnē“技艺”。法语词尾 -ique 标记它是学术借词，而非本土日耳曼词。"},"items":[{"era":"1817","en":"The word is first recorded in English in the context of art criticism, meaning a manner of execution.","cn":"该词最早记录于 1817 年的英语艺术评论语境，意为执行方式。"},{"era":"FRENCH","en":"French technique is a noun use of the adjective technique 'technical', with the ending -ique.","cn":"法语 technique 是形容词 technique“技术的”的名词化，带 -ique 词尾。"},{"era":"GREEK","en":"tekhnikos 'of an art, skillful' comes from tekhnē 'art, craft, skill, method'.","cn":"tekhnikos“技艺的、熟练的”出自 tekhnē“技艺、手艺、技能、方法”。"},{"era":"PIE","en":"tekhnē is traced to PIE *teks- 'to weave, fabricate', also behind textile and tectonic.","cn":"tekhnē 被追溯到原始印欧语 *teks-“编织、制作”，也见于 textile 与 tectonic。"},{"era":"19C","en":"The word spreads from painting and music to medicine, sport, and science, wherever a method is taught and repeated.","cn":"十九世纪该词从绘画与音乐扩展到医学、体育与科学，凡方法被教授与重复之处皆可用。"},{"era":"MODERN","en":"Modern English keeps technique for the how, and technology for the systematic knowledge and machinery.","cn":"现代英语以 technique 指“如何做”，以 technology 指系统化知识与机器。"}]},"similar":{"note":{"en":"The first group is the same technē family seen as adjective, person, and rare plural; the second is words for a way of doing, each with a different emphasis.","cn":"第一组是同一 technē 词族的形容词、人物与罕用复数；第二组是“做法”的近义词，侧重各异。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"technical","ipa":"/ˈteknɪkl/","tag":"adjective","definition":"relating to a craft, a technology, or its details.","definitionCN":"关乎技艺、技术或其细节的。"},{"word":"technician","ipa":"/tekˈnɪʃn/","tag":"person noun","definition":"one trained in the practical details of a technique.","definitionCN":"受训于某项技术实操细节的人。"},{"word":"technics","ipa":"/ˈteknɪks/","tag":"rare plural noun","definition":"the study or body of technical methods.","definitionCN":"技术学；技术方法总集（罕用）。"}]},{"heading":"NEAR MEANING","entries":[{"word":"method","ipa":"/ˈmeθəd/","tag":"systematic way","definition":"an organised way of doing something, often step by step. It stresses order rather than bodily skill.","definitionCN":"有组织的做法，常分步骤。强调秩序而非身体技能。"},{"word":"skill","ipa":"/skɪl/","tag":"ability","definition":"the ability to do something well, gained by practice. It is the capacity, not the procedure.","definitionCN":"通过练习获得的做好某事的能力。是能力，而非程序。"},{"word":"procedure","ipa":"/prəˈsiːdʒə/","tag":"prescribed steps","definition":"an established sequence of steps, especially in official or medical settings. It stresses rules and repeatability.","definitionCN":"既定步骤序列，尤用于官方或医疗场景。强调规则与可重复。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: French -ique, Greek tekhnē, the technique/technology split, and the move from art to medicine and sport.","cn":"真实联系：法语 -ique、希腊 tekhnē、technique 与 technology 的分工，以及从艺术到医学、体育的迁移。"},"normal":[{"en":"Technique is method plus skill: the route and the trained body that can walk it.","cn":"technique 是方法加技能：路径，以及能走这条路的训练过的身体。"},{"en":"The French -ique tells you it came through French, not straight from Greek.","cn":"法语 -ique 告诉你它经法语而来，不是直接从希腊语。"},{"en":"Technique is the how; technology is the system of knowledge and machines. A guitarist has technique; a studio has technology.","cn":"technique 是“如何做”；technology 是知识与机器的体系。吉他手有 technique；录音室有 technology。"},{"en":"In medicine a technique becomes a protocol, because variation can mean risk.","cn":"医学中技术会变成规程，因为变化可能意味着风险。"},{"en":"Sport judges technique by efficiency: the same movement with less wasted force.","cn":"体育以效率评判技术：同一动作，少浪费力。"}],"abstract":[{"en":"Technique is freedom made repeatable: it turns a lucky gesture into something you can do again.","cn":"技术是把自由变成可重复：它把偶然的一下变成你能再做一次的东西。"},{"en":"Every technique carries a way of seeing: what it makes easy, it also makes natural to want.","cn":"每种技术都携带一种看的方式：它使之容易的，也使之显得自然可欲。"},{"en":"Mastery is technique that has disappeared into the body, leaving only the result visible.","cn":"精通是消失进身体里的技术，只留下结果可见。"}]},"examples":[{"en":"She learned the technique of woodblock printing.","cn":"她学会了木版印刷的技法。"},{"en":"The surgeon's technique reduced recovery time.","cn":"这位外科医生的手术方式缩短了恢复时间。"},{"en":"Good interviewing is a technique, not a personality trait.","cn":"好的访谈是一种技巧，而非性格特质。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“特克尼克”——特别克制、特别讲究地拿捏每个动作 → technique 技巧、技法","word":"technique"},"root":"法语 technique（形容词“技术的”的名词化），出自希腊 tekhnikos“技艺的”，再出自 tekhnē“技艺、技能、方法”，追溯到原始印欧语 *teks-“编织、制作”。","sensesIntro":{"en":"Nine senses of technique, all a learned route to a result. The route may be artistic, musical, athletic, surgical, scientific, pedagogical, or therapeutic; in each field, technique is what can be taught and repeated.","cn":"technique 的九个义项都是通往结果的学习路径。路径可以是艺术的、音乐的、运动的、手术的、科学的、教学的或治疗的；在每个领域，technique 都是可被教授与重复之物。"},"semanticMap":{"core":{"en":"CORE IMAGE: a trained hand making a mark that a novice cannot make.","cn":"核心意象：训练有素的手留下新手留不出的痕迹。"},"chain":["A CRAFT","A LEARNED ROUTE","SKILL IN THE BODY","A VISIBLE STYLE","A REPEATABLE PROTOCOL","A FIELD-SPECIFIC METHOD"],"branches":[{"senses":"S1 · S2","en":"METHOD AND SKILL: the route and the trained capacity to walk it.","cn":"方法与技能：路径，以及走这条路的训练能力。"},{"senses":"S3 · S4","en":"ART AND MUSIC: technique becomes a visible or audible style.","cn":"艺术与音乐：技术变成可见或可听的风格。"},{"senses":"S5 · S6","en":"BODY AND MEDICINE: efficient movement and safe protocol.","cn":"身体与医学：高效动作与安全规程。"},{"senses":"S7 · S8","en":"SCIENCE AND SCHOOL: reproducibility and learning outcomes judge the method.","cn":"科学与学校：可复现性与学习结果评判方法。"},{"senses":"S9","en":"THERAPY: a deliberate procedure whose effect depends on trust.","cn":"治疗：刻意的程序，其效果依赖信任。"}]},"affixes":{"intro":{"en":"Technique is a French -ique noun from Greek tekhnē. Its English family splits into technical (the adjective), technician (the person), and technics (the rare collective). The same stem also gives technology through -logia.","cn":"technique 是带法语 -ique 的名词，源于希腊 tekhnē。其英语词族分为 technical（形容词）、technician（人）、technics（罕用集合名词）。同一词干经 -logia 还给出 technology。"},"latinIntro":{"en":"Greek tekhnē 'craft' gives tekhnikos 'of a craft'; French turned that adjective into the noun technique. Technology follows a different Greek suffix, -logia 'discourse, study'. Technique is the skill; technology is the discourse and system about skills.","cn":"希腊 tekhnē“技艺”生成 tekhnikos“技艺的”；法语把该形容词转为名词 technique。technology 走另一希腊后缀 -logia“论述、研究”。technique 是技能；technology 是关于技能的论述与体系。"},"items":[{"word":"techniques","structure":"technique + -s (plural)","meaning":"more than one method or skill","meaningCN":"多种技巧（复数）","example":"advanced techniques","exampleCN":"先进技术"},{"word":"technical","structure":"technique + -al (adjective)","meaning":"relating to technique or technology","meaningCN":"技术的；技法的（-al 形容词）","example":"technical skill","exampleCN":"技术能力"},{"word":"technically","structure":"technical + -ly (adverb)","meaning":"in technical terms; strictly","meaningCN":"技术上；严格说来（-ly 副词）","example":"technically correct","exampleCN":"技术上正确"},{"word":"technician","structure":"tekhnē + -ician (person noun)","meaning":"a trained practical worker","meaningCN":"技术员；技师（-ician 施事）","example":"a sound technician","exampleCN":"音响技术员"},{"word":"technics","structure":"tekhnē + -ics (rare noun)","meaning":"the study or system of technical methods","meaningCN":"技术学；工艺（罕用名词）","example":"the technics of printing","exampleCN":"印刷工艺"},{"word":"polytechnic","structure":"poly- + tekhnē (noun)","meaning":"an institution teaching many arts","meaningCN":"理工学院（poly-“多”+ 技艺）","example":"a polytechnic college","exampleCN":"理工学院"},{"word":"technocracy","structure":"tekhnē + -cracy (noun)","meaning":"rule by technical experts","meaningCN":"技术官僚统治（-cracy 名词）","example":"a technocracy","exampleCN":"技术官僚制"},{"word":"technocrat","structure":"tekhnē + -crat (person noun)","meaning":"a technical expert in power","meaningCN":"技术官僚（-crat 人物）","example":"a government of technocrats","exampleCN":"技术官僚政府"},{"word":"technophile","structure":"tekhnē + -phile (person noun)","meaning":"one who loves new technology","meaningCN":"技术爱好者（-phile 人物）","example":"a technophile's gadget","exampleCN":"技术迷的玩意儿"}],"latinEntries":[{"word":"tekhnē","structure":"Greek noun","meaning":"art, craft, skill, method","meaningCN":"技艺；手艺；技能；方法"},{"word":"tekhnikos","structure":"tekhnē + -ikos","meaning":"of art, skillful","meaningCN":"技艺的；熟练的"},{"word":"technicus","structure":"Latin from Greek","meaning":"technical","meaningCN":"技术的"},{"word":"technique","structure":"French noun from the adjective","meaning":"a manner of execution","meaningCN":"执行方式；技法"}]}},{"word":"technology","ipa_uk":"/tekˈnɒlədʒi/","ipa_us":"/tekˈnɑːlədʒi/","definition_zh":"技术；科技；工艺学；某种具体技术；（人类学）物质技术","definition_en":"the application of scientific knowledge for practical purposes; the body of tools, machines, and methods a society uses","core_image":"一条从矿石到芯片的流水线，每一站都站着一种被人类学会的手段","scene":"这家医院用远程会诊。Remote consultation technology means that patients in the county town no longer have to drive six hours to the provincial hospital.","sceneCN":"这里 technology 是「技术、科技」（第 1 个义项：把知识应用于实际目的的整体手段）；句意：远程会诊技术让县城的病人不必再坐六小时车去省城。图中可辨识物件：会诊屏幕、摄像头、病床、县城医院走廊、网络设备。","pos":[{"tag":"n.","zh":"技术；科技；工艺学；具体技术"}],"collocations":[{"phrase":"information technology","zh":"信息技术"},{"phrase":"new technology","zh":"新技术"},{"phrase":"technology transfer","zh":"技术转移"},{"phrase":"green technology","zh":"绿色技术"},{"phrase":"high technology","zh":"高科技"},{"phrase":"educational technology","zh":"教育技术"}],"forms":[{"label":"复数","form":"technologies"},{"label":"形容词","form":"technological"},{"label":"施事名词","form":"technologist"},{"label":"近亲名词","form":"technique"}],"derivatives":[{"word":"technological","pos":"adj.","zh":"技术的；科技的"},{"word":"technologist","pos":"n.","zh":"技术专家；技术员"},{"word":"technologically","pos":"adv.","zh":"技术上；科技上"},{"word":"technophobe","pos":"n.","zh":"惧怕新技术的人"}],"senses":[{"no":"01","title":"Applied science in practice","titleCN":"技术；科技（总称）","definition":"the application of scientific knowledge to practical ends","definitionCN":"把科学知识用于实际目的","example":"Modern technology has changed how we work.","exampleCN":"现代技术改变了我们的工作方式。","why":"Technology is knowledge that has been made operational. It is not science itself but science put to work, embodied in tools, systems, and routines.","whyCN":"technology 是被投入运作的知识。它不是科学本身，而是被投入使用、体现为工具、系统与常规的科学。"},{"no":"02","title":"A particular technology","titleCN":"某项具体技术","definition":"a specific tool, system, or method, such as solar power or writing","definitionCN":"某一具体工具、系统或方法，如太阳能或文字","example":"The clinic adopted telemedicine technology.","exampleCN":"诊所采用了远程医疗技术。","why":"The countable use lets us compare technologies: writing, printing, and the internet are each a technology with its own affordances.","whyCN":"可数用法让我们比较各种技术：文字、印刷与互联网各是一门有自身可能性的技术。"},{"no":"03","title":"The study of the arts (original)","titleCN":"工艺学；技术学（原义）","definition":"in the seventeenth-century sense, a systematic discourse about an art or craft","definitionCN":"十七世纪义：关于某门技艺的系统论述","example":"The old treatise was a technology of music.","exampleCN":"那篇旧论文是一部音乐工艺论。","why":"The Greek suffix -logia means 'discourse, study', so technology first meant talking about a craft, not the craft itself. The modern 'body of tools' sense is later.","whyCN":"希腊后缀 -logia 意为“论述、研究”，故 technology 最初指谈论技艺，而非技艺本身。现代“工具总体”义较晚。"},{"no":"04","title":"Information technology","titleCN":"信息技术","definition":"the technology of computing, data, and communication","definitionCN":"计算、数据与通信的技术","example":"She works in information technology.","exampleCN":"她从事信息技术工作。","why":"IT names a domain where technology is mostly invisible: code, protocols, and data centres. The word's plural 'technologies' fits its many layers.","whyCN":"IT 命名一个技术多半不可见的领域：代码、协议与数据中心。其复数 technologies 正合其多层结构。"},{"no":"05","title":"Educational technology","titleCN":"教育技术","definition":"tools and systems designed to support teaching and learning","definitionCN":"支持教与学的工具与系统","example":"The school invested in educational technology.","exampleCN":"学校投资了教育技术。","why":"Education adopts technology as a means, then asks whether it changes learning rather than merely delivering it faster.","whyCN":"教育把技术当手段，随后要问它是否改变了学习，而不只是更快地传递。"},{"no":"06","title":"Green technology","titleCN":"绿色技术","definition":"technology designed to reduce environmental harm","definitionCN":"为减少环境损害而设计的技术","example":"The city subsidises green technology.","exampleCN":"这座城市补贴绿色技术。","why":"Environmental politics adds a value judgement to the neutral word: not every technology is welcome, and 'green' marks the ones chosen.","whyCN":"环境政治给这个中性词加上价值判断：并非所有技术都受欢迎，“绿色”标记被选中的那些。"},{"no":"07","title":"High technology","titleCN":"高科技","definition":"advanced technology using sophisticated science or engineering","definitionCN":"使用精密科学或工程的先进技术","example":"The region attracts high-technology firms.","exampleCN":"该地区吸引高科技企业。","why":"High technology sorts tools by sophistication. The label is partly descriptive, partly promotional: it promises novelty and capability.","whyCN":"高科技按精密程度给工具排序。这个标签一半描述、一半宣传：它承诺新颖与能力。"},{"no":"08","title":"Technology transfer","titleCN":"技术转移","definition":"the movement of technology from one setting, often a lab, to another, often industry","definitionCN":"技术从一处（常为实验室）移到另一处（常为产业）","example":"The university set up an office for technology transfer.","exampleCN":"大学设立了技术转移办公室。","why":"Transfer treats technology as a movable object: knowledge, patents, and know-how can be handed from research to production.","whyCN":"转移把技术当作可移动之物：知识、专利与诀窍可从研究交到生产。"},{"no":"09","title":"Material technology (anthropology)","titleCN":"（人类学）物质技术","definition":"the tools and techniques by which a culture acts on its material world","definitionCN":"一个文化作用于其物质世界的工具与技艺","example":"Stone tools define an early material technology.","exampleCN":"石器定义了早期的物质技术。","why":"Anthropology uses the word broadly: a culture's technology is everything it does with materials, from fire to irrigation. Here it is close to 'material culture'.","whyCN":"人类学广义使用该词：一个文化的 technology 是它用材料所做的一切，从火到灌溉。此处近于“物质文化”。"}],"etymology":{"intro":{"en":"Technology is Greek in origin but English in its modern sense. Greek tekhnologia meant 'systematic treatment of an art', from tekhnē 'craft' plus -logia 'discourse, study'. English borrowed it in the seventeenth century for a treatise on an art; only in the nineteenth and twentieth centuries did it come to mean the tools and systems of applied science.","cn":"technology 源于希腊，现代义则是英语的。希腊 tekhnologia 意为“对某门技艺的系统论述”，由 tekhnē“技艺”加 -logia“论述、研究”构成。英语十七世纪借入，指论技艺的著作；直到十九、二十世纪，它才指应用科学的工具与系统。"},"items":[{"era":"1610S","en":"English takes the word from Greek tekhnologia, meaning a systematic discourse on an art.","cn":"英语自希腊 tekhnologia 借入，意为关于某门技艺的系统论述。"},{"era":"GREEK","en":"tekhnologia is tekhnē 'art, craft' plus -logia 'speaking, discourse, study'. It names talk about a craft, not the craft.","cn":"tekhnologia 是 tekhnē“技艺”加 -logia“言说、论述、研究”。它命名关于技艺的谈论，而非技艺本身。"},{"era":"GREEK","en":"The rival suffix -ikos 'pertaining to' gives tekhnikos and English technical. Technology studies the craft; technical belongs to it.","cn":"与之竞争的后缀 -ikos“与…相关”生成 tekhnikos 与英语 technical。technology 研究技艺；technical 属于技艺。"},{"era":"19C","en":"The Industrial Revolution shifts the sense to 'the science of the mechanical and industrial arts'.","cn":"工业革命把词义转向“机械与工业技艺的科学”。"},{"era":"20C","en":"The word settles into 'the application of scientific knowledge for practical purposes', and the plural technologies names competing systems.","cn":"二十世纪词义稳定为“把科学知识用于实际目的”，复数 technologies 指相互竞争的各种体系。"},{"era":"MODERN","en":"Modern usage spans IT, green tech, high tech, and technology transfer, all treating technology as a system rather than a single tool.","cn":"现代用法涵盖 IT、绿色技术、高科技与技术转移，皆把 technology 视为体系而非单一工具。"}]},"similar":{"note":{"en":"The first group is the technology family and its -logia branch; the second is neighbouring domains that are often confused with technology.","cn":"第一组是 technology 词族及其 -logia 分支；第二组是常与技术混淆的邻近领域。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"technological","ipa":"/ˌteknəˈlɒdʒɪkl/","tag":"adjective","definition":"relating to technology as a system or body of knowledge.","definitionCN":"关乎作为体系或知识整体的技术。"},{"word":"technologist","ipa":"/tekˈnɒlədʒɪst/","tag":"person noun","definition":"one who works with or studies technology.","definitionCN":"从事或研究技术的人。"},{"word":"technocracy","ipa":"/tekˈnɒkrəsi/","tag":"noun","definition":"rule by technical experts, from tekhnē plus -cracy.","definitionCN":"技术专家统治，由 tekhnē 加 -cracy 构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"engineering","ipa":"/ˌendʒɪˈnɪərɪŋ/","tag":"design discipline","definition":"the design and building of structures, machines, and systems. It is the discipline that produces much technology.","definitionCN":"结构、机器与系统的设计与建造。它是产出大量技术的学科。"},{"word":"innovation","ipa":"/ˌɪnəˈveɪʃn/","tag":"new thing or act","definition":"the introduction of a new idea, product, or method. It stresses novelty and adoption, not the whole system.","definitionCN":"新想法、产品或方法的引入。强调新颖与采纳，而非整个体系。"},{"word":"science","ipa":"/ˈsaɪəns/","tag":"knowledge discipline","definition":"organised knowledge about the world, pursued by method. Technology applies it; science seeks it.","definitionCN":"以方法获得的关于世界的系统知识。技术应用它；科学追求它。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: tekhnē plus -logia, the original 'discourse on an art' sense, the -logia/-ikos contrast, and the modern system sense.","cn":"真实联系：tekhnē 加 -logia、原义“论技艺”、-logia 与 -ikos 的对照，以及现代的体系义。"},"normal":[{"en":"Tekhnē means craft and -logia means discourse. Technology first meant talking about a craft, not the craft.","cn":"tekhnē 意为技艺，-logia 意为论述。technology 最初指谈论技艺，而非技艺本身。"},{"en":"Technology vs technical: -logia studies the craft; -ikos belongs to it.","cn":"technology 与 technical：-logia 研究技艺；-ikos 属于技艺。"},{"en":"Technology is science put to work: knowledge embodied in tools, systems, and routines.","cn":"technology 是被投入使用的科学：体现为工具、系统与常规的知识。"},{"en":"Countable technologies let us compare: writing, printing, and the internet each change what is easy.","cn":"可数的 technologies 让我们比较：文字、印刷与互联网各自改变“什么变容易”。"},{"en":"High tech, green tech, IT, tech transfer: the word now names systems, not single gadgets.","cn":"高科技、绿色技术、IT、技术转移：这个词现在命名体系，而非单一小装置。"}],"abstract":[{"en":"Technology is not neutral, because every tool makes some actions easy and others costly.","cn":"技术并非中立，因为每件工具都让某些行动变易、另一些变贵。"},{"en":"The word's history is a lesson: it began as talk about craft and ended as the craft that talks back.","cn":"这个词的历史是一课：它从谈论技艺开始，最终成为会回话的技艺。"},{"en":"Science asks what is true; technology asks what can be made to work, and then what that working changes.","cn":"科学问何为真；技术问何物能被做成，接着问“做成”改变了什么。"}]},"examples":[{"en":"Technology has reshaped the way people communicate.","cn":"技术重塑了人们的交流方式。"},{"en":"The company develops technology for clean water.","cn":"这家公司开发净水技术。"},{"en":"The course examines the technology of early printing.","cn":"这门课考察早期印刷技术。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“泰克诺乐记”——泰克诺（techno）把每门手艺都“乐记”成一本书 → technology 工艺学、技术","word":"technology"},"root":"希腊 tekhnologia“对技艺的系统论述”，由 tekhnē“技艺、技能”+ -logia“论述、研究”构成；经拉丁进入英语。","sensesIntro":{"en":"Nine senses of technology, from a discourse about craft to the systems that now shape daily life. The thread is systematic knowledge made operational, whether in one tool, one industry, or a whole culture.","cn":"technology 的九个义项，从“关于技艺的论述”到如今塑造日常生活的体系。线索是系统化知识被投入运作，无论在单件工具、一个产业，还是一个文化中。"},"semanticMap":{"core":{"en":"CORE IMAGE: a production line where each station embodies a learned human method.","cn":"核心意象：一条流水线，每一站都体现一种被人类学会的方法。"},"chain":["A CRAFT","DISCOURSE ABOUT THE CRAFT","SYSTEMATIC KNOWLEDGE OF ARTS","SCIENCE APPLIED TO WORK","A BODY OF TOOLS AND SYSTEMS","A CULTURE'S MATERIAL MEANS"],"branches":[{"senses":"S1 · S2","en":"APPLIED KNOWLEDGE: general technology and a countable, comparable technology.","cn":"应用知识：总称的技术，与可数、可比较的具体技术。"},{"senses":"S3","en":"THE ORIGINAL DISCOURSE: -logia names talk about craft, not the craft.","cn":"原初论述：-logia 命名关于技艺的谈论，而非技艺。"},{"senses":"S4 · S5","en":"DOMAINS: IT and education each build their own technological layer.","cn":"领域：IT 与教育各自建立自己的技术层。"},{"senses":"S6 · S7","en":"VALUES: green and high technology sort tools by harm and sophistication.","cn":"价值：绿色与高科技按损害与精密程度给工具分类。"},{"senses":"S8 · S9","en":"MOVEMENT AND CULTURE: tech transfer moves systems; anthropology sees a whole material world.","cn":"转移与文化：技术转移移动体系；人类学看见整个物质世界。"}]},"affixes":{"intro":{"en":"Technology is Greek tekhnē plus -logia, the suffix of discourse and study. English derives technological and technologist. Contrast technical, which uses -ikos, the suffix of belonging.","cn":"technology 是希腊 tekhnē 加 -logia（论述与研究后缀）。英语派生 technological 与 technologist。对照 technical，后者用 -ikos（归属后缀）。"},"latinIntro":{"en":"Greek tekhnologia 'systematic treatment of an art' joins tekhnē 'craft' and -logia 'discourse'. Latin transmitted the word, and English gave it the modern industrial sense. The same tekhnē stem yields technique, technical, and technician through other suffixes.","cn":"希腊 tekhnologia“对技艺的系统处理”结合 tekhnē“技艺”与 -logia“论述”。拉丁传递该词，英语赋予其现代工业义。同一 tekhnē 词干经其他后缀生成 technique、technical、technician。"},"items":[{"word":"technologies","structure":"technology + -ies (plural)","meaning":"multiple technologies or systems","meaningCN":"多种技术（复数）","example":"competing technologies","exampleCN":"相互竞争的技术"},{"word":"technological","structure":"technology + -ical (adjective)","meaning":"relating to technology","meaningCN":"技术的；科技的（-ical 形容词）","example":"technological progress","exampleCN":"技术进步"},{"word":"technologically","structure":"technological + -ly (adverb)","meaning":"by technological means; in technological terms","meaningCN":"技术上（-ly 副词）","example":"technologically advanced","exampleCN":"技术先进的"},{"word":"technologist","structure":"technology + -ist (person noun)","meaning":"one who studies or applies technology","meaningCN":"技术专家（-ist 人物）","example":"a medical technologist","exampleCN":"医疗技术专家"},{"word":"technique","structure":"tekhnē (same stem, noun)","meaning":"a skilled method","meaningCN":"技巧；技法（同词干名词）","example":"a surgical technique","exampleCN":"手术技法"},{"word":"technical","structure":"tekhnē + -ikos (adjective)","meaning":"relating to a craft or its details","meaningCN":"技术的；专业的（同词干 -ikos）","example":"technical details","exampleCN":"技术细节"},{"word":"technician","structure":"tekhnē + -ician (person noun)","meaning":"a practical skilled worker","meaningCN":"技术员（同词干人物）","example":"a lab technician","exampleCN":"实验室技术员"},{"word":"technocracy","structure":"tekhnē + -cracy (noun)","meaning":"government by technical experts","meaningCN":"技术官僚统治（-cracy 名词）","example":"a technocratic state","exampleCN":"技术官僚国家"},{"word":"biotechnology","structure":"bio- + technology (compound)","meaning":"technology applied to living systems","meaningCN":"生物技术（复合词）","example":"biotechnology research","exampleCN":"生物技术研究"}],"latinEntries":[{"word":"tekhnē","structure":"Greek noun","meaning":"art, craft, skill","meaningCN":"技艺；手艺；技能"},{"word":"tekhnologia","structure":"tekhnē + -logia","meaning":"systematic treatment of an art","meaningCN":"对技艺的系统论述"},{"word":"-logia","structure":"Greek suffix","meaning":"discourse, study","meaningCN":"论述；研究"},{"word":"technologia","structure":"Latin from Greek","meaning":"technology, discourse on arts","meaningCN":"工艺论；技艺论述"}]}},{"word":"temporary","ipa_uk":"/ˈtemprəri/","ipa_us":"/ˈtempəreri/","definition_zh":"临时的；暂时的；短期的；非永久的；临时工（名词，常用复数）","definition_en":"lasting only for a limited time; intended to be used or kept for a short period","core_image":"工地入口立着一块临时围挡，风一吹就晃，却已经立了三年","scene":"搬进新家前，他们先住进一间小公寓。They stayed in a temporary flat while the new house was being painted, and moved out as soon as the work was finished.","sceneCN":"这里 temporary 是「临时的、暂时的」（第 1 个义项：只持续有限时间）；句意：新房刷漆期间他们住在一间临时公寓，一完工就搬走了。图中可辨识物件：简易公寓、纸箱、未拆封的家具、装修中的新房、搬家货车。","pos":[{"tag":"adj.","zh":"临时的；暂时的；短期的"},{"tag":"n.","zh":"临时工；临时事物（常用复数）"}],"collocations":[{"phrase":"temporary accommodation","zh":"临时住处"},{"phrase":"temporary worker","zh":"临时工"},{"phrase":"temporary measure","zh":"权宜之计"},{"phrase":"temporary setback","zh":"暂时的挫折"},{"phrase":"temporary file","zh":"临时文件"},{"phrase":"on a temporary basis","zh":"以临时方式"}],"forms":[{"label":"副词","form":"temporarily"},{"label":"名词","form":"temporariness"},{"label":"复数（名词）","form":"temporaries"},{"label":"比较级（更多用 more 构成）","form":"more temporary"}],"derivatives":[{"word":"temporarily","pos":"adv.","zh":"暂时地；临时地"},{"word":"temporariness","pos":"n.","zh":"临时性；暂时性"},{"word":"temporal","pos":"adj.","zh":"时间的；世俗的（同根）"},{"word":"contemporary","pos":"adj./n.","zh":"同时代的；同代人（同根）"}],"senses":[{"no":"01","title":"Lasting a short time","titleCN":"只持续有限时间的","definition":"lasting only for a limited period, not forever","definitionCN":"只持续有限时段，不会永远","example":"They found temporary shelter under a bridge.","exampleCN":"他们在桥下找到临时遮蔽。","why":"Temporary is defined by an end. It does not say how short the period is, only that a limit exists and is expected to arrive.","whyCN":"temporary 由“终点”定义。它不说时段多短，只说存在一个被预期会到来的界限。"},{"no":"02","title":"Not permanent","titleCN":"非永久的","definition":"not intended to last or to be final","definitionCN":"不打算长久保留或成为最终状态","example":"The agreement is temporary and will be reviewed.","exampleCN":"该协议是暂时的，将会复审。","why":"The word often carries a promise or a warning: this state is provisional, so do not build your life on it, or do not despair of it.","whyCN":"这个词常带承诺或警告：此状态是暂定的，故不要把生活建在其上，也别为它绝望。"},{"no":"03","title":"Of a short-term job","titleCN":"临时工作的","definition":"of work or a post that ends after a fixed period","definitionCN":"有固定期限、到期即止的工作或职位","example":"She took a temporary job for the summer.","exampleCN":"她做了份暑期临时工作。","why":"Labour markets use temporary as a category: the contract has an end date, and with it fewer rights and less security.","whyCN":"劳动力市场把 temporary 当作类别：合同有终止日，随之而来的是更少的权利与保障。"},{"no":"04","title":"Of short-term lodging","titleCN":"临时住处的","definition":"of accommodation used until something permanent is available","definitionCN":"在永久住处可用之前使用的住所","example":"The family stayed in temporary housing after the fire.","exampleCN":"火灾后这家人住进临时住房。","why":"Housing makes the word concrete: a roof that is known to be borrowed, often provided by an agency or a friend, and marked by boxes not yet unpacked.","whyCN":"住房把词变具体：一个明知是借来的屋顶，常由机构或朋友提供，以尚未拆封的纸箱为标志。"},{"no":"05","title":"A temporary worker (noun)","titleCN":"临时工（名词）","definition":"a person employed for a limited period, often through an agency","definitionCN":"受雇有限期限的人，常经中介","example":"The hospital hired temporaries for the winter.","exampleCN":"医院为冬季雇了临时工。","why":"The noun turns the adjective into a person. 'Temps' is the clipped, everyday form; the plural temporaries is more formal.","whyCN":"名词把形容词变成人。口语缩略为 temp；复数 temporaries 更正式。"},{"no":"06","title":"A stopgap measure","titleCN":"权宜之计","definition":"an arrangement used to solve a problem until a better one is possible","definitionCN":"在更好办法出现前用来解决问题的安排","example":"The ban is a temporary measure, not a policy.","exampleCN":"该禁令是权宜之计，而非政策。","why":"A temporary measure admits its own inadequacy. It buys time, and the honest ones say so rather than pretending to be final.","whyCN":"权宜之计承认自身不足。它买时间，诚实者会明说，而不假装是最终方案。"},{"no":"07","title":"A temporary file","titleCN":"临时文件","definition":"a computer file created for a short task and deleted later","definitionCN":"为短期任务创建、随后删除的计算机文件","example":"The installer left temporary files on the disk.","exampleCN":"安装程序在磁盘上留下了临时文件。","why":"Computing literalises the word: the file exists only while a process runs, and its deletion is part of its design.","whyCN":"计算把词字面化：文件只在进程运行时存在，其删除是设计的一部分。"},{"no":"08","title":"A short stay","titleCN":"短期停留","definition":"a visit or residence lasting only a while","definitionCN":"只持续一段时日的访问或居住","example":"He made a temporary stay in the city.","exampleCN":"他在城里作短期停留。","why":"Travel and diplomacy use the word for presence that is explicitly not settlement. The visitor is in place but not of it.","whyCN":"旅行与外交用该词指明确不落户的存在。访客在此地，却不属于此地。"},{"no":"09","title":"A passing setback","titleCN":"暂时的挫折","definition":"a difficulty expected to improve with time","definitionCN":"预期随时间好转的困难","example":"The loss was a temporary setback, not a collapse.","exampleCN":"这次亏损是暂时挫折，不是崩溃。","why":"Applied to feelings and fortunes, temporary is consolation: it reframes a present pain as a phase with an exit.","whyCN":"用于情绪与境遇时，temporary 是安慰：它把当下的痛重新框定为有出口的阶段。"}],"etymology":{"intro":{"en":"Temporary comes from Latin temporarius, 'of a time, lasting for a time', from tempus 'time' (genitive temporis). English took it in the sixteenth century. The deeper origin of tempus is uncertain; it is often connected with a root meaning 'to stretch or span'.","cn":"temporary 出自拉丁语 temporarius“某段时间的、暂时的”，源于 tempus“时间”（属格 temporis）。英语十六世纪借入。tempus 的更早来源不确定，常与表示“伸展、跨度”的词根相连。"},"items":[{"era":"1540S","en":"The adjective is first recorded in English in the sense 'lasting only for a time'.","cn":"该形容词最早记录于十六世纪四十年代，意为“只持续一段时间的”。"},{"era":"LATIN","en":"temporarius means 'of time, belonging to a time, transient', from tempus 'time, season'.","cn":"temporarius 意为“时间的、属于某时段的、短暂的”，出自 tempus“时间、季节”。"},{"era":"LATIN","en":"tempus has the genitive temporis, which is why temporary has an r where the base word seems to lack one.","cn":"tempus 的属格是 temporis，故 temporary 在词基看似没有 r 的地方出现了一个 r。"},{"era":"UNCERTAIN","en":"The Indo-European origin of tempus is disputed. A connection with a root meaning 'to stretch, span' is often proposed but not certain.","cn":"tempus 的印欧来源有争议。常有人提出与表示“伸展、跨度”的词根相关，但并不确定。"},{"era":"16C","en":"Legal and religious writing spread the word: temporal goods are of this world, temporary arrangements last only a while.","cn":"十六世纪法律与宗教写作推广该词：temporal 之物属于此世，temporary 安排只维持一时。"},{"era":"MODERN","en":"Modern usage ranges from temp work and temporary housing to temporary files, all sharing an expected end point.","cn":"现代用法从临时工作、临时住房到临时文件，皆共享一个预期终点。"}]},"similar":{"note":{"en":"The first group is the tempus family, where r-forms and plain forms alternate; the second is words for shortness of duration, each with a different tone.","cn":"第一组是 tempus 词族，r 形式与无 r 形式交替；第二组是表示时短的其他词，语气各异。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"temporarily","ipa":"/ˌtemprəˈrerəli/","tag":"adverb","definition":"for a limited time only.","definitionCN":"只限一段时间地。"},{"word":"temporariness","ipa":"/ˈtemprərinəs/","tag":"noun","definition":"the quality of lasting only a while.","definitionCN":"只持续一时的性质。"},{"word":"temporal","ipa":"/ˈtempərəl/","tag":"adjective","definition":"relating to time, or to worldly rather than spiritual matters.","definitionCN":"关于时间的；世俗的（非属灵的）。"}]},{"heading":"NEAR MEANING","entries":[{"word":"transient","ipa":"/ˈtrænziənt/","tag":"passing","definition":"lasting only a very short time and passing quickly. It is more literary and more absolute than temporary.","definitionCN":"只持续极短时间并迅速消逝。比 temporary 更文学、更绝对。"},{"word":"interim","ipa":"/ˈɪntərɪm/","tag":"meanwhile","definition":"used or done between two points in time, especially between two official arrangements.","definitionCN":"在两个时点之间、尤在两个正式安排之间使用或做的。"},{"word":"provisional","ipa":"/prəˈvɪʒənl/","tag":"conditional","definition":"arranged for the present but likely to be changed. It stresses conditionality rather than duration.","definitionCN":"为当下安排但很可能被改。强调条件性而非时长。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: tempus/temporis, the r in the English word, the temp-work sense, and the contrast with permanent.","cn":"真实联系：tempus 与 temporis、英语词中的 r、临时工作义，以及同 permanent 的对照。"},"normal":[{"en":"Tempus means time, and its genitive is temporis. That hidden r is why English has temporary.","cn":"tempus 意为时间，属格是 temporis。那个藏起来的 r 正是英语 temporary 的来源。"},{"en":"Temporary is defined by an end: it does not say how short, only that a stop is expected.","cn":"temporary 由终点定义：它不说多短，只说预期会停。"},{"en":"A temp job has an end date written into the contract; the word is a legal fact, not just a feeling.","cn":"临时工作的合同里写着终止日；这个词是法律事实，不只是感觉。"},{"en":"A temporary file exists only while a process runs; deleting it is part of its design.","cn":"临时文件只在进程运行时存在；删除它是设计的一部分。"},{"en":"Temporary vs permanent: one expects an exit, the other expects to remain.","cn":"temporary 与 permanent：前者预期出口，后者预期留下。"}],"abstract":[{"en":"The temporary is not less real; it is real with a clock attached.","cn":"临时之物并非不那么真实；它是被系上时钟的真实。"},{"en":"Calling something temporary is a political act: it can make an injustice easier to bear or harder to oppose.","cn":"把某物称为临时，是一种政治行为：它能让不义更易忍受，也能让它更难被反对。"},{"en":"All arrangements are temporary at some scale; the word only makes the scale visible.","cn":"一切安排在某个尺度上都是临时的；这个词只是让尺度显现。"}]},"examples":[{"en":"The museum is closed for temporary repairs.","cn":"博物馆因临时维修闭馆。"},{"en":"He took a temporary position at the bank.","cn":"他在银行做了一份临时职位。"},{"en":"The decline in sales proved temporary.","cn":"销售下滑被证明是暂时的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“摊破若瑞”——摊子破了也别急，若天降祥瑞，很快就能换新的 → temporary 临时的","word":"temporary"},"root":"拉丁语 temporarius“某段时间的、短暂的”，出自 tempus“时间、季节”（属格 temporis）；tempus 的印欧来源存疑。","sensesIntro":{"en":"Nine senses of temporary, all marked by an expected end. The end may be a date on a contract, the completion of a house, the closing of a file, or the passing of a mood.","cn":"temporary 的九个义项都以“预期终点”为标记。终点可以是合同日期、房子装完、文件关闭，或情绪过去。"},"semanticMap":{"core":{"en":"CORE IMAGE: a temporary fence that is expected to come down.","cn":"核心意象：一道预期会被拆掉的临时围挡。"},"chain":["OF A TIME","LASTING A WHILE","NOT FINAL","ENDING ON A DATE","SERVING UNTIL BETTER","PASSING WITH TIME"],"branches":[{"senses":"S1 · S2","en":"DURATION: the word measures a limited span and denies permanence.","cn":"时长：衡量有限跨度，并否认永久。"},{"senses":"S3 · S4 · S5","en":"LIFE ARRANGEMENTS: jobs, housing, and the people who fill them are all marked by an end date.","cn":"生活安排：工作、住房与填充其中的人，都带终止日。"},{"senses":"S6 · S9","en":"THE STOPGAP: measures and setbacks are framed as phases with an exit.","cn":"权宜：措施与挫折被框定为有出口的阶段。"},{"senses":"S7","en":"COMPUTING: the file exists only while needed, and deletion is designed in.","cn":"计算：文件只在需要时存在，删除是设计的一部分。"},{"senses":"S8","en":"PRESENCE: a short stay is presence without settlement.","cn":"在场：短期停留是“在场而不落户”。"}]},"affixes":{"intro":{"en":"Temporary is a Latin adjective in -arius built on the tempus/tempor- stem. English derives -ly and -ness, while the same stem gives temporal, contemporary, tempo, and tempest.","cn":"temporary 是建于 tempus/tempor- 词干的拉丁 -arius 形容词。英语派生 -ly 与 -ness，同一词干给出 temporal、contemporary、tempo、tempest。"},"latinIntro":{"en":"Latin tempus 'time' has the stem tempor-, which supplies temporarius 'lasting a time'. The family includes temporal (of time), contemporary (of the same time), and tempo (time in music). The ultimate origin of tempus is uncertain.","cn":"拉丁 tempus“时间”的词干为 tempor-，生成 temporarius“持续一段时间的”。词族含 temporal（时间的）、contemporary（同时代的）、tempo（音乐的时间）。tempus 的最终来源不确定。"},"items":[{"word":"temporarily","structure":"temporary + -ly (adverb)","meaning":"for a limited time","meaningCN":"暂时地；临时地（-ly 副词）","example":"temporarily closed","exampleCN":"暂时关闭"},{"word":"temporariness","structure":"temporary + -ness (noun)","meaning":"the quality of being temporary","meaningCN":"临时性；暂时性（-ness 名词）","example":"the temporariness of the arrangement","exampleCN":"安排的临时性"},{"word":"temporaries","structure":"temporary + -ies (plural noun)","meaning":"temporary workers or things","meaningCN":"临时工；临时事物（复数）","example":"hiring temporaries","exampleCN":"雇用临时工"},{"word":"temporal","structure":"tempus + -al (adjective)","meaning":"relating to time; worldly","meaningCN":"时间的；世俗的（-al 形容词）","example":"the temporal world","exampleCN":"世俗世界"},{"word":"contemporary","structure":"con- + temporarius (same stem)","meaning":"existing at the same time","meaningCN":"同时代的（同词干：con-“共同”）","example":"contemporary art","exampleCN":"当代艺术"},{"word":"contemporaneous","structure":"con- + temporaneus (same stem)","meaning":"happening at the same time","meaningCN":"同时发生的（同词干）","example":"contemporaneous records","exampleCN":"同时期记录"},{"word":"tempo","structure":"tempus (Italian, same stem)","meaning":"the speed of music","meaningCN":"节拍；速度（同词干，经意大利语）","example":"a slow tempo","exampleCN":"慢速"},{"word":"tempest","structure":"tempestas 'storm, season' (same stem)","meaning":"a violent storm","meaningCN":"暴风雨（同词干）","example":"a raging tempest","exampleCN":"狂暴的风暴"},{"word":"temporize","structure":"tempus + -ize (verb)","meaning":"to act for the moment; to delay","meaningCN":"顺应时势；拖延（同词干动词）","example":"temporize with critics","exampleCN":"与批评者周旋"}],"latinEntries":[{"word":"tempus","structure":"Latin noun, genitive temporis","meaning":"time, season","meaningCN":"时间；季节"},{"word":"temporarius","structure":"from tempus","meaning":"lasting for a time, temporary","meaningCN":"持续一时的；暂时的"},{"word":"temporal","structure":"from tempus","meaning":"of time","meaningCN":"时间的"},{"word":"tempestas","structure":"from tempus","meaning":"season, storm","meaningCN":"季节；风暴"}]}},{"word":"tend","ipa_uk":"/tend/","ipa_us":"/tend/","definition_zh":"倾向；有…趋势；趋向；照料；照看；管理；在酒吧当班；放牧；（古）侍候","definition_en":"to be likely to do something or to move in a certain direction; to take care of someone or something","core_image":"水往低处流，而牧人低头跟着羊群往坡下走","scene":"每到冬天，他的咳嗽就更厉害。Every winter his cough tends to get worse, and the doctor says the cold air is the cause.","sceneCN":"这里 tend 是「倾向于、有…趋势」（第 1 个义项：经常如此或很可能如此）；句意：每年冬天他的咳嗽都倾向于加重，医生说是冷空气刺激。图中可辨识物件：病历、冬季窗景、雾化器、围巾、医生的听诊器。","pos":[{"tag":"v.","zh":"倾向；趋向；照料；照看；管理；当班"}],"collocations":[{"phrase":"tend to do sth","zh":"倾向于做某事"},{"phrase":"tend toward","zh":"趋向于"},{"phrase":"tend a fire","zh":"照看炉火"},{"phrase":"tend bar","zh":"在酒吧当班"},{"phrase":"tend sheep","zh":"放羊"},{"phrase":"tend to sb's needs","zh":"照料某人的需要"}],"forms":[{"label":"第三人称单数","form":"tends"},{"label":"现在分词","form":"tending"},{"label":"过去式/过去分词","form":"tended"},{"label":"名词","form":"tendency"}],"derivatives":[{"word":"tendency","pos":"n.","zh":"倾向；趋势"},{"word":"tending","pos":"n.","zh":"照料；护理"},{"word":"tendentious","pos":"adj.","zh":"有倾向性的；带偏见的"},{"word":"tender","pos":"n./adj.","zh":"照料者；温柔的（同根近亲，义已分化）"}],"senses":[{"no":"01","title":"Be likely to do something","titleCN":"倾向于做某事","definition":"to be likely to do or be something, as a regular pattern","definitionCN":"经常如此或很可能如此","example":"People tend to ignore warnings they hear too often.","exampleCN":"人们倾向于忽略听太多的警告。","why":"Tendere means 'to stretch'. The modern sense pictures behaviour stretched toward one outcome: the pattern leans, and prediction follows the lean.","whyCN":"tendere 意为“伸展”。现代义把行为想象为朝某个结果伸展：模式倾斜，预测随倾斜而来。"},{"no":"02","title":"Take care of someone","titleCN":"照料；护理","definition":"to look after a person, especially one who is ill or young","definitionCN":"照看某人，尤指病者或幼者","example":"Nurses tended the wounded through the night.","exampleCN":"护士整夜照料伤员。","why":"This sense has a different parent: it is a shortened form of attend, 'to direct one's mind to'. Care is attention made practical.","whyCN":"此义另有来源：它是 attend“把心思朝向”的缩略。照料是“注意”被付诸实践。"},{"no":"03","title":"Move in a direction","titleCN":"趋向；朝向","definition":"to move or point toward a place or state","definitionCN":"朝某处或某状态移动、指向","example":"The path tends toward the river.","exampleCN":"小径趋向河边。","why":"The spatial sense is the most literal: a line or a road stretches in a direction. Inclination in behaviour is this stretching made mental.","whyCN":"空间义最字面：一条线或路朝某方向伸展。行为上的倾向，就是这种伸展被心智化。"},{"no":"04","title":"Have an inclination of opinion","titleCN":"倾向（于某种看法）","definition":"to be inclined to hold a view or favour an option","definitionCN":"倾向于持有某观点或支持某选项","example":"The committee tends toward a compromise.","exampleCN":"委员会倾向于妥协。","why":"Opinions also lean. The verb lets a speaker report a drift without claiming a fixed position: the group is not there yet, but it is tending there.","whyCN":"观点也会倾斜。动词让说话者报告一种漂移而不宣称固定立场：群体尚未到达，但正朝那里去。"},{"no":"05","title":"Look after a fire or machine","titleCN":"照看（炉火/机器）","definition":"to keep a fire, machine, or process working properly","definitionCN":"使炉火、机器或过程正常运转","example":"He tended the furnace all night.","exampleCN":"他整夜照看炉子。","why":"Tending a fire is maintenance as attention: add fuel, watch the draft, respond to changes. The cared-for object is not alive, but it needs vigilance.","whyCN":"照看炉火是“注意”式的维护：添燃料、看通风、应对变化。被照看之物并非活物，却需要警觉。"},{"no":"06","title":"Serve in a bar","titleCN":"在酒吧当班","definition":"to work behind a bar, serving drinks","definitionCN":"在吧台后工作、供应饮品","example":"She tends bar on weekends.","exampleCN":"她周末在酒吧当班。","why":"American English uses tend for a workplace one keeps running. The bartender tends the bar as a shepherd tends a flock: presence plus upkeep.","whyCN":"美式英语用 tend 指维持一个工作场所运转。酒吧侍者 tend 吧台，如牧人 tend 羊群：在场加维护。"},{"no":"07","title":"Herd animals","titleCN":"放牧；看管","definition":"to watch over animals as they graze","definitionCN":"看管吃草的牲畜","example":"A boy tended the goats on the hillside.","exampleCN":"一个男孩在山坡上放羊。","why":"Herding is the oldest care sense: the animals move, and the herder's attention moves with them, keeping them from straying.","whyCN":"放牧是最古老的照料义：牲畜移动，牧人的注意力随之前移，防止它们走失。"},{"no":"08","title":"Attend or wait upon (archaic)","titleCN":"侍候；随侍（古义）","definition":"in older usage, to attend on a person of rank","definitionCN":"旧用法：随侍地位高者","example":"The squire tended his lord.","exampleCN":"侍从随侍他的领主。","why":"This is the attend branch in its full feudal form: standing ready, mind directed toward the master's needs. Modern care kept the service and dropped the rank.","whyCN":"这是 attend 一支的完整封建形态：立于一旁待命，心思朝向主人的需要。现代“照料”保留服侍，丢掉等级。"},{"no":"09","title":"Converge on a result","titleCN":"趋于（某结果）","definition":"of numbers or processes, to approach a limit or outcome","definitionCN":"数字或过程逼近某一极限或结果","example":"Under these rules, costs tend toward zero.","exampleCN":"在这些规则下，成本趋于零。","why":"Mathematics uses the spatial lean for convergence: a sequence stretches toward a limit it may never reach exactly.","whyCN":"数学用空间倾斜表示收敛：序列朝一个可能永远不能精确到达的极限伸展。"}],"etymology":{"intro":{"en":"English has two tend verbs that now look alike. The 'incline' tend comes from Old French tendre, Latin tendere 'to stretch'. The 'care for' tend is a shortened form of attend, from Old French atendre, Latin attendere 'to give heed'. They merged in spelling but not in origin.","cn":"英语有两个现已形似的 tend 动词。“倾向”的 tend 出自古法语 tendre、拉丁 tendere“伸展”；“照料”的 tend 是 attend 的缩略，出自古法语 atendre、拉丁 attendere“留心”。它们在拼写上合并，来源却不同。"},"items":[{"era":"13C","en":"The 'stretch, incline' verb enters English from Old French tendre, used of movement and direction.","cn":"“伸展、倾向”动词十三世纪自法语 tendre 进入英语，用于移动与方向。"},{"era":"LATIN","en":"tendere means 'to stretch, extend, direct'. Its past participle tensus gives tense and tension.","cn":"tendere 意为“伸展、延伸、指向”。其过去分词 tensus 生成 tense 与 tension。"},{"era":"PIE","en":"tendere is traced to PIE *ten- 'to stretch', the same root behind tendon and the ten- of intend and extend.","cn":"tendere 被追溯到原始印欧语 *ten-“伸展”，同一词根见于 tendon，以及 intend、extend 中的 ten-。"},{"era":"C.1200","en":"The 'care for' sense comes from attend, 'to direct the mind to', later shortened to tend in everyday use.","cn":"“照料”义出自 attend“把心思朝向”，后在日常使用中缩略为 tend。"},{"era":"LATIN","en":"attendere is ad- 'to' plus tendere 'stretch': to stretch one's mind toward something. So care and inclination are distant cousins after all.","cn":"attendere 是 ad-“朝向”加 tendere“伸展”：把心思朝某物伸去。故“照料”与“倾向”终究是远亲。"},{"era":"MODERN","en":"Modern English keeps both: tend to do (incline) and tend a fire (care for). Context, not spelling, tells them apart.","cn":"现代英语两者皆存：tend to do（倾向）与 tend a fire（照看）。区分靠语境，不靠拼写。"}]},"similar":{"note":{"en":"The first group is the tend family and its look-alikes; the second is verbs that share either the leaning or the caring sense.","cn":"第一组是 tend 词族与形近词；第二组是共享“倾斜”或“照料”义的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"tendency","ipa":"/ˈtendənsi/","tag":"noun","definition":"a regular inclination to behave in a certain way.","definitionCN":"以某种方式行事的经常性倾向。"},{"word":"tendentious","ipa":"/tenˈdenʃəs/","tag":"adjective","definition":"expressing a strong biased point of view. It comes from German Tendenz, not directly from English tend.","definitionCN":"表达强烈偏见的。出自德语 Tendenz，并非直接来自英语 tend。"},{"word":"tending","ipa":"/ˈtendɪŋ/","tag":"participle/noun","definition":"looking after; the act of caring for.","definitionCN":"照看；照料的行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"incline","ipa":"/ɪnˈklaɪn/","tag":"lean toward","definition":"to lean or be disposed toward something. It is more formal and more spatial than tend.","definitionCN":"向某物倾斜或有意向。比 tend 更正式、更空间化。"},{"word":"care for","ipa":"/keə fɔː/","tag":"look after","definition":"to look after someone's needs. It is the plain phrase for the 'tend' care sense.","definitionCN":"照看某人的需要。是“照料”义的朴素说法。"},{"word":"gravitate","ipa":"/ˈɡrævɪteɪt/","tag":"drift toward","definition":"to be drawn toward something as if by gravity. It stresses attraction rather than habit.","definitionCN":"如受重力吸引般趋向某物。强调吸引而非习惯。"}]}]},"mnemonics":{"normalIntro":{"en":"Real links: tendere 'stretch', attend shortened to tend, the tense/tension family, and the two-verb history.","cn":"真实联系：tendere“伸展”、attend 缩略为 tend、tense 与 tension 词族，以及“双动词”历史。"},"normal":[{"en":"Tendere means 'stretch'. Behaviour tends when it stretches toward one outcome rather than another.","cn":"tendere 意为“伸展”。行为 tend，就是朝某个结果而非另一个伸展。"},{"en":"The care sense is attend shortened: to tend a patient is to stretch your attention toward them.","cn":"照料义是 attend 的缩略：tend 病人，就是把注意力朝他们伸去。"},{"en":"Tend, tense, tension, tendon all go back to stretching. A tendon is a stretched cord.","cn":"tend、tense、tension、tendon 都回到“伸展”。肌腱就是一根被拉紧的索。"},{"en":"Tend to do = habit leans; tend a fire = attention stays. Context decides which verb you met.","cn":"tend to do 是习惯倾斜；tend a fire 是注意力留守。语境决定你遇到哪一个。"},{"en":"Intend and extend hide the same ten-: stretching the mind toward, or stretching out.","cn":"intend 与 extend 藏着同一个 ten-：把心思伸向，或向外伸展。"}],"abstract":[{"en":"A tendency is a future written into the present as a slope; tend names the slope without promising the destination.","cn":"倾向是写进当下的未来，形如斜坡；tend 命名坡度，却不承诺终点。"},{"en":"Care and inclination meet in attention: both are a stretching of the self toward something beyond it.","cn":"照料与倾向在“注意”处相遇：两者都是自我朝外物的伸展。"},{"en":"What we tend grows; what we merely intend does not. The hand matters more than the plan.","cn":"我们所照料的东西会生长；仅仅所意图的不会。手比计划更重要。"}]},"examples":[{"en":"Prices tend to rise before the holiday.","cn":"节前价格往往上涨。"},{"en":"A nurse tended him through the night.","cn":"一名护士整夜照料他。"},{"en":"The discussion tended toward the question of cost.","cn":"讨论逐渐转向成本问题。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"“探的”——探着身子往一个方向去，也探身照看病人 → tend 倾向、照料","word":"tend"},"root":"两个来源合流：“倾向”义出自拉丁 tendere“伸展”（经古法语 tendre）；“照料”义是 attend 的缩略，出自拉丁 attendere“留心”（ad- + tendere）。","sensesIntro":{"en":"Nine senses of tend, split between two histories: a stretching toward (inclination, direction, convergence) and an attention turned toward (care, herding, service). Both are forms of leaning out of oneself.","cn":"tend 的九个义项分属两段历史：朝某物伸展（倾向、方向、收敛）与把注意转向某物（照料、放牧、服侍）。两者都是自我向外倾。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line stretched toward a point, and a herder's gaze stretched toward a flock.","cn":"核心意象：一条朝某点伸展的线，与牧人朝羊群伸去的目光。"},"chain":["STRETCH","LEAN TOWARD","BE DISPOSED TO","MOVE IN A DIRECTION","APPROACH A LIMIT","TURN ATTENTION ON"],"branches":[{"senses":"01","en":"HABIT: behaviour leans in a predictable direction.","cn":"习惯：行为朝可预测的方向倾斜。"},{"senses":"03 · 09","en":"DIRECTION AND LIMIT: paths and sequences stretch toward a point.","cn":"方向与极限：路径与序列朝某点伸展。"},{"senses":"02 · 05","en":"CARE: attention is turned toward a person, a fire, or a machine that needs upkeep.","cn":"照料：注意力转向需要维护的人、炉火或机器。"},{"senses":"06 · 07 · 08","en":"SERVICE: bars, flocks, and lords are all kept by a presence that stays.","cn":"服侍：酒吧、羊群与领主，都靠一种留守的在场维持。"},{"senses":"04","en":"THE UNFINISHED MIND: a group can tend toward a view without having reached it.","cn":"未完成的心智：群体可以趋向某观点而尚未抵达。"}]},"affixes":{"intro":{"en":"Tend's English family splits along its two origins: tendency belongs to the 'stretch' verb, while attend and its derivatives belong to the 'heed' verb. The ten- root also gives tense, tension, tendon, intend, and extend.","cn":"tend 的英语词族沿两个来源分裂：tendency 属“伸展”动词，attend 及其派生属“留心”动词。ten- 词根还给出 tense、tension、tendon、intend、extend。"},"latinIntro":{"en":"Latin tendere 'stretch' has the participle tensus, source of tense and tension. Latin attendere 'stretch toward' is ad- plus tendere, and its French shortening gave the care sense of tend. The same *ten- root underlies tendon.","cn":"拉丁 tendere“伸展”的分词 tensus 是 tense 与 tension 的来源。拉丁 attendere“朝…伸展”是 ad- 加 tendere，其法语缩略给出 tend 的照料义。同一 *ten- 词根支撑 tendon。"},"items":[{"word":"tends","structure":"tend + -s (3sg)","meaning":"is likely to; looks after","meaningCN":"倾向于；照料（三单）","example":"she tends to worry","exampleCN":"她容易担心"},{"word":"tending","structure":"tend + -ing (participle)","meaning":"looking after; moving toward","meaningCN":"照料中的；趋向的（现在分词）","example":"tending the garden","exampleCN":"打理花园"},{"word":"tended","structure":"tend + -ed (past)","meaning":"looked after; inclined","meaningCN":"照料了；倾向了（过去式）","example":"he tended the sheep","exampleCN":"他放了羊"},{"word":"tendency","structure":"tend + -ency (noun)","meaning":"a regular inclination","meaningCN":"倾向；趋势（-ency 名词）","example":"a tendency to exaggerate","exampleCN":"夸张的倾向"},{"word":"tendentious","structure":"tend + -entious (adjective)","meaning":"biased, pushing a view","meaningCN":"有倾向性的；带偏见的（形容词）","example":"a tendentious account","exampleCN":"带偏见的叙述"},{"word":"attend","structure":"ad- + tendere (same root)","meaning":"to be present at; to give heed","meaningCN":"出席；留心（同根：ad-“朝向”）","example":"attend a meeting","exampleCN":"出席会议"},{"word":"extend","structure":"ex- + tendere (same root)","meaning":"to stretch out","meaningCN":"延伸；扩展（同根：ex-“向外”）","example":"extend the deadline","exampleCN":"延长截止期"},{"word":"intend","structure":"in- + tendere (same root)","meaning":"to stretch the mind toward; to plan","meaningCN":"打算；意图（同根：in-“向内”）","example":"intend to go","exampleCN":"打算去"},{"word":"tension","structure":"tensus + -ion (same root)","meaning":"the state of being stretched; strain","meaningCN":"紧张；张力（同根名词）","example":"muscle tension","exampleCN":"肌肉紧张"}],"latinEntries":[{"word":"tendere","structure":"Latin verb","meaning":"to stretch, extend, direct","meaningCN":"伸展；延伸；指向"},{"word":"tensus","structure":"past participle of tendere","meaning":"stretched, tense","meaningCN":"被拉紧的；紧绷的"},{"word":"attendere","structure":"ad- 'to' + tendere 'stretch'","meaning":"to stretch the mind toward; heed","meaningCN":"把心思伸向；留心"},{"word":"tendon","structure":"from Greek tenōn, related to *ten-","meaning":"a stretched cord","meaningCN":"肌腱；拉紧的索"}]}}]);
